["Here is an example of how you might implement this in C using POSIX threads for managing threads:

```c
#include <stdlib.h>
#include <pthread.h>
#include <assert.h>
#include <limits.h>

typedef struct {
    int value;
} record_t;

typedef struct {
    size_t count;
    long* offsets;
    int* keys;
    record_t** records;
    pthread_mutex_t mutex;
} record_array_t;

// A simple hash function
size_t custom_hash(int key, size_t size) {
    return (key % size + size) % size;  // Ensure the result is positive
}

record_array_t* create_records(size_t count, int min_value, int max_value) {
    assert(count <= INT_MAX);

    record_array_t* array = malloc(sizeof(record_array_t));
    if (!array) return NULL;

    array->count = count;
    array->offsets = malloc(sizeof(long) * count);
    array->keys = malloc(sizeof(int) * count);
    array->records = calloc(count, sizeof(record_t*));  // Initialize to NULL pointers

    if (!array->offsets || !array->keys || !array->records) {
        free(array->offsets);
        free(array->keys);
        free(array->records);
        free(array);
        return NULL;
    }

    // Initialize the arrays and records
    for (size_t i = 0; i < count; ++i) {
        array->offsets[i] = rand();
        array->keys[i] = rand() % (max_value - min_value + 1) + min_value;  // Random key within the specified range

        record_t* record = malloc(sizeof(record_t));
        if (!record) {
            free(array->offsets);
            free(array->keys);
            for (size_t j = 0; j < i; ++j) free(array->records[j]);  // Free any already allocated records
            free(array->records);
            free(array);
            return NULL;
        }

        record->value = rand() % (max_value - min_value + 1) + min_value;  // Random value within the specified range
        array->records[i] = record;
    }

    pthread_mutex_init(&array->mutex, NULL);

    return array;
}

void destroy_records(record_array_t* array) {
    assert(array != NULL);

    for (size_t i = 0; i < array->count; ++i) free(array->records[i]);

    pthread_mutex_destroy(&array->mutex);
    free(array->offsets);
    free(array->keys);
    free(array->records);
    free(array);
}
```
In this code, a `record_t` struct is used to hold the data for each record. An array of these records is maintained in a larger structure (`record_array_t`) which also holds the offset and key arrays. The function `create_records` is responsible for allocating memory for all these arrays, and initializing them with random numbers.

The use of POSIX threads' mutexes ensures that only one thread can access the shared data at a time, providing synchronization between threads.

Please note that this code doesn't handle potential collisions in the hash function or when allocating memory for arrays and records. These aspects would need to be addressed in a production-quality implementation. For simplicity, they were left out of this example.
"]

