#include <errno.h>
#include <pthread.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <limits.h>
#include <stdlib.h>
#define MAX_LINE_LENGTH 1024

typedef struct LineNode {
    char line[MAX_LINE_LENGTH];
    struct LineNode *next;
} LineNode;

// Globals
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
LineNode* head = NULL;
int totalLines = 0;
char outputFile[PATH_MAX] = "";
int maxLength = INT_MAX;
FILE *logfile;

void usage() {
    printf("Usage: ./program [--manpage | -cs | -o output_file] input_file\n");
}

int validateInput(char* filename) {
    struct stat buffer;
    return (stat(filename, &buffer) == 0);
}

void processLine(char *line) {
    if (!head) {
        head = malloc(sizeof(LineNode));
        strncpy(head->line, line, MAX_LINE_LENGTH - 1);
        head->next = NULL;
    } else {
        LineNode *current = head;
        while (current->next) {
            current = current->next;
        }
        current->next = malloc(sizeof(LineNode));
        strncpy(current->next->line, line, MAX_LINE_LENGTH - 1);
        current->next->next = NULL;
    }
}

void *processLinesInThread(void *arg) {
    LineNode* node = (LineNode*) arg;
    while (node) {
        pthread_mutex_lock(&lock);
        ++totalLines;
        if (outputFile[0] != '\0') {
            fprintf(logfile, "%s\n", node->line);
        }
        pthread_mutex_unlock(&lock);
        LineNode* temp = node;
        node = node->next;
        free(temp);
    }
    return NULL;
}

int main(int argc, char **argv) {
    logfile = fopen("log.txt", "w");
    if (!logfile) {
        perror("Failed to open log file");
        exit(-1);
    }
    // Parse command line arguments
    for (int i = 0; i < argc; ++i) {
        if (strcmp(argv[i], "--manpage") == 0 || strcmp(argv[i], "-cs") == 0) {
            usage();
            return 1;
        } else if (strncmp(argv[i], "-o", 2) == 0) {
            strncpy(outputFile, argv[++i], PATH_MAX - 1);
        } else if (!validateInput(argv[i])) {
            perror("Invalid file");
            return 1;
        } else {
            FILE *file = fopen(argv[i], "r");
            if (!file) {
                perror("Failed to open file");
                return 1;
            }
            char line[MAX_LINE_LENGTH];
            while (fgets(line, MAX_LINE_LENGTH, file)) {
                processLine(line);
            }
        }
    }
    pthread_t threadId;
    if (pthread_create(&threadId, NULL, &processLinesInThread, head) != 0) {
        perror("Failed to create thread");
        return 1;
    }
    pthread_join(threadId, NULL);
    printf("%d\n", totalLines);
    fclose(logfile);
    return 0;
}
```
