int dnsResolve(char hostname[], u_char ip[]) {
    pthread_mutex_lock(&mutex);

    // Check if IP already in cache (not shown here, would need to be implemented separately)
    if(isInCache(ip)) {
        pthread_mutex_unlock(&mutex);
        return 0;
    }

    struct addrinfo hints, *res = NULL;
    int errcode;
    char addrstr[INET6_ADDRSTRLEN];
    void *ptr;

    memset (&hints, 0, sizeof(hints));
    hints.ai_family = PF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_flags |= AI_CANONNAME;

    errcode = getaddrinfo (hostname, NULL, &hints, &res);
    if(errcode != 0) {
        pthread_mutex_unlock(&mutex);
        return 1; // Error
    }

    while(res) {
        inet_ntop (res->ai_family, res->ai_addr->sa_data, addrstr, sizeof(addrstr));

        switch(res->ai_family) {
            case AF_INET:
                ptr = &((struct sockaddr_in *) res->ai_addr)->sin_addr;
                inet_ntop (res->ai_family, ptr, addrstr, sizeof(addrstr));
                break;
            case AF_INET6:
                ptr = &((struct sockaddr_in6 *) res->ai_addr)->sin6_addr;
                inet_ntop (res->ai_family, ptr, addrstr, sizeof(addrstr));
                break;
        }

        // Check if the resolved IP is in trusted domain list (not shown here)
        if(!isTrustedDomain(addrstr)) {
            pthread_mutex_unlock(&mutex);
            return 2; // Non-trusted domain
        }

        res = res->ai_next;
    }

    freeaddrinfo(res);

    // Add resolved IP to cache (not shown here)
    addToCache(ip);

    pthread_mutex_unlock(&mutex);
    return 0; // Success
}
