#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

int* read_integers(size_t *n) {
    int i;
    size_t capacity = 1024, *new_ptr;

    int *arr = malloc(capacity * sizeof(*arr));  // allocate initial memory
    if (arr == NULL) return NULL;  

    for (*n=0; scanf("%d", &i) == 1; ++*n) {
        if (*n >= capacity) { 
            capacity *= 2;
            new_ptr = realloc(arr, capacity * sizeof(*new_ptr)); // double size of memory
            if (new_ptr == NULL){
                free(arr);  
                return NULL;
            } else arr = new_ptr;
        }

        arr[*n] = i;  // store the integer in the array
    }

    return arr;
}

int findMax(int *arr, size_t n) {  
    int max = INT_MIN;  
    for (size_t i = 0; i < n; ++i)
        if (arr[i] > max) 
            max = arr[i];

    return max;
}

int main() {
    size_t count;
    int *data = read_integers(&count);  
    if (!data) {
        fprintf(stderr, "Memory allocation error or input was non-integer.\n");
        return EXIT_FAILURE;
    } else if (count == 0) {  // check for empty input
        printf("No integers were entered.\n");
    } else {  
        int max = findMax(data, count);
        printf("The largest integer is: %d\n", max);
    }

    free(data);  // release the memory block after use
    return EXIT_SUCCESS;
}
```
