['```c
#include <stdio.h>
#include <semaphore.h>
#include <pthread.h>

typedef struct {
    sem_t mutex;
    int count;
} ResourcePool;

void initializeResourcePool(ResourcePool *pool, int initialCount) {
    sem_init(&pool->mutex, 0, 1);
    pool->count = initialCount;
}

int acquireResources(ResourcePool *pool, int amount) {
    sem_wait(&pool->mutex);
    if (amount <= pool->count) {
        pool->count -= amount;
        FILE *logFile = fopen("audit.log", "a");
        fprintf(logFile, "Acquired %d resources, remaining: %d\n", amount, pool->count);
        fclose(logFile);
        sem_post(&pool->mutex);
        return 0;
    } else {
        FILE *logFile = fopen("audit.log", "a");
        fprintf(logFile, "Failed to acquire %d resources, remaining: %d\n", amount, pool->count);
        fclose(logFile);
        sem_post(&pool->mutex);
        return -1;
    }
}

void releaseResources(ResourcePool *pool, int amount) {
    sem_wait(&pool->mutex);
    pool->count += amount;
    FILE *logFile = fopen("audit.log", "a");
    fprintf(logFile, "Released %d resources, remaining: %d\n", amount, pool->count);
    fclose(logFile);
    sem_post(&pool->mutex);
}

void cleanupResourcePool(ResourcePool *pool) {
    FILE *logFile = fopen("audit.log", "a");
    fprintf(logFile, "Clean up: remaining resources %d\n", pool->count);
    fclose(logFile);
    sem_destroy(&pool->mutex);
}
```
