#include <vector>
#include <algorithm>

void insertAndSort(std::vector<int>& v, int num1, int num2) {
    auto it = std::find(v.begin(), v.end(), num1);

    if (it != v.end()) {
        v.insert(++it, num2);
    } else {
        v.push_back(num2);
    }

    std::sort(v.begin(), v.end());
}
