    SandeshClient() {}
    ~SandeshClient() {
        io_service_.stop();
        threads_.join_all();
    }

    void SendRequest(const std::string& url) {
        // Simulate a network latency between 0ms and 500ms
        boost::posix_time::milliseconds workTime(rand() % 501);
        boost::this_thread::sleep(workTime);

        try {
            std::string response = MakeGetRequest(url);

            // Store the response in thread-local storage mechanism
            StoreResponseInThreadLocalStorage(response);

            // Log successful requests
            LogSuccessfulRequest();
        } catch (const boost::system::system_error& err) {
            if (err.code() == boost::asio::error::timed_out) {
                // Handle timeout exception
                HandleTimeoutException(url);
            } else {
                // Log internal errors
                LogInternalError();
            }
        } catch (const std::exception& e) {
            // Log proxy sessions
            LogProxySession();
        }
    }

    void Start() {
        for(int i = 0; i < CalculateConcurrencyLevel(); ++i) {
            threads_.create_thread(boost::bind(&SandeshClient::Run, this));
        }

        threads_.join_all();
    }

private:
