```cpp
#include <mutex>
#include <random>
#include <memory>
#include <iostream>

namespace CustomRng {
    class RNGFactory;

    class Distribution {
    public:
        virtual ~Distribution() = default;

        // Pure Virtual Function to be overriden by derived classes
        virtual double generateNumber(std::mt19937& generator) = 0;
    };

    class UniformDistribution : public Distribution {
    private:
        std::uniform_real_distribution<double> dist;

    public:
        explicit UniformDistribution() 
            : dist(0.0, 1.0) {}

        double generateNumber(std::mt19937& generator) override {
            return dist(generator);
        }
    };

    class NormalDistribution : public Distribution {
    private:
        std::normal_distribution<double> dist;

    public:
        explicit NormalDistribution() 
            : dist(0.0, 1.0) {}

        double generateNumber(std::mt19937& generator) override {
            return dist(generator);
        }
    };

    class RNGFactory {
    private:
        static std::mutex mtx;
        static std::random_device rd;  // Will be used to obtain a seed for the random number engine
        static std::mt19937 generator; // Standard mersenne_twister_engine seeded with rd()

    public:
        static void setSeed(const unsigned int newSeed) {
            std::lock_guard<std::mutex> lock(mtx);
            generator.seed(newSeed);
        }

        static double getRandomNumber(Distribution& distr) {
            std::lock_guard<std::mutex> lock(mtx);
            return distr.generateNumber(generator);
        }
    };

    // Initialize static member variables outside class definition
    std::random_device RNGFactory::rd; 
    std::mt19937 RNGFactory::generator(RNGFactory::rd());
    std::mutex RNGFactory::mtx;
}
```

This code creates a thread-safe random number generator factory with support for different distributions (Uniform and Normal). It uses the 'std::mt19937' type from the 'random' header to implement the random number generator. The class hierarchy is designed in such a way that new distribution classes can be easily added in future by just creating a derived class of Distribution and overriding generateNumber().
"]

