public class CustomException : Exception
{
    public CustomException(string message) : base(message) { }
}

public static XmlNode GetFirstMatchingElement(string xml, string xpathQuery)
{
    try
    {
        var doc = new XmlDocument();
        doc.LoadXml(xml);

        var navigator = doc.CreateNavigator();
        var iterator = navigator.Select(xpathQuery);

        if (!iterator.MoveNext()) throw new CustomException("No matching element found");

        XmlNode node = (XmlNode)iterator.Current;

        while (iterator.MoveNext()) 
            throw new CustomException("Multiple elements with the same name found");

        return node;
    }
    catch (XmlException ex)
    {
        throw new CustomException("Malformed XML document", ex);
    }
}
