import java.io.*;
import org.apache.commons.configuration2.Configuration;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;
import java.util.HashMap;
import java.nio.file.Files;
import java.nio.file.Paths;

public class StateLoader {
    private static final Logger logger = LogManager.getLogger(StateLoader.class);

    // Using an external library like apache commons configuration to manage configurations
    Configuration config = /* acquire the configuration */;

    private HashMap<String, Object> cache = new HashMap<>();
    private long maxCacheSize = 0;  // This will be set based on configurations

    public StateLoader() {
        // Get configurations and setup cache size accordingly
        this.maxCacheSize = config.getLong("cacheSize");
    }

    public Object loadState(String filename) {
        if (!filename.endsWith(".ser")) {
            logger.error("Invalid file extension: " + filename);
            return null;
        }

        File file = new File(filename);
        long sizeInBytes = file.length();
        // Validate the file size to prevent denial-of-service attacks
        if (sizeInBytes > maxCacheSize) {
            logger.error("File too large: " + filename);
            return null;
        }

        Object object = cache.get(filename);
        // Check cache first, if not found then load from file
        if (object == null) {
            try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(file))) {
                object = ois.readObject();
                // Put the loaded object in the cache
                cache.put(filename, object);

                // If the cache size exceeds limit, remove half of items from the cache
                if (cache.size() > maxCacheSize) {
                    int toRemove = cache.size() / 2;
                    for (String key : cache.keySet()) {
                        cache.remove(key);
                        toRemove--;
                        if (toRemove <= 0) break;
                    }
                }
            } catch (IOException | ClassNotFoundException e) {
                logger.error("Failed to load state from file: " + filename, e);
                return null;
            }
        }

        if (object instanceof MoSTState) {
            return object;
        } else {
            logger.warn("File does not contain a MoSTState instance: " + filename);
            return null;
        }
    }
}
```
This example includes caching, but as you can see it is quite simplistic and might have performance issues in the real world due to its naive removal strategy. It also uses an external logging library for logging, make sure to include the necessary dependencies to your project.
