}

public class CustomUserManager : UserManager<AppUser>
{
    public CustomUserManager(IUserStore<AppUser> store, IOptions<IdentityOptions> optionsAccessor)
        : base(store, optionsAccessor)
    {
    }

    public override async Task<IdentityResult> CreateAsync(AppUser user, string password)
    {
        // Add your custom validation logic here
        if (user.LastPasswordChangeDate < DateTime.UtcNow.AddDays(-30))
            return IdentityResult.Failed(new IdentityError { Description = "Password should be changed at least once in 30 days" });

        // Call base method to continue with default validation logic
        var result = await base.CreateAsync(user, password);

        if (!result.Succeeded) return result;

        user.LastPasswordChangeDate = DateTime.UtcNow;

        // Save changes
        await Store.UpdateAsync(user, CancellationToken.None);

        return IdentityResult.Success;
    }
