const readline = require('readline');
const fs = require('fs');
const axios = require('axios');

// Example configuration object with regular expressions for book names
const config = {
  booksRegex: /(Genesis|Exodus|Leviticus|Numbers|Deuteronomy)/g,
  logProgress: false,
  verifyAgainstDB: true
};

// URL of external API to fetch Old Testament book names for verification
const apiURL = 'http://example.com/api';

async function extractBooks(filePath, config) {
  const lineReader = readline.createInterface({
    input: fs.createReadStream(filePath),
  });

  let booksCountObj = {};
  let counter = 0;

  if (config.logProgress) console.time('Processing time');

  for await (const line of lineReader) {
    const booksInLine = [...line.matchAll(config.booksRegex)].map(m => m[1]);

    for (let bookName of booksInLine) {
      if (!booksCountObj[bookName]) {
        booksCountObj[bookName] = 0;
      }

      booksCountObj[bookName]++;
    }

    counter += line.length;

    if (config.logProgress) console.log(`Processed ${counter} characters`);
  }

  if (config.verifyAgainstDB) {
    const response = await axios.get(apiURL);
    const verifiedBooksCountObj = {};

    for (let bookName in booksCountObj) {
      if (response.data.includes(bookName)) {
        verifiedBooksCountObj[bookName] = booksCountObj[bookName];
      }
    }

    return verifiedBooksCountObj;
  } else {
    return booksCountObj;
  }
}
```
This JavaScript function `extractBooks` reads a large text file line by line using node.js's readline module, which provides an efficient streaming approach for handling large inputs. It also utilizes async/await syntax and Promises to handle asynchronous operations like the database fetch via Axios.
