function renderWidgets(widgetData, containerId) {
    // Get the container element
    var container = document.getElementById(containerId);

    if (!container || !Array.isArray(widgetData)) {
        return "Invalid input";
    }

    widgetData.forEach((widget) => {
        // Create a div for each widget
        var widgetDiv = document.createElement('div');

        if (typeof widget === 'object' && 
            widget !== null && 
            typeof widget.icon === 'string' && 
            typeof widget.title === 'string' && 
            typeof widget.description === 'string') {

            // Create elements for icon, title and description
            var icon = document.createElement('img');
            icon.src = widget.icon;
            var title = document.createElement('h3');
            title.textContent = widget.title;
            var desc = document.createElement('p');
            desc.textContent = widget.description;

            // Toggle visibility of the description when title is clicked
            title.addEventListener('click', function() {
                if (desc.style.display === 'none') {
                    desc.style.display = '';
                } else {
                    desc.style.display = 'none';
                }
            });

            // Append elements to the widget div
            widgetDiv.appendChild(icon);
            widgetDiv.appendChild(title);
            widgetDiv.appendChild(desc);

            // Calculate total height after adding this widget
            var totalHeight = Array.from(container.children).reduce((total, child) => {
                return total + child.offsetHeight;
            }, 0) + widgetDiv.offsetHeight;

            // Only add the widget if it doesn't exceed the max height
            if (totalHeight <= 500) {
                container.appendChild(widgetDiv);
            }
        }
    });

    return container.innerHTML;
}
