/**
 * Copies bytes from a list of buffers to a new buffer without modifying the original.
 * 
 * @param {ArrayBuffer[]} chunks - List of ArrayBuffers containing data.
 * @param {number} byteCount - Number of bytes to copy.
 * @param {string|null} checksum - Checksum to validate the copied data against. If null, no validation is done.
 * @return {ArrayBuffer} A new buffer containing the specified number of bytes from the original buffers.
 */
function copyBytes(chunks, byteCount, checksum) {
    console.time('copy operation'); // Logging start time of the operation

    let copiedBytes = 0;
    const totalChunkSize = chunks.reduce((acc, chunk) => acc + chunk.byteLength, 0);

    if (byteCount > totalChunkSize) {
        byteCount = totalChunkSize; // Can't copy more bytes than available. Clamp to maximum possible.
    }

    const newBuffer = new ArrayBuffer(byteCount);
    const newView = new Uint8Array(newBuffer);

    for (let i = 0, j = 0; copiedBytes < byteCount; i++) {
        if (i >= chunks[j].byteLength) { // If we've reached the end of this chunk.
            j++;
            i = 0; // Reset to start of next chunk.
        } else {
            newView[copiedBytes] = chunks[j][i]; // Copy byte from old buffer into new one.

            copiedBytes++;
        }
    }

    if (checksum !== null) {
        const checksumValidationResult = validateChecksum(newBuffer, checksum);

        if (!checksumValidationResult) {
            console.error('Data integrity check failed');

            return null; // Return null to indicate validation failure.
        }
    }

    console.timeEnd('copy operation'); // Logging end time of the operation

    return newBuffer;
}

/**
 * Validates the checksum of data in a buffer.
 * 
 * @param {ArrayBuffer} buffer - The buffer containing the data to validate.
 * @param {string} expectedChecksum - The checksum against which to validate.
 * @return {boolean} True if the checksums match, false otherwise.
 */
function validateChecksum(buffer, expectedChecksum) {
    // This is a stub for the actual implementation of this function, which would likely be more complex and dependent on the specifics of your checksum algorithm.
    const calculatedChecksum = calculateChecksum(new Uint8Array(buffer));

    return calculatedChecksum === expectedChecksum;
}
```

