function updateWeatherData($apiKey, $location) {
    try {
        // Call third-party API to get weather data
        $ch = curl_init('http://api.weatherapi.com/v1/current.json?key='.$apiKey.'&q='.urlencode($location));
        curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
        $response = curl_exec($ch);

        // Handle network errors
        if (curl_errno($ch)) {
            error_log('Network error: ' . curl_error($ch));
            return false;
        }

        // Decode JSON response
        $weatherData = json_decode($response, true);

        // Check for errors in API response
        if (isset($weatherData['error'])) {
            error_log('API error: ' . $weatherData['error']['message']);
            return false;
        }

        // Connect to database
        $db = new PDO('mysql:host=localhost;dbname=weather', 'username', 'password');

        // Implement caching strategies (here we use a simple file-based cache)
        $cacheFile = '/path/to/cache.json';
        $cacheData = json_decode(file_get_contents($cacheFile), true);

        if (!is_array($cacheData)) {
            $cacheData = array();
        }

        $currentTime = time();
        // Check if data is already in cache and not older than 5 minutes
        if (isset($cacheData[$location]) && $cacheData[$location]['timestamp'] > $currentTime - 300) {
            return 'Success: Data fetched from cache';
        } else {
            $query = "INSERT INTO weather_data 
                      (location, temperature, humidity, windspeed, timestamp) 
                      VALUES (?, ?, ?, ?, ?)";

            // Prepare the query
            $stmt = $db->prepare($query);
            $stmt->execute([
                $location,
                $weatherData['current']['temp_c'],
                $weatherData['current']['humidity'],
                $weatherData['current']['wind_kph'],
                $currentTime
            ]);

            // Update cache
            $cacheData[$location] = [
                'temperature' => $weatherData['current']['temp_c'],
                'humidity' => $weatherData['current']['humidity'],
                'windspeed' => $weatherData['current']['wind_kph'],
                'timestamp' => $currentTime
            ];

            file_put_contents($cacheFile, json_encode($cacheData));
        }

    } catch (PDOException $e) {
        // Log any database errors
        error_log('Database error: ' . $e->getMessage());
        return false;
    }

    return 'Success: Data updated and cached';
}
```
