<?php
class AuthManager {
    private $session;
    private $oauthClient;
    private $userStorage;

    function __construct(SessionInterface $session, OAuth2ClientInterface $oauthClient, UserStorageInterface $userStorage) {
        $this->session = $session;
        $this->oauthClient = $oauthClient;
        $this->userStorage = $userStorage;

        if (!$this->session->has('access_token') || $this->session->get('expiry_time') < time()) {
            $this->refreshToken();
        }
    }

    function refreshToken() {
        $response = $this->oauthClient->requestAccessToken($this->session->get('refresh_token'));

        if ($response['access_token']) {
            $this->session->set('access_token', $response['access_token']);
            $this->session->set('expiry_time', time() + $response['expires_in']);
            // save the refresh token in a secure storage like secure cookie or database
            $this->session->set('refresh_token', $response['refresh_token']);
        } else {
            throw new Exception('Failed to refresh access token');
        }
    }

    function getUserData() {
        $accessToken = $this->session->get('access_token');

        if (!$this->userStorage->has($accessToken)) {
            $response = $this->oauthClient->requestResourceOwnerDetails($accessToken);

            if ($response['data']) {
                $this->userStorage->store($accessToken, $response['data']);
            } else {
                throw new Exception('Failed to get user data');
            }
        }

        return $this->userStorage->get($accessToken);
    }

    function redirectToDashboard() {
        $userData = $this->getUserData();
        $dashboardUrl = 'https://' . $userData['tenant_id'] . '.yourapp.com/dashboard';

        header('Location: ' . $dashboardUrl);
        exit;
    }
}
?>
