class UserDao {
    private $pdo; // PDO instance for database connection

    public function __construct(PDO $pdo) {
        $this->pdo = $pdo;
    }

    public function updatePassword($userId, $newPassword) {
        if (!$this->isValidPassword($newPassword)) {
            throw new Exception('Invalid password');
        }

        // Begin transaction to ensure atomicity of operation
        $this->pdo->beginTransaction();

        try {
            $stmt = $this->pdo->prepare("UPDATE users SET password = ? WHERE id = ?");
            $hashedPassword = $this->hashPassword($newPassword); // Implement hashing method depending on your use case

            if (!$stmt->execute([$hashedPassword, $userId])) {
                throw new Exception('Failed to update password');
            }

            $affectedRows = $stmt->rowCount();

            // Handle the case where no rows are affected (e.g., invalid user ID)
            if ($affectedRows == 0) {
                throw new Exception('User not found');
            }

            // End of transaction, commit to ensure changes are saved
            $this->pdo->commit();

        } catch (Exception $e) {
            // In case of any error during execution, rollback the transaction
            $this->pdo->rollBack();
            throw $e;
        }
    }

    private function isValidPassword($password) {
        // Implement password strength check according to business rules
        if (strlen($password) < 8) return false;

        if (!preg_match('/[A-Za-z].*[0-9]|[0-9].*[A-Za-z]/', $password)) return false;

        // Add more rules as per requirements

        return true;
    }

    private function hashPassword($password) {
        // Implement your password hashing method (e.g., bcrypt, argon2 etc.)
        return password_hash($password, PASSWORD_DEFAULT);
    }
}
