#define MAX_STATES 100000
typedef struct State{
    int stateId;
    void* transitionFunction; // you will need to define this in accordance with your FSA configuration
    struct State *nextState;
} State;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
State* createFSA(int* states, int numberOfStates, void* fsaConfiguration){
    if (numberOfStates > MAX_STATES) return NULL;

    State *lastStateInList = malloc(sizeof(State));
    if (!lastStateInList) return NULL; // out of memory

    lastStateInList->stateId = states[0];
    // initialize other members as per your FSA configuration

    for (int i = 1; i < numberOfStates; ++i){
        State *newState = malloc(sizeof(State));
        if (!newState) {
            freeFSA(lastStateInList);
            return NULL; // out of memory
        }

        newState->stateId = states[i];
        // initialize other members as per your FSA configuration

        lastStateInList->nextState = newState;
        lastStateInList = newState;
    }

    return lastStateInList;
}

void freeFSA(State *head){
    if (!head) return;

    freeFSA(head->nextState); // first we have to go to the end of the list

    pthread_mutex_lock(&lock);

    free(head);

    pthread_mutex_unlock(&lock);
}
```
Note: The function `freeFSA` is called recursively from within itself in order to reach the last state and free it. It's also thread-safe since `pthread_mutex_t` is used for ensuring only one thread at a time can delete a FSA state node.

