["Here is a simple implementation of an Octree data structure in C++:

```cpp
#include <vector>
#include <cmath>

struct Point {
    float x;
    float y;
    float z;
};

class Node {
public:
    std::vector<Node*> children; 
    std::vector<Point*> data;
    int capacity;

    Node(int cap) : capacity(cap), children(8, nullptr) {}

    ~Node() {
        for (auto child : children) delete child;
    }
};

class Octree {
private:
    Node* root;
    int max_depth;
    float feature_size;
public:
    Octree(float fs, int mdc, int depth = 5) 
        : root(new Node(mdc)), max_depth(depth), feature_size(fs) {}

    ~Octree() { delete root; }

    void insert(Point* p, int depth = 0, Node* node = nullptr) {
        if (!node) node = root;  // Starting from the root if not specified

        // Check to see if this is a leaf node
        if (depth == max_depth) {
            node->data.push_back(p);
            return;
        }

        int index = 0;  // Compute the child's index based on the point
        for (int i=0; i<3; ++i) if (p[i] > feature_size / pow(2, depth)) index |= 1 << i;

        // If this node is a leaf, create children and insert data into them
        if (!node->children[index]) {
            node->children[index] = new Node(root->capacity);
        } 

        insert(p, depth+1, node->children[index]);  // Recursively insert the point
    }
};
```

Please note that this is a simplified version of an Octree. It doesn't include many features found in a full implementation such as node merging, memory management for dynamic data sources, or optimized access times. You may need to modify it according to your specific requirements. Also, remember to manage the memory correctly and make sure you handle all edge cases that can arise from using this structure in a simulation environment.
