["Sure, here's a simplified version of how you might implement this in C:

```c
#include <stdio.h>
#include <time.h>
#define WINDOW_SIZE 5
#define THRESHOLD 10
#define DECAY_FACTOR 0.9

typedef struct {
    int id;
    time_t timestamp;
    double value;
} Transaction;

double weightedSum = 0.0;
int totalProcessed = 0, discardedByAge = 0, discardedByRate = 0;
Transaction window[WINDOW_SIZE];
size_t startIndex = 0, endIndex = 0;
time_t lastUpdateTime = -1;
double maxWeightedSum = 0.0;
int maxWeightedId = -1;

void processTransaction(Transaction transaction) {
    time_t currentTime = time(NULL);
    double decayFactor = pow(DECAY_FACTOR, difftime(currentTime, lastUpdateTime));

    if (difftime(transaction.timestamp, currentTime) > WINDOW_SIZE) {
        discardedByAge++;
        return;
    }

    while (endIndex != startIndex && difftime(currentTime, window[startIndex].timestamp) >= WINDOW_SIZE) {
        weightedSum -= decayFactor * window[startIndex].value;
        startIndex = (startIndex + 1) % WINDOW_SIZE;
    }

    if ((endIndex + 1) % WINDOW_SIZE == startIndex) {
        discardedByRate++;
        return;
    }

    window[endIndex] = transaction;
    weightedSum = decayFactor * weightedSum + transaction.value;
    endIndex = (endIndex + 1) % WINDOW_SIZE;

    if(difftime(currentTime, lastUpdateTime) >= 3) {
        if(weightedSum > maxWeightedSum) {
            maxWeightedSum = weightedSum;
            maxWeightedId = transaction.id;
        }
        lastUpdateTime = currentTime;
    }

    totalProcessed++;
}
```
This code is a simplified version of what you asked for and it doesn't account for multiple threads accessing the shared resources, or managing time in more precise manner (e.g., using `CLOCK_MONOTONIC`), but I hope this gives you an idea on how to approach your problem in C.
