char *addSlash(const char *input, size_t limit, size_t bufferSize) {
    if (!input) return NULL;  // Handle null pointers gracefully

    size_t inputLen = strlen(input);

    if (inputLen > limit || inputLen + 2 > bufferSize) return NULL;  // If input string exceeds the size limit or total length exceeds the maximum buffer size, return NULL.

    char *output = malloc((bufferSize - 1) * sizeof(char));  // Allocate memory for output string based on the maximum buffer size minus one byte to accommodate the slash.

    if (!output) return NULL;  // Handle memory allocation errors

    strncpy(output, input, limit);  // Copy limited number of characters from input string.

    if (inputLen >= limit && bufferSize > 0) output[bufferSize-2] = '\0';  // If the total length exceeds the maximum buffer size and the buffer size is nonzero, null-terminate the resulting string to fit within the buffer size limit.

    strcat(output, "/");  // Append slash to the end of the output string.

    return output;
}
