['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main() {
    FILE *file = fopen("large_text_file.txt", "r");
    if (file == NULL) {
        printf("Could not open file.\n");
        return 1;
    }

    FILE *logFile = fopen("process_logs.txt", "w");
    if (logFile == NULL) {
        printf("Could not create log file.\n");
        return 1;
    }

    char *line = NULL;
    size_t len = 0;
    ssize_t read;

    int totalLines = 0, totalLength = 0;
    while ((read = getline(&line, &len, file)) != -1) {
        totalLines++;
        totalLength += strlen(line);

        char *field = strtok(line, " ");
        float weightedAverage = 0;
        int i = 0;
        while (field != NULL) {
            if (i >= 3) {
                float value = atof(field);
                weightedAverage += value * (4 - i);  // weights are 1, 2, and 3
            }
            field = strtok(NULL, " ");
            i++;
        }

        if (i >= 3) {
            weightedAverage /= ((float)(i-2)/2 * (i-1));  // normalizing factor is sum of weights divided by weight times number of fields
        } else {
            fprintf(logFile, "Skipping line with less than three fields\n");
            continue;
        }

        fseek(file, -strlen(line), SEEK_CUR);  // rewind file pointer to the start of the line
        while (fgetc(file) != '\n') {  // read and print fields until end of line
            float value;
            if (fscanf(file, "%f", &value) == 1) {
                fprintf(logFile, "%.2f, ", value);  // print to log file with two decimal places
            } else {
                fprintf(logFile, "Error reading field\n");
            }
        }

        fprintf(logFile, "%.2f\n", weightedAverage);  // print weighted average to log file
    }

    float avgLength = (float)totalLength / totalLines;
    fclose(file);
    fprintf(logFile, "Total number of lines: %d\n", totalLines);
    fprintf(logFile, "Average line length: %.2f\n", avgLength);
    fclose(logFile);

    free(line);
    return 0;
}
```
