    if (!TIFFGetField(tiffFile, TIFFTAG_BITSPERSAMPLE, &imageInfo.bitsPerSample)) {
        handleError("Failed to get bits per sample");
    }
    if (imageInfo.bitsPerSample != 1 && imageInfo.bitsPerSample != 2 && 
        imageInfo.bitsPerSample != 4 && imageInfo.bitsPerSample != 8 && imageInfo.bitsPerSample != 16) {
        handleError("Unsupported bit depth");
    }

    if (!TIFFGetField(tiffFile, TIFFTAG_SAMPLESPERPIXEL, &imageInfo.samplesPerPixel)) {
        handleError("Failed to get samples per pixel");
    }

    if (TIFFGetField(tiffFile, TIFFTAG_EXTRASAMPLES, &imageInfo.extraSamplesCount)) {
        imageInfo.extraSamplesDetails = malloc(sizeof(uint16) * imageInfo.extraSamplesCount);
        if (!TIFFGetField(tiffFile, TIFFTAG_EXTRASAMPLESPERPIXEL, imageInfo.extraSamplesDetails)) {
            handleError("Failed to get extra samples details");
        }
    }

    return imageInfo;
}

EVP_CIPHER_CTX* performEncryption(char *option) {
