int convert_video(char *input, char *outputDir, char *codec) {
    struct stat st = {0};

    // Check if the output directory exists
    if (stat(outputDir, &st) == -1) {
        mkdir(outputDir, 0700);
    }

    int len_input = strlen(input);
    int len_codec = strlen(codec);

    char *output = malloc(len_input + len_codec + 2); // 2 for the dot and null terminator
    if (output == NULL) {
        return 1; // Failed to allocate memory
