    strncat(output, codec, len_codec); // Append the new file extension

    char command[256]; // Command buffer
    snprintf(command, sizeof(command), "ffmpeg -i %s %s/%s", input, outputDir, output); 

    int ret = system(command); // Run the ffmpeg command

    free(output);

    return ret == 0 ? 0 : 1; // Return success if ffmpeg ran successfully
}
