static int authenticateUser(Session *session) {
    if (!session || !session->user || !session->connection || !session->failureCb) return -1; // Null pointer check

    pthread_mutex_lock(&session->lock);

    if (session->initialized && session->user->token && 
        strlen(session->connection->hostAddress) > 0) {
        pthread_mutex_unlock(&session->lock);
        return 0; // Authentication successful
    }

    if (!session->initialized || !session->user->token || strlen(session->connection->hostAddress) == 0) {
        session->failureCb(-1); // Default callback for authentication failures

        pthread_mutex_unlock(&session->lock);
        return -2; // Failed to reinitialize connection or handle failure
    }

    if (!reinitializeConnection(session)) {
        session->failureCb(-1); // Default callback for authentication failures

        pthread_mutex_unlock(&session->lock);
        return -3; // Failed to reinitialize connection
    }

    session->initialized = true;

    pthread_mutex_unlock(&session->lock);
    return 0; // Authentication successful after reinitialization
}
