```C
#include <stdbool.h>
#include <string.h>
#include <json-c/json.h>
#include <regex.h>

/* regex for UUID */
const char* uuid_pattern = "^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$";

bool validate_oauth_response(const char* json_str, int *error) {
    regex_t uuid_regex;

    if (regcomp(&uuid_regex, uuid_pattern, REG_EXTENDED|REG_NOSUB)) {
        /* If the regex could not be compiled, report an error */
        *error = -1;
        return false;
    }

    struct json_object *jobj = json_tokener_parse(json_str);

    if(!jobj) {
        /* Invalid JSON, report the error */
        *error = 1;
        return false;
    }

    struct json_object *access_token, *expires_in, *token_type, *refresh_token = NULL;

    if(!json_object_object_get_ex(jobj, "access_token", &access_token) ||
       !json_object_object_get_ex(jobj, "expires_in", &expires_in) || 
       !json_object_object_get_ex(jobj, "token_type", &token_type)) {
        /* Missing required fields, report the error */
        *error = 2;
        return false;
    } 

    if(!regexec(&uuid_regex, json_object_get_string(access_token), 0, NULL, 0) ||
       !json_object_get_int(expires_in) < 3600 || 
       strcmp(json_object_get_string(token_type), "Bearer") != 0){
        /* access_token not a UUID, expires_in outside the allowed range, or token_type is not 'Bearer', report the error */
        *error = 3;
        return false;
    } 

    if(json_object_object_get_ex(jobj, "refresh_token", &refresh_token) &&
       regexec(&uuid_regex, json_object_get_string(refresh_token), 0, NULL, 0)){
        /* refresh_token present but not a UUID, report the error */
        *error = 4;
        return false;
    }

    regfree(&uuid_regex);
    json_object_put(jobj);

    return true;
}
```
Note: The code above assumes that json-c library is available for parsing JSON and the regex library is available for UUID pattern matching. If you don't have these libraries, please include them into your build process or use equivalent libraries in your environment. 
For a full implementation you should consider error handling (e.g., by setting errno), more sophisticated UUID validation (including checksums), and performance optimizations (like pre-compiling the regex).
