['Here's how you can achieve this using C#:

```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class AESCipher
{
    private const int BlockSize = 128; // bits
    private const CipherMode Mode = CipherMode.CBC;
    private const PaddingMode Padding = PaddingMode.PKCS7;
    private readonly byte[] _key;
    private readonly byte[] _iv;

    public AESCipher(byte[] key, byte[] iv)
    {
        if (key == null || key.Length != BlockSize / 8)
            throw new CryptographicException("Invalid Key Size");

        if (iv == null || iv.Length != BlockSize / 8)
            throw new CryptographicException("Invalid IV Length");

        _key = key;
        _iv = iv;
    }

    public byte[] Transform(byte[] input, bool encrypt)
    {
        using (var aesAlgorithm = Aes.Create())
        {
            var transform = encrypt ? aesAlgorithm.CreateEncryptor(_key, _iv) : aesAlgorithm.CreateDecryptor(_key, _iv);

            return TransformFinalBlock(input, transform);
        }
    }

    private static byte[] TransformFinalBlock(byte[] input, ICryptoTransform transform)
    {
        using (var memoryStream = new MemoryStream())
        {
            using (var cryptoStream = new CryptoStream(memoryStream, transform, CryptoStreamMode.Write))
            {
                cryptoStream.Write(input, 0, input.Length);
                // Must manually call FlushFinalBlock in order to complete the encryption/decryption operation before we can get back the bytes
                cryptoStream.FlushFinalBlock();

                return memoryStream.ToArray();
            }
        }
    }
}
``` 

