```c
#include <stdlib.h>
#include <pthread.h>

// Struct for Record 
typedef struct {
    int key;
    long offset_value;
} Record;

// Node in linked list
typedef struct node {
    Record* record;
    struct node* next;
} Node;

// Hash table with buckets (linked lists)
#define HASH_TABLE_SIZE 1024 // Size of hash table
Node** hashTable;
pthread_mutex_t hashLock = PTHREAD_MUTEX_INITIALIZER;

// Simple hash function implementation
int hashFunction(int key) {
    return abs(key % HASH_TABLE_SIZE);
}

// Initialize HashTable
void initHashTable() {
    hashTable = malloc(sizeof(Node*) * HASH_TABLE_SIZE);
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        hashTable[i] = NULL;
    }
}

// Insert into Hash Table
void insertRecord(Record* record) {
    int index = hashFunction(record->key);

    pthread_mutex_lock(&hashLock); // Acquire lock before modifying shared data
    Node* node = malloc(sizeof(Node));
    node->record = record;
    node->next = hashTable[index]; 
    hashTable[index] = node; 
    pthread_mutex_unlock(&hashLock); // Release lock after modification
}

// Lookup in Hash Table
Record* lookup(int key) {
    int index = hashFunction(key);

    pthread_mutex_lock(&hashLock); // Acquire lock before accessing shared data
    Node* node = hashTable[index]; 
    while (node != NULL) {
        if (node->record->key == key) {
            pthread_mutex_unlock(&hashLock); // Release lock after lookup
            return node->record;
        }
        node = node->next;
    }
    pthread_mutex_unlock(&hashLock); // Release lock after failed lookup
    return NULL; 
}
```
This code creates a simple hash table with linked list for collision resolution. It uses a mutex to ensure that only one thread can modify the hash table at any given time, preventing race conditions. 

