public class FileHashingService {
    private static final Logger logger = Logger.getLogger(FileHashingService.class.getName());
    private MessageDigest messageDigest;
    private int blockSize = 1024 * 1024; // default block size in bytes (1MB)
    private String hashAlgorithm = "SHA-256"; // default hashing algorithm

    public FileHashingService() {
        try {
            messageDigest = MessageDigest.getInstance(hashAlgorithm);
        } catch (NoSuchAlgorithmException e) {
            logger.severe("Failed to initialize MessageDigest: " + e.getMessage());
        }
    }

    public String calculateHash(String filePath) throws IOException {
        FileInputStream inputStream = new FileInputStream(filePath);
        byte[] buffer = new byte[blockSize];
        int bytesRead;

        while ((bytesRead = inputStream.read(buffer)) != -1) {
            messageDigest.update(buffer, 0, bytesRead);
        }

        return IOUtils.toHex(messageDigest.digest());
    }

    // Asynchronous processing with CompletableFuture
