['Here is a C code that creates a scalable collection in a multi-threaded environment, using separate chaining for handling collisions:
```c
#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>
#define HASH_TABLE_SIZE 1024

typedef struct Record {
    int key;
    unsigned offset;
} Record;

typedef struct Bucket {
    pthread_mutex_t mutex;
    Record* record;
    struct Bucket* next;
} Bucket;

Bucket hashTable[HASH_TABLE_SIZE];
int rehashFlag = 0;
pthread_rwlock_t rwLock = PTHREAD_RWLOCK_INITIALIZER;

unsigned int hash(int key) {
    return abs((key * 2654435761)) % HASH_TABLE_SIZE;
}

Record* createRecord() {
    Record* rec = malloc(sizeof(Record));
    assert(rec != NULL);

    rec->key = rand();
    rec->offset = rand();

    return rec;
}

void initializeHashTable(int size) {
    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        pthread_mutex_init(&hashTable[i].mutex, NULL);
        hashTable[i].record = NULL;
        hashTable[i].next = NULL;
    }

    for (int i = 0; i < size; i++) {
        Record* rec = createRecord();
        unsigned int index = hash(rec->key);

        pthread_mutex_lock(&hashTable[index].mutex);
        Bucket* newBucket = malloc(sizeof(Bucket));
        assert(newBucket != NULL);

        newBucket->record = rec;
        newBucket->next = hashTable[index].next;
        hashTable[index].next = newBucket;
        pthread_mutex_unlock(&hashTable[index].mutex);
    }
}

Record* get(int key) {
    unsigned int index = hash(key);

    pthread_rwlock_rdlock(&rwLock);
    if (rehashFlag == 1) {
        // If a rehash is in progress, wait until it finishes.
        while (rehashFlag == 1) {}
    } 
    Bucket* bucket = hashTable[index].next;

    while (bucket != NULL && bucket->record->key != key) {
        bucket = bucket->next;
    }
    pthread_rwlock_unlock(&rwLock);

    return bucket == NULL ? NULL : bucket->record;
}

void rehash() {
    if (rehashFlag == 1) return; // already rehashing, just wait for it to finish
    Bucket* newHashTable[HASH_TABLE_SIZE];

    pthread_rwlock_wrlock(&rwLock);
    rehashFlag = 1;

    for (int i = 0; i < HASH_TABLE_SIZE; i++) {
        Bucket* bucket = hashTable[i].next;

        while (bucket != NULL) {
            unsigned int newIndex = hash(bucket->record->key);
            Bucket* nextBucket = bucket->next;

            // remove the record from current chain
            pthread_mutex_lock(&hashTable[i].mutex);
            if (hashTable[i].next == bucket) {
                hashTable[i].next = nextBucket;
            } else {
                Bucket* prevBucket = &hashTable[i];

                while (prevBucket->next != bucket) {
                    prevBucket = prevBucket->next;
                }
                prevBucket->next = nextBucket;
            }
            pthread_mutex_unlock(&hashTable[i].mutex);

            // insert into new chain
            if (newHashTable[newIndex] == NULL) {
                newHashTable[newIndex] = malloc(sizeof(Bucket));
                assert(newHashTable[newIndex] != NULL);

                newHashTable[newIndex]->record = bucket->record;
            } else {
                Bucket* tail = newHashTable[newIndex];
                while (tail->next != NULL) {
                    tail = tail->next;
                }

                Bucket* newBucket = malloc(sizeof(Bucket));
                assert(newBucket != NULL);

                newBucket->record = bucket->record;
                tail->next = newBucket;
            }

            free(bucket); // delete old bucket
            bucket = nextBucket;
        }
    }

    memcpy(hashTable, newHashTable, sizeof(newHashTable));
    rehashFlag = 0;
    pthread_rwlock_unlock(&rwLock);
}
```
This code uses separate chaining to handle hash collisions and provides a mechanism to dynamically update the hash table. It utilizes reader-writer locks for concurrent access management, with one writer thread responsible for rehashing when necessary. The hash function used is relatively simple and may not provide optimal performance under skewed distributions.
']

