```c
#include <openssl/evp.h>
#include <openssl/err.h>
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <pthread.h>

// Struct to hold the context and lock for each initialization call
typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[32];
    pthread_mutex_t lock;
} aes_context;

aes_context ctxs[10]; // Array to hold contexts for each initialization call
int num_ctxs = 0; 
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void handleErrors(const char *msg) {
    ERR_print_errors_fp(stderr);
    fprintf(stderr, "%s\n", msg);
    exit(1);
}

int aes256CBCInit(const unsigned char *password) {
    pthread_mutex_lock(&mutex); // Lock the mutex
    int ctxIndex = num_ctxs++; // Use current number of contexts as index for new context

    if (num_ctxs > 10) {
        fprintf(stderr, "Too many AES-256-CBC ciphers initialized\n");
        exit(1);
    }

    aes_context *ctx = &ctxs[ctxIndex]; // Get the context for this initialization call
    ctx->lock = (pthread_mutex_t)PTHREAD_MUTEX_INITIALIZER; 

    // Generate key using SHA-256 hash function
    unsigned char digest[SHA256_DIGEST_LENGTH];
    SHA256(password, strlen((char *)password), digest);
    memcpy(ctx->key, digest, sizeof(digest));

    // Initialize cipher context
    if(!(ctx->ctx = EVP_CIPHER_CTX_new())) {
        handleErrors("Error initializing AES-256-CBC cipher");
    }

    pthread_mutex_unlock(&mutex); // Unlock the mutex
    return ctxIndex;
}

void aes256CBCEncrypt(const unsigned char *in, size_t inLen, unsigned char *out, int ivLen) {
    if (ctxs[ivLen].ctx == NULL) {
        handleErrors("No AES-256-CBC cipher context found for encryption");
    }

    // Lock the mutex and begin critical section
    pthread_mutex_lock(&(ctxs[ivLen].lock)); 
    EVP_EncryptInit_ex(ctxs[ivLen].ctx, NULL, NULL, ctxs[ivLen].key, iv); 

    if(!EVP_EncryptUpdate(ctxs[ivLen].ctx, out, &outLen, in, inLen)) {
        handleErrors("Error encrypting data with AES-256-CBC cipher");
    }

    // Unlock the mutex and end critical section
    pthread_mutex_unlock(&(ctxs[ivLen].lock)); 
}

void aes256CBCDecrypt(const unsigned char *in, size_t inLen, unsigned char *out, int ivLen) {
    if (ctxs[ivLen].ctx == NULL) {
        handleErrors("No AES-256-CBC cipher context found for decryption");
    }

    // Lock the mutex and begin critical section
    pthread_mutex_lock(&(ctxs[ivLen].lock)); 
    EVP_DecryptInit_ex(ctxs[ivLen].ctx, NULL, NULL, ctxs[ivLen].key, iv); 

    if(!EVP_DecryptUpdate(ctxs[ivLen].ctx, out, &outLen, in, inLen)) {
        handleErrors("Error decrypting data with AES-256-CBC cipher");
    }

    // Unlock the mutex and end critical section
    pthread_mutex_unlock(&(ctxs[ivLen].lock)); 
}

void aes256CBCCleanup(int ivLen) {
    if (ctxs[ivLen].ctx == NULL) {
        return;
    }

    // Lock the mutex and begin critical section
    pthread_mutex_lock(&(ctxs[ivLen].lock)); 

    EVP_CIPHER_CTX_free(ctxs[ivLen].ctx);
    ctxs[ivLen].ctx = NULL;

    // Unlock the mutex and end critical section
    pthread_mutex_unlock(&(ctxs[ivLen].lock)); 
}
```
This is a very basic implementation of an AES-256-CBC cipher in C using the OpenSSL library. It includes several key features such as context initialization, error handling, encryption and decryption functions, cleanup process, and thread safety. Please note that you would need to handle IVs separately for each call to encrypt or decrypt, as they are not stored or reused. Also remember to include appropriate error checking before using the code in production environment.
