    }

    public float GetRandomFloat() 
    {
        return Random.Range(minValue, maxValue);
    }

    public int GetRandomInt() 
    {
        return Mathf.FloorToInt(GetRandomFloat());
    }

    public int GetRandomIntExclusiveMax() 
    {
        return Random.Range(minValue, maxValue);
    }

    public override string ToString() 
    {
        return $"Range: [{minValue}, {maxValue}]";
    }

    public void ShuffleValues(int[] array)
    {
        if (array.Length < maxValue - minValue + 1)
            throw new ArgumentException("Array length should be equal or less than range");

        int n = array.Length;
        while (n > 0) 
        {
            int k = GetRandomIntExclusiveMax();
            n--;
            int temp = array[n];
            array[n] = array[k];
            array[k] = temp;
        }
    }

    public void ResetRange(int minValue, int maxValue) 
    {
        if (minValue > maxValue)
            throw new ArgumentException("Min value should be less than or equal to max value");

        this.minValue = minValue;
        this.maxValue = maxValue;
    }
}
