#define SLASH '/'

char* appendSlash(const char *str, size_t limit, size_t bufferSize) {
    if (str == NULL) return NULL;

    size_t strLen = strlen(str);
    // Condition 1: string is within size limit and total length is within buffer size
    if ((strLen < limit) && ((strLen + 2) <= bufferSize)) {
        char* newStr = malloc(sizeof(char) * (strLen + 2)); // +1 for null terminator, +1 for slash
        if (newStr == NULL) return NULL; 

        strncpy(newStr, str, limit);
        newStr[limit] = SLASH;
        newStr[limit+1] = '\0'; // Null-terminate the string
        return newStr;
    }

    // Condition 3: truncate the string to fit within buffer size if total length exceeds it
    else if ((strLen + 2) > bufferSize){
        char* newStr = malloc(sizeof(char) * (bufferSize)); // +1 for null terminator
        if (newStr == NULL) return NULL; 

        strncpy(newStr, str, bufferSize - 2); // leave room for slash and null-terminator
        newStr[bufferSize - 2] = SLASH;
        newStr[bufferSize - 1] = '\0'; // Null-terminate the string
        return newStr;
    }

    // Condition 2: if strLen >= limit, return NULL
    else {
        return NULL;
    }
}
