    // Execute SQL query with retry logic and exponential backoff
    public void executeQuery(String sql) {
        if (ds == null || ds.isClosed()) {
            establishConnection();
        }

        int maxAttempts = 5;
        long delay = 1000L; // Initial retry delay in milliseconds

        for (int i = 1; i <= maxAttempts; ++i) {
            try {
                ds.getConnection().createStatement().execute(sql);
                logger.info("SQL query executed successfully");
                return;
            } catch (Exception e) {
                logger.warn("Failed to execute SQL query, retrying in {}ms", delay, e);

                try { Thread.sleep(delay); } catch (InterruptedException ignored) { }

                if (i < maxAttempts) { delay *= 2; } // Exponential backoff
            }
        }

        logger.error("Failed to execute SQL query after {} attempts", maxAttempts);
    }

