void process_image(char *filepath, char **crypto_ops) {
    TIFF* tif = TIFFOpen(filepath, "r");
    if (tif == NULL) {
        log_func("Failed to open the image file: %s", filepath);
        return;
    }

    uint16 bitsPerSample, samplesPerPixel;
    TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE, &bitsPerSample);
    TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL, &samplesPerPixel);

    // Check if the bit depth is supported
    if (bitsPerSample != 1 && bitsPerSample != 2 && bitsPerSample != 4 && 
        bitsPerSample != 8 && bitsPerSample != 16) {
        log_func("Unsupported bit depth: %d", bitsPerSample);
        TIFFClose(tif);
        return;
    }

    // Get image data and perform the specified cryptographic operations
    size_t npixels = TIFFScanlineSize(tif) / samplesPerPixel;
    uint32* raster = _TIFFmalloc(npixels * sizeof (uint32));
    if (raster != NULL) {
        for (uint32 row = 0; row < TIFFNumberOfRows(tif); row++) {
            TIFFReadScanline(tif, &raster[row], row);

            // Perform cryptographic operations
            for (int i = 0; i < MAX_CRYPTO_OPTS && crypto_ops[i] != NULL; ++i) {
                if (!strcmp(crypto_ops[i], "SHA256")) {
                    EVP_Digest("SHA256", &raster[row], sizeof (uint32), NULL, NULL);
                } else if (!strcmp(crypto_ops[i], "AES-256-CBC")) {
                    // AES encryption code here
                } 
            }
        }
    }

    TIFFClose(tif);
}
