            tm.tm_hour, tm.tm_min, tm.tm_sec);

    // Append random number of digits between 1 and 5
    srand((unsigned int)time(NULL));
    int randomDigit = rand() % 5 + 1;

    for (int i = 0; i < randomDigit; ++i) {
        sprintf(&buffer[strlen(filename)] + strlen("YYYYMMDDHHMMSS") + 6, "%d", rand() % 10);
    }

    // Append filetype
    sprintf(&buffer[strlen(filename)] + strlen("YYYYMMDDHHMMSS") + 6 + randomDigit, ".%s", filetype);

    return buffer;
