This solution assumes that keys and values are strings, and the format is a simple binary format where each key-value pair consists of:

1. A 4 byte integer for the length of the key.
2. The specified number of bytes for the key string (not including NULL terminator).
3. A 4 byte integer for the length of the value.
4. The specified number of bytes for the value string (not including NULL terminator).
5. Repeat steps 1-4 until end of file.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <zlib.h>

// Struct for key-value pair
typedef struct {
    char* key;
    char* value;
} KeyValuePair;

// Resource bundle structure
typedef struct {
    pthread_mutex_t mutex; // For thread safety
    KeyValuePair** pairs;  // Array of pairs
    size_t count;         // Number of pairs
    size_t capacity;      // Capacity of array
} ResourceBundle;

// Function to load resource bundle from file
ResourceBundle* loadResourceBundle(const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        return NULL; // Handle error here
    }

    ResourceBundle* bundle = malloc(sizeof(ResourceBundle));
    if (bundle == NULL) {
        // Handle memory allocation failure
        fclose(file);
        return NULL;
    }

    pthread_mutex_init(&bundle->mutex, NULL);  // Initialize mutex

    bundle->count = 0;
    bundle->capacity = 1024;  // Initial capacity
    bundle->pairs = malloc(sizeof(KeyValuePair*) * bundle->capacity);
    if (bundle->pairs == NULL) {
        // Handle memory allocation failure
        fclose(file);
        pthread_mutex_destroy(&bundle->mutex);  // Cleanup mutex
        free(bundle);
        return NULL;
    }

    while (!feof(file)) {
        uint32_t keyLen, valueLen;
        fread(&keyLen, sizeof(uint32_t), 1, file);

        char* key = malloc(keyLen + 1);
        if (key == NULL) {
            // Handle memory allocation failure
            fclose(file);
            pthread_mutex_destroy(&bundle->mutex);  // Cleanup mutex
            free(bundle);
            return NULL;
        }

        fread(key, keyLen, 1, file);
        key[keyLen] = '\0';

        fread(&valueLen, sizeof(uint32_t), 1, file);

        char* value = malloc(valueLen + 1);
        if (value == NULL) {
            // Handle memory allocation failure
            free(key);
            fclose(file);
            pthread_mutex_destroy(&bundle->mutex);  // Cleanup mutex
            free(bundle);
            return NULL;
        }

        fread(value, valueLen, 1, file);
        value[valueLen] = '\0';

        if (bundle->count == bundle->capacity) {
            // Resize array when full
            bundle->capacity *= 2;
            bundle->pairs = realloc(bundle->pairs, sizeof(KeyValuePair*) * bundle->capacity);
            if (bundle->pairs == NULL) {
                // Handle memory allocation failure
                free(key);
                free(value);
                fclose(file);
                pthread_mutex_destroy(&bundle->mutex);  // Cleanup mutex
                free(bundle);
                return NULL;
            }
        }

        KeyValuePair* pair = malloc(sizeof(KeyValuePair));
        if (pair == NULL) {
            // Handle memory allocation failure
            free(key);
            free(value);
            fclose(file);
            pthread_mutex_destroy(&bundle->mutex);  // Cleanup mutex
            free(bundle);
            return NULL;
        }

        pair->key = key;
        pair->value = value;

        bundle->pairs[bundle->count++] = pair;
    }

    fclose(file);  // Close file
    return bundle;
}
```

