public class DocumentBatchProcessor {
    private final ConcurrentHashMap<String, Long> documentIdCounts;
    private final AtomicLong totalProcessedDocs;
    private final AtomicLong totalProcessingTime;

    public DocumentBatchProcessor() {
        this.documentIdCounts = new ConcurrentHashMap<>();
        this.totalProcessedDocs = new AtomicLong(0);
        this.totalProcessingTime = new AtomicLong(0);
    }

    public void batchProcessDocuments(String[] filePaths) {
        if (filePaths == null) {
            System.out.println("No files to process");
            return;
        }

        ExecutorService executor = Executors.newFixedThreadPool(10); // adjust this depending on the available cores and expected load

        for (String filePath : filePaths) {
            executor.execute(() -> {
                try {
                    Instant startTime = Instant.now();

                    String documentId = readDocumentFromFile(filePath); // replace with actual logic
                    if (!documentIdCounts.containsKey(documentId)) {
                        synchronized (this) {
                            if (!documentIdCounts.containsKey(documentId)) {
                                documentIdCounts.put(documentId, 0L);
                            }
                        }
                    }

                    long processingTime = Duration.between(startTime, Instant.now()).toMillis();
                    totalProcessingTime.addAndGet(processingTime);
                    totalProcessedDocs.incrementAndGet();
                } catch (Exception e) {
                    // handle exceptions gracefully
                    System.out.println("Error processing file " + filePath + ": " + e.getMessage());
                }
            });
        }

        executor.shutdown();
        try {
            executor.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS); // replace with actual timeout and unit
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        System.out.println("Total processed documents: " + totalProcessedDocs.get());
        if(totalProcessedDocs.get() > 0){
          System.out.println("Average processing time per document (ms): " + (totalProcessingTime.get() / totalProcessedDocs.get()));
          System.out.println("Count of unique document IDs: " + documentIdCounts.size());
        }
    }

    // replace with actual file reading and document processing logic
    private String readDocumentFromFile(String path) throws Exception { 
      return new String(Files.readAllBytes(Paths.get(path)));
    }
}
```
