['Here's how you might implement this in C#:

```csharp
using System;
using System.Security.Cryptography;
using System.IO;
using System.Threading;
using System.Threading.Tasks;
using System.Collections.Generic;

public class FileHashGenerator
{
    private int minValue;
    private int maxValue;
    private static readonly Random random = new Random();
    private SemaphoreSlim semaphore = new SemaphoreSlim(1, 1); // Only one thread can execute at a time.

    public FileHashGenerator(int minValue, int maxValue)
    {
        if (minValue > maxValue)
            throw new ArgumentException("Minimum value cannot be greater than maximum value.");

        this.minValue = minValue;
        this.maxValue = maxValue;
    }

    public void ResetRange(int minValue, int maxValue)
    {
        if (minValue > maxValue)
            throw new ArgumentException("Minimum value cannot be greater than maximum value.");

        this.minValue = minValue;
        this.maxValue = maxValue;
    }

    public int GetRandomInt()
    {
        return random.Next(minValue, maxValue + 1); // Inclusive upper bound
    }

    public float GetRandomFloat()
    {
        var nextDouble = random.NextDouble();
        return (float)(nextDouble * (maxValue - minValue) + minValue);
    }

    public int GetRandomIntExclusiveMax()
    {
        return random.Next(minValue, maxValue); // Exclusive upper bound
    }

    public override string ToString()
    {
        return $"Range: [{minValue}, {maxValue}]";
    }

    private void Shuffle<T>(IList<T> list)  
    { 
        int n = list.Count;

        while (n > 1) {  
            n--;  
            int k = random.Next(n + 1);  
            T value = list[k];  
            list[k] = list[n];  
            list[n] = value;  
        } 
    }

    public IList<int> ShuffleValues()
    {
        var values = new List<int>();

        for (var i = minValue; i <= maxValue; i++)
            values.Add(i);

        Shuffle(values);
        return values;
    }

    public async Task<string> CalculateFileHashAsync(string filePath, CancellationToken cancellationToken = default)
    {
        await semaphore.WaitAsync(cancellationToken).ConfigureAwait(false);

        try 
        {
            using var hashAlgorithm = SHA256.Create();

            const int bufferSizeForReading = 1024 * 1024; // Adjust as necessary
            byte[] buffer = new byte[bufferSizeForReading];

            using (FileStream fileStream = File.OpenRead(filePath))
            {
                int readBytes;

                while ((readBytes = await fileStream.ReadAsync(buffer, 0, bufferSizeForReading, cancellationToken).ConfigureAwait(false)) > 0)
                    hashAlgorithm.TransformBlock(buffer, 0, readBytes, buffer, 0);
            }

            hashAlgorithm.TransformFinalBlock(buffer, 0, 0);
            return BitConverter.ToString(hashAlgorithm.Hash).Replace("-", "").ToLowerInvariant();
        } 
        finally 
        {
            semaphore.Release();
        }
    }
}
```
This class provides a range of functionality that includes generating random numbers, calculating the hash of a file and ensuring thread safety for concurrent operations. The `CalculateFileHashAsync` method is asynchronous to avoid blocking other threads while the file is being read. The semaphore ensures only one task can execute at a time. It also includes an exponential backoff retry mechanism which you would need to implement yourself since this is out of scope for this task.
