public class ObjectDeserializer {
    private static final int MAX_FILENAME_LENGTH = 255;
    private SimpleDateFormat sdf = new SimpleDateFormat("YYYYMMDDHHmmss");

    public String deserializeAndRename(byte[] data, String filename) throws RuntimeException {
        try (ByteArrayInputStream bis = new ByteArrayInputStream(data);
             ObjectInput in = new ObjectInputStream(bis)) {
            // Deserialization
            Object obj = in.readObject();

            // Rename the file with timestamp and random numbers
            String timeStamp = sdf.format(new Date());
            Random rand = new Random();
            int digitsCount = rand.nextInt(5) + 1;
            StringBuilder sb = new StringBuilder();

            for (int i = 0; i < digitsCount; i++) {
                sb.append(rand.nextInt(10));
            }

            // Prepare the file extension and truncate it if necessary
            int dotIndex = filename.lastIndexOf('.');
            String ext = "";
            if (dotIndex != -1 && dotIndex < MAX_FILENAME_LENGTH) {
                ext = filename.substring(dotIndex);
            }

            // Generate the new filename
            String newFilename = timeStamp + sb.toString() + ext;

            // Handle filename conflicts by appending an incremental suffix
            int counter = 1;
            while (new File(newFilename).exists()) {
                newFilename = timeStamp + sb.toString() + "_" + counter++ + ext;

                // If the new filename still exceeds the limit, truncate it
                if (newFilename.length() > MAX_FILENAME_LENGTH) {
                    newFilename = newFilename.substring(0, MAX_FILENAME_LENGTH);
                    break;
                }
            }

            // Log the process 
            System.out.println("Deserialized object from " + filename + ", renamed to " + newFilename);

            return newFilename;
        } catch (IOException | ClassNotFoundException e) {
            throw new RuntimeException("Error deserializing object", e);
        } finally {
            // Memory deallocation is handled automatically by try-with-resources
        }
    }
}
