['```c
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <assert.h>
#include <limits.h>

typedef struct {
    int key;
    unsigned long offset;
} record;

typedef struct node_t {
    record rec;
    struct node_t *next;
} node;

typedef struct {
    pthread_mutex_t lock;
    node **buckets;
    int size, bucketNum;
} hashTable;

hashTable* initHash(int num) {
    assert(num < UINT_MAX / sizeof(node *));

    srand((unsigned int) time(NULL));

    hashTable *ht = malloc(sizeof(hashTable));
    if (ht == NULL) return NULL;

    ht->buckets = calloc(num, sizeof(node *));
    if (ht->buckets == NULL) {
        free(ht);
        return NULL;
    }

    pthread_mutex_init(&ht->lock, NULL);
    ht->size = 0;
    ht->bucketNum = num;
    return ht;
}

void insertRecord(hashTable *ht, record rec) {
    pthread_mutex_lock(&ht->lock);

    int index = rec.key % ht->bucketNum;
    if (index < 0) index += ht->bucketNum;

    node **ptr = &(ht->buckets[index]);
    while (*ptr != NULL && (*ptr)->rec.key != rec.key) ptr = &((*ptr)->next);

    if (*ptr == NULL) {
        *ptr = malloc(sizeof(node));
        assert(*ptr != NULL);
        (*ptr)->rec = rec;
        (*ptr)->next = NULL;
        ht->size++;
    } else {
        (*ptr)->rec.offset = rec.offset;
    }

    pthread_mutex_unlock(&ht->lock);
}

void destroyHash(hashTable *ht) {
    for (int i = 0; i < ht->bucketNum; i++) {
        node *cur = ht->buckets[i];

        while (cur != NULL) {
            node *next = cur->next;
            free(cur);
            cur = next;
        }
    }

    pthread_mutex_destroy(&ht->lock);
    free(ht->buckets);
    free(ht);
}
```
