```c
#include <stdarg.h>
#include <pthread.h>
#include <string.h>

typedef struct Resource {
    char type[256];
    size_t size;
} Resource;

Resource* resourcePool = NULL;
size_t poolSize = 0, maxPoolSize = 1000000;  // Maximum of 1MB resources
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void updateMaxPoolSize(size_t newMax) {
    pthread_mutex_lock(&mutex);
    maxPoolSize = newMax;
    pthread_mutex_unlock(&mutex);
}

Resource* resource_manager(int count, ...){
    Resource *requests = malloc(count * sizeof(Resource));

    va_list args;
    va_start(args, count);

    for (int i = 0; i < count; ++i) {
        snprintf(requests[i].type, 256, "%s", va_arg(args, char*));
        requests[i].size = va_arg(args, size_t);

        if (poolSize + requests[i].size > maxPoolSize) {
            free(requests);
            return NULL;  // Resource pool overflow
        }
    }

    pthread_mutex_lock(&mutex);

    for (int i = 0; i < count; ++i) {
        resourcePool = realloc(resourcePool, (poolSize + requests[i].size) * sizeof(Resource));
        memcpy(&resourcePool[poolSize], &requests[i], sizeof(Resource));
        poolSize += requests[i].size;
    }

    pthread_mutex_unlock(&mutex);
    free(requests);

    return resourcePool;
}
```
This code maintains a simple in-memory resource pool with basic concurrency management using `pthread_mutex_t`. It also limits the maximum size of the resource pool to prevent memory exhaustion, as requested.

