    }
    return ip;
}

// Function to handle video conversion and DNS resolution
u_char* convertAndResolve(const char *inputVideoFile, const char *outputDirectory, const char *codecType, const char *hostname) {
    FILE *pipein, *pipeout;
    char command[256];
    u_char ip[16] = {0};

    // Ensure output directory exists
    struct stat st = {0};
    if (stat(outputDirectory, &st) == -1) {
        mkdir(outputDirectory, 0700);
    }

    // Convert video using FFmpeg
    sprintf(command,"ffmpeg -i %s -c:v %s %s/%s_%s.mp4", inputVideoFile, codecType, outputDirectory, inputVideoFile, codecType);

    if((pipein = popen(command, "r")) == NULL) {
        perror("popen");
        return NULL;
    }

    pclose(pipein);

    // Perform DNS resolution
    struct in_addr **addr_list;
    if (ipToUChar(addr_list, hostname) == NULL) {
        return NULL;
    }

    return ip;
}
