#include <ctype.h>

char* generate_session_id(const char* username, const char* version) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    struct tm* ptm = localtime(&tv.tv_sec);
    char timestamp[15];  // "YYYYMMDDHHMMSS"
    strftime(timestamp, sizeof(timestamp), "%Y%m%d%H%M%S", ptm);

    const char alphanum[] = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
    srand(tv.tv_usec);  // seed with microseconds
    char randstring[9];
    for (int i = 0; i < 8; ++i) {
        randstring[i] = alphanum[rand() % (sizeof(alphanum) - 1)];
    }
    randstring[8] = '\0';  // null-terminate the string

    size_t username_len = strlen(username);
    size_t session_id_len = 23 + username_len;  // timestamp, randstr and version + 1 for '\0'
    char* session_id = malloc((session_id_len + 1) * sizeof(*session_id));  // allocate memory for the whole string
    if (session_id == NULL) {
        return NULL;  // handle allocation failure, may need to free resources and return an error code.
    }

    strcpy(session_id, timestamp);
    strcat(session_id, randstring);
    strncat(session_id, username, username_len);
    strcat(session_id, version);

    return session_id;  // developer must free the memory when it's not needed anymore
}
