} Profile;

Profile* parse_profile(FILE *file, size_t fileSize) {
    if (fread(&fileSize, sizeof(size_t), 1, file) != 1) return NULL;

    Profile* profile = malloc(sizeof(Profile));
    if (!profile) return NULL;

    if (fread(&profile->id, sizeof(int), 1, file) != 1 || fread(&profile->name, sizeof(char), fileSize - sizeof(int), file) != fileSize - sizeof(int)) {
        free(profile);
        return NULL;
    }

    return profile;
}

Profile** initialize_manager(const char* configPath, size_t maxFileSize) {
    Profile **profiles = malloc(sizeof(Profile*)); // Initialize with empty list
    if (!profiles) return NULL;

    FILE *configFile = fopen(configPath, "rb");
    if (!configFile) {
        free(profiles);
        return NULL;
    }

    size_t fileSize = 0;
    while (fread(&fileSize, sizeof(size_t), 1, configFile) == 1 && fileSize <= maxFileSize) {
        fseek(configFile, -sizeof(size_t), SEEK_CUR); // Reset to start of profile data

        Profile* newProfile = parse_profile(configFile, fileSize);
        if (!newProfile) continue;

        profiles = realloc(profiles, sizeof(Profile*) * (*(&profiles + 1) - profiles + 1));  // Expand the list
        profiles[(*(&profiles + 1) - profiles - 1)] = newProfile;  // Append to end of list
    }

    fclose(configFile);
    return profiles;
}
```
