    if (it != list.end()) {
        list.insert_after(it, insertion);
    } else {
        list.push_front(insertion);
    }
}

void generateUniqueIdAndInsertInList(std::forward_list<std::string>& list, const std::string& target, 
                                     const std::string& insertion, int versionId) {
    time_t now = time(0);
    struct tm tstruct;
    char buf[80];
    tstruct = *localtime(&now);
    strftime(buf, sizeof(buf), "%Y%m%d%H%M%S", &tstruct);

    std::string timestamp = buf;
    std::string randomStr = generateRandomString(8);
    std::string versionStr = "v" + std::to_string(versionId);

    std::string uniqueId = timestamp + "_" + randomStr + "_" + versionStr;

    // Handle maximum length issues here if needed.
