['Here is a high-level pseudo code for `DatabaseConnectionManager` class in Java using HikariCP library along with Logback for logging. This does not handle all edge cases or error conditions as those would require further details to be provided, but it provides a good starting point. 

```java
import com.zaxxer.hikari.HikariConfig;
import com.zaxxer.hikari.HikariDataSource;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import java.sql.*;
import java.util.concurrent.atomic.AtomicInteger;

public class DatabaseConnectionManager {
    private final static Logger logger = LoggerFactory.getLogger(DatabaseConnectionManager.class);

    private HikariDataSource dataSource;
    private AtomicInteger currentConnections = new AtomicInteger();
    private int maxPoolSize;

    public DatabaseConnectionManager() {
        // Initialize with default configuration values or read from config file
        this.maxPoolSize = 10;  // set initial pool size for example
    }

    public void initializeDataSource(HikariConfig hikariConfig) {
        if (this.dataSource == null) {
            this.dataSource = new HikariDataSource(hikariConfig);
            logger.info("Connection Pool initialized with " + maxPoolSize + " connections");
        } else {
            logger.warn("Pool already initialized!");
        }
    }

    public Connection getConnection() throws SQLException {
        if (currentConnections.get() >= maxPoolSize) {
            resizeDataSource(maxPoolSize * 2); // double the pool size on full utilization
        }
        Connection conn = dataSource.getConnection();
        currentConnections.incrementAndGet();
        logger.info("New connection established, current pool size: " + currentConnections.get());
        return conn;
    }

    private void resizeDataSource(int newSize) {
        HikariConfig hikariConfig = dataSource.getHikariConfigMXBean();
        hikariConfig.setMaximumPoolSize(newSize);
        dataSource.close(); // Close all connections and update the config
        initializeDataSource(hikariConfig);
    }

    public void closeConnection(Connection conn) {
        try {
            if (conn != null && !conn.isClosed()) {
                conn.close();
                currentConnections.decrementAndGet();
                logger.info("Connection closed, current pool size: " + currentConnections.get());
                // If the pool is more than 25% empty after closing a connection, resize it
                if (currentConnections.get() < maxPoolSize / 4) {
                    resizeDataSource(maxPoolSize / 2);
                }
            }
        } catch (SQLException e) {
            logger.error("Error occurred while closing the connection: ", e);
        }
    }

    public ResultSet executeQuery(Connection conn, String sql) throws SQLException {
        Statement stmt = conn.createStatement();
        return stmt.executeQuery(sql);
    }
}
```

This is a very simplified version of what you are asking for and it does not include all the details like exception handling with exponential backoff, health check mechanisms, logging configuration etc. Please refer to HikariCP and Logback documentation for more information on how to configure them properly. 

