public class BatchStringProcessor {

    private static final int MAX_MEMORY = 1024 * 1024 * 1024; // 1GB
    private Cache<String, String> cache = CacheBuilder.newBuilder()
            .maximumWeight(MAX_MEMORY)
            .weigher((key, value) -> key.length() + value.length())
            .build();

    public void processBatch(String[] batch) {
        for (String str : batch) {
            // Add a random delay between 0ms and 500ms to simulate network latency
            Random rand = new Random();
            int delay = rand.nextInt(501); // Max value is exclusive

            try {
                Thread.sleep(delay);
            } catch (InterruptedException e) {
                System.out.println("Thread interrupted while sleeping: " + e.getMessage());
            }

            long startTime = System.currentTimeMillis();

            // Compute the MD5 hash of the string and cache it if not already present
            String hash = DigestUtils.md5Hex(str);
            boolean isPresent = cache.asMap().containsKey(hash);

            long endTime = System.currentTimeMillis();
            long duration = endTime - startTime;
            System.out.println("Processing time for string " + str + ": " + duration + "ms");

            if (!isPresent) {
                // Simulate call to external data source and handle exceptions here...

                cache.put(hash, str);
                System.out.println("Added hash to cache: " + hash);
            } else {
                System.out.println("Duplicate hash detected for string: " + str);
            }
        }

        // Generate summary report...
        int uniqueHashes = (int) cache.size();
        double averageTimePerHash = 0; // Calculated based on total processing time divided by number of hashes
        System.out.println("Total unique hashes processed: " + uniqueHashes);
        System.out.println("Average processing time per hash: " + averageTimePerHash + "ms");
    }

