using System.Text;
using System.Threading.Tasks;
using System.Data;
using System.Data.SqlClient;

public class FileHashGenerator
{
    private int minValue, maxValue;

    public FileHashGenerator(int minValue, int maxValue)
    {
        if (minValue > maxValue) 
            throw new ArgumentException("Min value cannot be greater than max value.");

        this.minValue = minValue;
        this.maxValue = maxValue;
    }

    public float GetRandomFloat()
    {
        Random random = new Random();
        return (float)(random.NextDouble() * (maxValue - minValue) + minValue);
    }

    public int GetRandomInt()
    {
        Random random = new Random();
        return random.Next(minValue, maxValue + 1);
    }

    public int GetRandomIntExclusiveMax()
    {
        Random random = new Random();
        return random.Next(minValue, maxValue);
    }

    public void ShuffleValues(int[] array)
    {
        var rand = new Random();

        for (var i = 0; i < array.Length - 1; ++i)
        {
            var j = rand.Next(i, array.Length);

            var temp = array[i];
            array[i] = array[j];
            array[j] = temp;
        }
    }

    public override string ToString()
    {
        return $"Range: [{minValue}, {maxValue}]";
    }

    public async Task<DataTableReader> SendDataToDatabase(byte[] data)
    {
        // Implement the logic to send data to database server and return DataTableReader object.

