        {
            await connection.OpenAsync();

            using (SqlCommand command = new SqlCommand("Your Query", connection))
            {
                // Set command parameters, if any.

                return await command.ExecuteReaderAsync();
            }
        }
    }

    public string GetFileHash(string filePath)
    {
        using (var hashAlgorithm = SHA256.Create())
        {
            const int bufferSizeForReading = 1024 * 1024; // 1MB chunks

            using (var stream = new FileStream(filePath, FileMode.Open, FileAccess.Read, FileShare.ReadWrite, bufferSizeForReading, true))
            {
                var buffer = new byte[bufferSizeForReading];
                int read;

                while ((read = await stream.ReadAsync(buffer, 0, buffer.Length)) != 0)
                    hashAlgorithm.TransformBlock(buffer, 0, read, buffer, 0);
            }

            return Convert.ToBase64String(hashAlgorithm.Hash);
        }
    }
}
```

