```python
import os
import hashlib
from concurrent.futures import ThreadPoolExecutor, ProcessPoolExecutor, as_completed
from threading import Lock

# Define a class for file hasher
class FileHasher:
    def __init__(self):
        self._lock = Lock()  # for thread safety

    def hash_file(self, file_path, chunk_size=8192):
        md5 = hashlib.md5()

        with open(file_path, 'rb') as f:
            while True:
                data = f.read(chunk_size)

                if not data:
                    break

                md5.update(data)

        return md5.hexdigest()

    def process_file(self, file_path):
        try:
            hash = self.hash_file(file_path)

            with self._lock:
                print(f'File {file_path} has MD5 hash of {hash}')  # replace with logging for a robust system

        except Exception as e:
            print(f'Failed to process file {file_path}. Reason: {str(e)}')  # replace with logger and error handling mechanism

    def process_files(self, file_paths):
        num_threads = min(32, os.cpu_count() + 4)  # tune this value based on your system configuration

        with ThreadPoolExecutor(max_workers=num_threads) as executor:
            future_to_file = {executor.submit(self.process_file, file): file for file in file_paths}

            for future in as_completed(future_to_file):
                file_path = future_to_file[future]

                try:
                    future.result()  # wait until the task is complete

                except Exception as e:
                    print(f'Exception occurred when processing {file_path}. Reason: {str(e)}')  # replace with logger and error handling mechanism
```
