        error("Cannot open file");

    char buffer[BUFSIZ];
    size_t bytesRead = 0;
    while((bytesRead = fread(buffer, 1, sizeof buffer, info->file)) > 0) {
        processLine(info);
    }

    if (ferror(info->file))
        error("Error reading file");

    pthread_exit(NULL);
}

int main(int argc, char *argv[]) {
    if(argc < 2) {
        printf("Usage: ./program <input_source>\n");
        return 1;
    }

    InputSourceInfo info = {.input_source = argv[1]};
    pthread_t thread;
    int result = pthread_create(&thread, NULL, thread_read_file, &info);
    if (result != 0) error("Cannot create thread");

    void *res;
    if (pthread_join(thread, &res) != 0) error("Failed to join thread");
}
