#define MAX_CACHE_SIZE 1024
typedef struct CacheEntry {
    int index;
    NFAPI_CRC_INDICATION_PDU_T* pdu;
} CacheEntry;

NFAPI_CRC_INDICATION_PDU_T** cache;
int cacheSize = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void populateCache(int index, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Implement a LRU eviction strategy when cache is full.
    if (cacheSize >= MAX_CACHE_SIZE) {
        for (int i = 0; i < cacheSize - 1; ++i) {
            cache[i] = cache[i+1];
        }
        --cacheSize;
    }
    CacheEntry* newEntry = malloc(sizeof(CacheEntry));
    if (newEntry != NULL) {
        newEntry->index = index;
        newEntry->pdu = pdu;
        cache[cacheSize++] = newEntry;
    }
}

NFAPI_CRC_INDICATION_PDU_T* getFromCache(int index) {
    for (int i = 0; i < cacheSize; ++i) {
        if (cache[i]->index == index) return cache[i]->pdu;
    }
    return NULL;
}

NFAPI_CRC_INDICATION_PDU_T* allocateAndPopulate(int N) {
    // Allocate memory for the PDUs.
    NFAPI_CRC_INDICATION_PDU_T* pdus = calloc(N, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdus == NULL) {
        // Log error and return NULL for memory allocation failure.
        printf("Memory allocation failed.\n");
        return NULL;
    }

    srand(time(NULL)); // Seed the random number generator.

    // Populate each PDU in a thread-safe manner.
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < N; ++i) {
        pdus[i].RNTI = rand(); // Generate random RNTI value.
        pdus[i].crcIndication.CRCFLAG = rand() % 2; // Generate random CRCFLAG value.

        populateCache(i, &pdus[i]); // Add to cache for future reference.
    }
    pthread_mutex_unlock(&mutex);

    return pdus;
}
```
