#include <stdlib.h>
#include <pthread.h>

// Assume NFAPI_CRC_INDICATION_PDU_T, RX_UE_INFORMATION_TAG, RNTI and CRC_INDICATION_REL8_TAG are defined elsewhere

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
} Node;

Node* createList(int count) {
    Node *head = NULL, *tail = NULL;
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < count; i++) {
        Node* newNode = malloc(sizeof(Node));

        if (!newNode) {
            // Handle memory allocation failure gracefully
            perror("Memory allocation failed");
            break;
        }

        pthread_mutex_lock(&mutex);  // Start of critical section

        newNode->data = createPDU();  // Assume this function creates a valid PDU

        insertSorted(newNode, &head); // Insert node in sorted order by RNTI

        pthread_mutex_unlock(&mutex);  // End of critical section
    }

    return head;
}

void insertSorted(Node* newNode, Node** head) {
    if (*head == NULL || (*head)->data.RNTI >= newNode->data.RNTI) {
        newNode->next = *head;
        *head = newNode;
        return;
    }

    Node* current = *head;
    while (current->next != NULL && current->next->data.RNTI < newNode->data.RNTI) {
        current = current->next;
    }

    newNode->next = current->next;
    current->next = newNode;
}

NFAPI_CRC_INDICATION_PDU_T createPDU() {
    NFAPI_CRC_INDICATION_PDU_T pdu;

    // Assume external library functions are available for setting RNTI and CRCFLAG
    setRNTI(&pdu); 
