        switch (c) {
            case 'm':
                printf("Usage: program [OPTION]...\n");
                return 0;
            case 'o':
                file = fopen(optarg, "r");
                if (file == NULL) {
                    printf("Could not open file\n");
                    return -1;
                }
                break;
        }
    }

    int line_count = 0;
