typedef struct PDU {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} PDU;

typedef struct Node {
    PDU *pdu;
    struct Node *next;
} Node;

Node *head = NULL;  // Head of the linked list, shared by multiple threads
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;  // Mutex to ensure thread safety

int compare(const void* a, const void* b) {
    return ((PDU*)a)->RNTI - ((PDU*)b)->RNTI;
}

void insertNodeSorted(Node** head_ref, Node* new_node) {
    Node* current = *head_ref;

    // If list is empty or if the RNTI of the node to be inserted 
    // is smaller than that of the head node, make it the new head
    if (*head_ref == NULL || compare((*head_ref)->pdu, new_node->pdu) >= 0) {
        new_node->next = *head_ref;
        *head_ref = new_node;
    } else {
        // Else find the right place to insert the node
        while (current->next != NULL && compare(current->pdu, new_node->pdu) < 0) {
            current = current->next;
        }

        new_node->next = current->next;
        current->next = new_node;
    }
}

void deleteNode(Node **head_ref, int RNTI) { 
    // Store head node 
    Node* temp = *head_ref; 
    Node* prev = NULL; 

    // If head itself holds the key to be deleted 
    if (temp != NULL && compare(temp->pdu, RNTI) == 0) { 
        *head_ref = temp->next; // Changed head 
        free(temp); // Free old head 
        return; 
    } 

    // Search for the key to be deleted, keep track of the previous node as we need to change 'prev->next' 
    while (temp != NULL && compare(temp->pdu, RNTI) != 0) { 
        prev = temp; 
        temp = temp->next; 
    } 

    // If key was not present in linked list 
    if (temp == NULL) return; 

    // Unlink the node from linked list 
    prev->next = temp->next; 

    free(temp); // Free memory 
}

