        Node *node = malloc(sizeof(Node));
        node->pdu = pdu;
        node->next = NULL;

        // Locking to avoid race condition
        pthread_mutex_lock(&mutex); 
        insertNodeSorted(&head, node);
        pthread_mutex_unlock(&mutex);
    }

