```c
#include <pthread.h>
#include <stdlib.h> // For malloc and free

typedef struct LTE_Ngap_UeContext_t {
    int RNTI;
    // Other data fields...
} LTE_Ngap_UeContext_t;

typedef struct DynamicArray {
    pthread_mutex_t mutex;
    LTE_Ngap_UeContext_t** array;
    int size;
    int capacity;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray* da = malloc(sizeof(DynamicArray));
    pthread_mutex_init(&da->mutex, NULL);
    da->array = NULL;
    da->size = 0;
    da->capacity = 0;
    return da;
}

void destroy_dynamic_array(DynamicArray* da) {
    pthread_mutex_destroy(&da->mutex);
    for (int i = 0; i < da->size; ++i) {
        free(da->array[i]);
    }
    free(da->array);
    free(da);
}

void add_context(DynamicArray* da, LTE_Ngap_UeContext_t* context) {
    pthread_mutex_lock(&da->mutex);

    if (da->size == da->capacity) { // Ensure enough capacity for the new element
        da->capacity = (da->capacity == 0) ? 1 : da->capacity * 2;
        da->array = realloc(da->array, sizeof(LTE_Ngap_UeContext_t*) * da->capacity);
    }

    // Check if RNTI already exists in the array to prevent duplicates
    for (int i = 0; i < da->size; ++i) {
        if (da->array[i]->RNTI == context->RNTI) {
            pthread_mutex_unlock(&da->mutex);
            return; // Don't add duplicate RNTIs
        }
    }

    da->array[da->size++] = context; // Add the new context

    pthread_mutex_unlock(&da->mutex);
}

void remove_context(DynamicArray* da, int RNTI) {
    pthread_mutex_lock(&da->mutex);

    for (int i = 0; i < da->size; ++i) {
        if (da->array[i]->RNTI == RNTI) {
            free(da->array[i]); // Free the memory of the removed context

            if (i != --da->size) { // If not removing the last element, move last one to fill the gap
                da->array[i] = da->array[da->size];
            }

            break;
        }
    }

    pthread_mutex_unlock(&da->mutex);
}

void update_context(DynamicArray* da, LTE_Ngap_UeContext_t* new_context) {
    pthread_mutex_lock(&da->mutex);

    for (int i = 0; i < da->size; ++i) {
        if (da->array[i]->RNTI == new_context->RNTI) {
            free(da->array[i]); // Free the old context's memory
            da->array[i] = new_context; // Add the updated context
            break;
        }
    }

    pthread_mutex_unlock(&da->mutex);
}
```
