using System;
using System.IO;
using System.Security.Cryptography;
using System.Threading.Tasks;
using System.Linq;
using System.Text;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;
using Serilog;
using Polly;

public class FileHashGenerator
{
    private int minValue, maxValue;
    private static readonly Random _random = new();
    private SqlConnection connection;

    public FileHashGenerator(int minValue, int maxValue)
    {
        if (minValue > maxValue)
            throw new ArgumentException("Min value should be less than or equal to max value");

        this.minValue = minValue;
        this.maxValue = maxValue;
        connection = new SqlConnection(); //replace with your database connection string
    }

    public float GetRandomFloat() => (float)_random.NextDouble() * (maxValue - minValue) + minValue;

    public int GetRandomInt() => _random.Next(minValue, maxValue + 1);

    public int GetRandomIntExclusiveMax() => _random.Next(minValue, maxValue);

    public override string ToString() => $"Range: [{minValue}, {maxValue}]";

    public void ShuffleValues()
    {
        var arr = Enumerable.Range(minValue, maxValue - minValue + 1).ToArray();
        int n = maxValue - minValue;

        while (n > 1)
        {
            int k = _random.Next(n--);
            (arr[n], arr[k]) = (arr[k], arr[n]); //swap elements at indices n and k
        }
    }

    public async Task<string> GetFileHashAsync(string filePath, HashAlgorithm hashAlgorithm)
    {
        using var stream = File.OpenRead(filePath);
        byte[] buffer = new byte[4096]; //can be adjusted as per requirement
        int bytesRead;

        while ((bytesRead = await stream.ReadAsync(buffer, 0, buffer.Length)) > 0)
            hashAlgorithm.TransformBlock(buffer, 0, bytesRead, buffer, 0);

        hashAlgorithm.TransformFinalBlock(buffer, 0, bytesRead); //final block may be smaller than the usual chunk size

        return BitConverter.ToString(hashAlgorithm.Hash).Replace("-", "").ToLower();
    }

    public async Task<DataTableReader> SendDataToDatabaseAsync(byte[] data)
    {
        // Assuming you're sending the data as a SQL query string, so assuming it's safe to execute here. 
        var command = new SqlCommand(Encoding.UTF8.GetString(data), connection);

        Log.Information("Executing database command: {@Query}", Encoding.UTF8.GetString(data));

        // Retry on transient errors, delay between each retry grows exponentially from 1 sec to 32 sec
        var policy = Policy.Handle<SqlException>()
                            .Or<TimeoutException>()
                            .WaitAndRetryAsync(5, attempt => TimeSpan.FromSeconds(Math.Pow(2, attempt)));

        await connection.OpenAsync();
        await policy.Execute(() => command.ExecuteReader());

        var reader = await command.ExecuteReaderAsync();
        Log.Information("Data sent successfully to database");
        return reader; 
    }
}
```
