    PacketHeader header;
    unsigned char* payload;
} Packet;

Packet* create_packets(int num, const char* ip, Protocol proto, int payload_len) {
    if (num <= 0 || strlen(ip) == 0 || payload_len <= 0) return NULL;

    srand((unsigned int) time(NULL));  // Seed the random number generator.

    Packet* packets = malloc(sizeof(Packet) * num);
    if (packets == NULL) {
        return NULL;
    }

    for (int i = 0; i < num; ++i) {
        // Allocate memory for the IP address string.
        packets[i].header.ip_address = malloc(strlen(ip) + 1);
        if (packets[i].header.ip_address == NULL) {
            // Clean up any allocated memory before returning NULL.
            for (int j = 0; j < i; ++j) free(packets[j].header.ip_address);
            free(packets);
            return NULL;
        }

        strcpy(packets[i].header.ip_address, ip);
        packets[i].header.protocol = proto;
        packets[i].header.payload_length = payload_len;

        // Allocate memory for the payload array.
        packets[i].payload = malloc(sizeof(unsigned char) * payload_len);
        if (packets[i].payload == NULL) {
            // Clean up any allocated memory before returning NULL.
            free(packets[i].header.ip_address);
            for (int j = 0; j < i; ++j) free(packets[j].payload);
            free(packets);
            return NULL;
        }

        // Populate the payload array with random bytes.
        for (int j = 0; j < payload_len; ++j) {
            packets[i].payload[j] = rand() % 256;  // Random byte between 0 and 255.
        }
    }

    return packets;
}
