public class DocumentProcessor {
    private ConcurrentMap<String, String> cache = new ConcurrentHashMap<>(); // cache for document metadata

    public void batchProcessDocuments(List<Path> filePaths) throws IOException, InterruptedException, ExecutionException {
        if (filePaths == null) return;

        ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors()); // create thread pool
        List<Future<DocumentMetadata>> futures = new ArrayList<>();

        for (Path filePath : filePaths) {
            Future<DocumentMetadata> future = executor.submit(() -> processFile(filePath)); // submit task to thread pool
            futures.add(future);
        }

        Instant startTime = Instant.now(); // track overall processing time
        int totalFilesProcessed = 0;
        Set<String> uniqueIDs = ConcurrentHashMap.newKeySet(); // set for unique IDs

        for (Future<DocumentMetadata> future : futures) {
            DocumentMetadata metadata = future.get();

            if(metadata == null) continue; // handle null pointer exceptions

            cache.putIfAbsent(metadata.getId(), metadata.getData()); // update cache with document metadata 
            uniqueIDs.add(metadata.getId());
            totalFilesProcessed++;
        }

        Duration processingTime = Duration.between(startTime, Instant.now()); // calculate overall processing time
        double averageProcessingTimePerDocument = (double) processingTime.toMillis() / totalFilesProcessed; 

        System.out.println("Total documents processed: " + totalFilesProcessed);
        System.out.printf("Average processing time per document in milliseconds: %f%n", averageProcessingTimePerDocument);
        System.out.println("Count of unique document IDs found across all files: " + uniqueIDs.size());

        executor.shutdown(); // shut down thread pool when done processing all files
    }

