    {
        if (min > max) throw new ArgumentException("Invalid range: min is greater than max");

        this.minValue = min;
        this.maxValue = max;
    }

    public void ResetRange(int min, int max) 
    {
        if (min > max) throw new ArgumentException("Invalid range: min is greater than max");

        this.minValue = min;
        this.maxValue = max;
    }

    public override string ToString() 
    {
        return $"Range: [{this.minValue}, {this.maxValue}]";
    }

    // Generate a hash for a large file given its path
    public async Task<string> GetFileHashAsync(string filePath)
    {
        using var hasher = SHA256.Create();

        const int bufferSize = 4096;
        byte[] buffer = new byte[bufferSize];

        using var stream = File.OpenRead(filePath);
        int bytesRead = 0;

        while ((bytesRead = await stream.ReadAsync(buffer, 0, buffer.Length)) > 0)
        {
            hasher.TransformBlock(buffer, 0, bytesRead, buffer, 0);
        }

        // Finalize the hash computation after reading all data
        hasher.TransformFinalBlock(buffer, 0, 0);

        return ConvertHashBytesToString(hasher.Hash);
    }

    private string ConvertHashBytesToString(byte[] bytes)
    {
        StringBuilder builder = new StringBuilder();

        for (int i = 0; i < bytes.Length; i++) 
        {
            builder.Append(bytes[i].ToString("x2"));
        }

        return builder.ToString();
    }
}
