```java
import java.io.*;
import java.security.*;
import java.util.concurrent.*;
import com.google.common.cache.*;
import org.apache.commons.codec.binary.*;

public class FileHashCalculator {
    private static final int CHUNK_SIZE = 4096; // bytes
    private static final int MAX_CONCURRENCY = 10; // Maximum active threads

    private MessageDigest messageDigest;
    private LoadingCache<String, byte[]> cache = CacheBuilder.newBuilder()
            .maximumSize(1000) // Adjust based on capacity and memory constraints
            .build(new CacheLoader<String, byte[]>(){
                @Override
                public byte[] load(String path){
                    return calculateHash(path);
                }
            });
    private ExecutorService executor = Executors.newFixedThreadPool(MAX_CONCURRENCY);

    public FileHashCalculator() throws NoSuchAlgorithmException {
        messageDigest = MessageDigest.getInstance("SHA-256"); // Adjust based on configuration
    }

    public byte[] getFileHash(String path) throws ExecutionException{
        return cache.get(path);
    }

    private byte[] calculateHash(String path){
        try (FileInputStream fileInput = new FileInputStream(new File(path))){
            ReadableByteChannel channel = Channels.newChannel(fileInput);
            ByteBuffer buffer = ByteBuffer.allocate(CHUNK_SIZE);
            while(channel.read(buffer) > 0){
                buffer.flip();
                messageDigest.update(buffer);
                buffer.clear();
            }
            return messageDigest.digest();
        } catch (IOException e){
            // Handle exception and recover if needed
            System.err.println("Error reading file: " + path);
        }
        return null;
    }

    public static void main(String[] args) throws NoSuchAlgorithmException, ExecutionException{
        FileHashCalculator calculator = new FileHashCalculator();
        byte[] hash = calculator.getFileHash("path/to/file"); // Change to your file path
        System.out.println(Hex.encodeHexString(hash));
    }
}
``` 

