} cipher_context;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static cipher_context ctx; // Global context

void init_cipher(const char *password) {
    unsigned char hashed[SHA256_DIGEST_LENGTH];
    pthread_mutex_lock(&mutex);
    if (ctx.ctx == NULL) {
        ctx.ctx = EVP_CIPHER_CTX_new();
        SHA256((unsigned char *)password, strlen(password), hashed); // Generate a key from the password
        memcpy(ctx.key, hashed, SHA256_DIGEST_LENGTH); 
    } else {
        printf("Cipher already initialized!\n");
    }
    pthread_mutex_unlock(&mutex);
}

void cleanup() {
    pthread_mutex_lock(&mutex);
    if (ctx.ctx != NULL) {
        EVP_CIPHER_CTX_free(ctx.ctx); 
        ctx.ctx = NULL; // Reset the context
    } else {
        printf("No cipher to clean up!\n");
    }
    pthread_mutex_unlock(&mutex);
}

void encrypt(unsigned char *plaintext, int plaintext_len, unsigned char *ciphertext) {
    unsigned char iv[IV_SIZE];
    RAND_bytes(iv, IV_SIZE); // Generate a random initialization vector for each operation

    pthread_mutex_lock(&mutex);
    EVP_EncryptInit_ex(ctx.ctx, EVP_aes_256_cbc(), NULL, ctx.key, iv); // Initialize the cipher context with key and IV
    EVP_EncryptUpdate(ctx.ctx, ciphertext, &plaintext_len, plaintext, plaintext_len); // Encrypt the data
    EVP_EncryptFinal_ex(ctx.ctx, ciphertext + plaintext_len, &plaintext_len); // Finalize encryption
    pthread_mutex_unlock(&mutex);
}
