void add_session(SessionManager_t* manager, CallSessionInfo_t* session) {
    pthread_mutex_lock(&manager->lock);

    // Check for duplicate session IDs
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->sessions[i]->id == session->id) return;
    }

    // Resize the array if needed
    if (manager->count >= manager->capacity) {
        manager->capacity *= 2;
        manager->sessions = realloc(manager->sessions, sizeof(CallSessionInfo_t*) * manager->capacity);
    }

    // Add the new session to the array
    manager->sessions[manager->count++] = session;

    pthread_mutex_unlock(&manager->lock);
}

void remove_session(SessionManager_t* manager, int id) {
    pthread_mutex_lock(&manager->lock);

    // Find the index of the session with the given ID and remove it
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->sessions[i]->id == id) {
            free(manager->sessions[i]);  // Free memory
            manager->sessions[i] = manager->sessions[--manager->count];  // Decrease count and move last session to the removed position
            return;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

