CUSTOM_ALLOCATOR_T allocator = {0};

// Custom memory allocation and deallocation functions with thread safety
void* custom_alloc(size_t size) {
  pthread_mutex_lock(&allocator.lock);

  if (atomic_fetch_add(&allocator.count, size) + size > allocator.capacity) {
    pthread_mutex_unlock(&allocator.lock);
    return NULL;
  }

  void *ptr = ((char*)allocator.data) + atomic_fetch_sub(&allocator.count, size);

  pthread_mutex_unlock(&allocator.lock);
  return ptr;
}

void custom_free(void* ptr) {
  if (ptr == NULL || ptr < allocator.data || ptr >= ((char*)allocator.data) + allocator.capacity) {
    // Out of range, ignore free request
    return;
  }

  pthread_mutex_lock(&allocator.lock);
  atomic_fetch_add(&allocator.count, (char*)ptr - ((char*)allocator.data));
  pthread_mutex_unlock(&allocator.lock);
}

// Initialize the list of NFAPI_CRC_INDICATION_PDU_T structures with custom allocator
