    event.protocol = protocol;
    event.payloadLength = payloadLength;
    event.timestamp = time(NULL); // Get the current timestamp
    event.payload = generatePayload(payloadLength); // Generate a random payload of specified length
    event.isHighPriority = false; // Initially mark as not high priority

