// Update an event's priority flag
bool updateEventPriority(int index, bool isHighPriority) {
    if (index < 0 || index >= MAX_EVENTS) {
        printf("Error: Invalid event index.\n");
        return false;
    }

    pthread_mutex_lock(&lock); // Lock the mutex for thread-safe access
    events[index].isHighPriority = isHighPriority;
    pthread_mutex_unlock(&lock); // Unlock the mutex

    return true;
}

// Serialize the traffic event data to a file
void serializeEventsToFile() {
