typedef struct PDUList {
    size_t capacity;
    size_t count;
    _Atomic(NFAPI_L1_RXINFO_T*) *pduArray;
    pthread_mutex_t lock;
} PDUList;

PDUList* createPDULisst(size_t initialCapacity) {
    PDUList* list = malloc(sizeof(PDUList));
    if (list == NULL) return NULL;

    list->capacity = initialCapacity;
    list->count = 0;
    list->pduArray = malloc(initialCapacity * sizeof(NFAPI_L1_RXINFO_T*));
    if (list->pduArray == NULL) {
        free(list);
        return NULL;
    }

    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void destroyPDUList(_Atomic(NFAPI_L1_RXINFO_T*)* list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->pduArray[i]);
    }

    pthread_mutex_destroy(&list->lock);
    free(list->pduArray);
    free(list);
}

void pushPDU(_Atomic(NFAPI_L1_RXINFO_T*)* list, NFAPI_L1_RXINFO_T* pdu) {
    pthread_mutex_lock(&list->lock);

    if (list->count == list->capacity) {
        size_t newCapacity = list->capacity * 2;
        NFAPI_L1_RXINFO_T** newArray = realloc(list->pduArray, newCapacity * sizeof(NFAPI_L1_RXINFO_T*));
        if (newArray == NULL) {
            // log error and handle it appropriately
            pthread_mutex_unlock(&list->lock);
            return;
        }

        list->capacity = newCapacity;
        list->pduArray = newArray;
    }

    list->pduArray[list->count++] = pdu;

    pthread_mutex_unlock(&list->lock);
}
```
