['Here is an example of how such a function could look like. This solution uses `gson` library for JSON parsing/generating and `apache commons lang` for string manipulations and random strings generation. 

This code is quite complex so it can't be fully explained here, but I will outline the major parts:

1) The `generateTransactionId()` function generates a unique transaction ID using timestamp, randomly generated string and version identifier. This is done by combining different components and generating MD5 hash of this combination.
2) The code then checks if the hash length exceeds maximum allowed length and handles it accordingly (currently by truncating to max length). 
3) After that, transactions are grouped by user and summary report is created including total amount and average transaction value per user.
4) Finally, JSON array with updated transactions is returned.

```java
import com.google.gson.*;
import org.apache.commons.lang3.RandomStringUtils;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.text.SimpleDateFormat;
import java.util.*;

public class TransactionProcessor {
    private static final int MAX_HASH_LENGTH = 32; // Change this according to your requirement
    private static final String VERSION = "1";  // Change this for different versions of the system

    public JsonArray processTransactions(JsonArray transactions) throws NoSuchAlgorithmException {
        Map<String, UserTransaction> userTransactionsMap = new HashMap<>();
        SimpleDateFormat dateFormat = new SimpleDateFormat("YYYYMMDDHHmmss");

        for (JsonElement transaction : transactions) {
            JsonObject transactionObj = transaction.getAsJsonObject();

            String username = transactionObj.get("username").getAsString();
            double amount = transactionObj.get("amount").getAsDouble();

            if (!userTransactionsMap.containsKey(username)) {
                userTransactionsMap.put(username, new UserTransaction());
            }

            String transactionId = generateTransactionId(dateFormat);

            while (transactionId.length() > MAX_HASH_LENGTH) {  // If hash is too long, truncate it
                transactionId = transactionId.substring(0, MAX_HASH_LENGTH);
            }

            transactionObj.addProperty("transactionId", transactionId);

            UserTransaction userTransaction = userTransactionsMap.get(username);
            userTransaction.totalAmount += amount;
            userTransaction.transactionsCount++;
        }

        JsonObject summaryReport = new JsonObject();
        for (String username : userTransactionsMap.keySet()) {
            UserTransaction userTransaction = userTransactionsMap.get(username);

            double averageAmount = userTransaction.totalAmount / userTransaction.transactionsCount;

            JsonObject userReport = new JsonObject();
            userReport.addProperty("total", userTransaction.totalAmount);
            userReport.addProperty("average", averageAmount);

            summaryReport.add(username, userReport);
        }

        // Add the summary report to the transactions array
        JsonObject summary = new JsonObject();
        summary.add("summary", summaryReport);
        transactions.add(0, summary);

        return transactions;
    }

    private String generateTransactionId(SimpleDateFormat dateFormat) throws NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        Date date = new Date();
        byte[] hashBytes = md.digest((dateFormat.format(date) + RandomStringUtils.randomAlphanumeric(16) + VERSION).getBytes(StandardCharsets.UTF_8));

        StringBuilder hexString = new StringBuilder();
        for (byte b : hashBytes) {
            hexString.append(Integer.toHexString(0xFF & b));
        }

        return hexString.toString();
    }

    private static class UserTransaction {
        double totalAmount = 0;
        int transactionsCount = 0;
    }
}
``` 
This is a simplified example and may need adjustments based on specific requirements of your project, such as handling different JSON structure or integration with existing systems.
