int maxCacheSize = 1024; // Maximum number of entries in cache
int numEntriesInCache = 0; // Current number of entries in cache

void addToCache(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (numEntriesInCache >= maxCacheSize) {
        NFAPI_CRC_INDICATION_PDU_T* last = cache;
        while (last->next != NULL) {
            last = last->next;
        }
        pthread_mutex_lock(&(last->pdu->lock));
        free(last->pdu); // Free memory from the end of the cache when it's full
        if (last == cache) {
            cache = NULL;
        } else {
            last->next = NULL;
        }
