    ctx->timestamp = 0;
    ctx->message = NULL;
}

struct loggingContextPool* createLoggingContextPool() {
    struct loggingContextPool* pool = malloc(sizeof(struct loggingContextPool));
    atomic_init(&pool->size, 0);
    pthread_mutex_init(&pool->mutex, NULL);
    pool->contexts = NULL;
    return pool;
}

void addLoggingContextToPool(struct loggingContextPool* pool, NFAPI_LOGGING_CONTEXT_T *ctx) {
    pthread_mutex_lock(&pool->mutex);

    int oldSize = atomic_load(&pool->size);
    int newSize = oldSize + 1;

    pool->contexts = realloc(pool->contexts, sizeof(NFAPI_LOGGING_CONTEXT_T*) * newSize);
    pool->contexts[newSize - 1] = ctx;

    atomic_store(&pool->size, newSize);

    pthread_mutex_unlock(&pool->mutex);
}
