pthread_rwlock_t lock = PTHREAD_RWLOCK_INITIALIZER;
SessionRecord** sessions;
int sessionCount = 0;
int maxInactiveDuration; // Load from environment or config file
char* logServiceAPI = "http://logservice.com/api"; // Load from environment or config file

void archiveToLogService(SessionRecord* record) {
    // Call logging service API to archive the session record
}

void processUserSessions(int userId, time_t startTime, time_t lastActiveTimestamp) {
    SessionRecord* newRecord = malloc(sizeof(SessionRecord));
    newRecord->userId = userId;
    newRecord->startTime = startTime;
    newRecord->lastActiveTimestamp = lastActiveTimestamp;

    pthread_rwlock_wrlock(&lock); // Acquire write lock
    ++sessionCount;
    sessions = realloc(sessions, sessionCount * sizeof(SessionRecord*));
    if (sessions == NULL) {
        --sessionCount;
        free(newRecord);
        pthread_rwlock_unlock(&lock); // Release the lock before returning
        return;
    }
    sessions[sessionCount - 1] = newRecord;
    pthread_rwlock_unlock(&lock); // Release the lock
}

void archiveInactiveSessions() {
    time_t currentTime = time(NULL);

    for (int i = 0; i < sessionCount; ++i) {
        pthread_rwlock_rdlock(&lock); // Acquire read lock
        SessionRecord* record = sessions[i];
        if (record->lastActiveTimestamp + maxInactiveDuration <= currentTime) {
            archiveToLogService(record);
        }
        pthread_rwlock_unlock(&lock); // Release the lock
    }
}
