        this.userDBService = userDBService;
        this.restTemplate = new RestTemplate();

        // Create a custom thread pool with dynamic size adjustment
        int initialPoolSize = 10;  // Initial number of threads in the pool
        executorService = Executors.newScheduledThreadPool(initialPoolSize, r -> {
            Thread t = new Thread(r);
            t.setDaemon(true);
            return t;
        });

        // Monitor system resource usage and dynamically adjust the pool size
        ScheduledExecutorService monitorService = Executors.newSingleThreadScheduledExecutor();
        monitorService.scheduleAtFixedRate(() -> {
            OperatingSystemMXBean osBean = ManagementFactory.getOperatingSystemMXBean();
            double cpuUsage = osBean.getProcessCpuLoad() * 100;
            long freeMemory = Runtime.getRuntime().freeMemory();

            // Adjust pool size based on CPU and memory usage
            if (cpuUsage > 90 || freeMemory < 50_000_000) {
                int currentPoolSize = executorService.getCorePoolSize();
                int newPoolSize = (int)(currentPoolSize * 0.75); // Reduce pool size by 25%
                if (newPoolSize < 1) newPoolSize = 1; // Ensure at least one thread
                executorService = Executors.newScheduledThreadPool(newPoolSize, r -> {
                    Thread t = new Thread(r);
                    t.setDaemon(true);
                    return t;
                });
            }
        }, 0, 1, TimeUnit.MINUTES); // Check resource usage every minute
    }

