#include <stdio.h>
#include <pthread.h>
#include <semaphore.h>
#include <time.h>
#include <stdlib.h>

typedef struct {
    int type;
    size_t size;
    int priority;
} ResourceRequest;

// A structure to hold resource information
typedef struct ResourceNode {
    ResourceRequest request;
    void* data;  // Pointer to actual resource
    time_t timestamp;  // Time when the resource was created
    struct ResourceNode* next;
} ResourceNode;

ResourceNode* head = NULL;
ResourceNode* tail = NULL;
size_t totalSize = 0;
pthread_mutex_t lock;
sem_t semaphore;
int maxEntries;  // Maximum number of entries in the resource pool

// Function to add a new resource to the resource pool
void addResource(ResourceRequest request, void* data) {
    ResourceNode* node = (ResourceNode*)malloc(sizeof(ResourceNode));
    node->request = request;
    node->data = data;
    node->timestamp = time(NULL);
    node->next = NULL;

    pthread_mutex_lock(&lock);
    if (totalSize + request.size > 1024 * 1024) {
        // If adding the new resource will exceed total size limit, deallocate resources
        while (totalSize + request.size > 1024 * 1024 && head != NULL) {
            ResourceNode* temp = head;
            head = head->next;
            free(temp);
            totalSize -= temp->request.size;
        }
    }

    if (totalSize + request.size > 1024 * 1024) {
        // If even after deallocating resources, the new resource still exceeds limit, don't add it
        free(node);
        pthread_mutex_unlock(&lock);
        return;
    }

    if (head == NULL) {
        head = node;
        tail = node;
    } else {
        tail->next = node;
        tail = node;
    }

    totalSize += request.size;
    pthread_mutex_unlock(&lock);
}

// Function to handle resource allocation requests
void* resource_manager(void* arg) {
    ResourceRequest request = *((ResourceRequest*)arg);
    void* data = malloc(request.size);  // Allocate memory for the resource

    addResource(request, data);

    return NULL;
}
```

