void* readFile(void *arg) {
    char *filename = (char*)arg;
    FILE *file = fopen(filename, "r");
    if (!file) {
        pthread_mutex_lock(&lock);
        fprintf(logfile, "Failed to open file %s\n", filename);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    char buffer[256];
    while (fgets(buffer, sizeof(buffer), file)) {
        pthread_mutex_lock(&lock);
        ++lineCount;
        fprintf(logfile, "Read line %d: %s", lineCount, buffer);
        pthread_mutex_unlock(&lock);
    }

    fclose(file);
    return NULL;
}

