```C
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct item {
    int id;
    void* metadata; // metadata can be any arbitrary data, adjust as needed
} item_t;

typedef struct bloom_filter {
    pthread_rwlock_t lock;
    size_t capacity;
    item_t** items;
} bloom_filter_t;

bloom_filter_t* create_bloom_filter(size_t capacity) {
    bloom_filter_t* bf = malloc(sizeof(bloom_filter_t));
    if(!bf) return NULL;

    bf->items = calloc(capacity, sizeof(item_t*));
    if(!bf->items) {
        free(bf);
        return NULL;
    }

    bf->capacity = capacity;
    pthread_rwlock_init(&bf->lock, NULL); // initialize the lock

    return bf;
}

void destroy_bloom_filter(bloom_filter_t* bf) {
    for(size_t i = 0; i < bf->capacity; ++i) {
        free(bf->items[i]); // need to free individual items
    }

    pthread_rwlock_destroy(&bf->lock); // destroy the lock
    free(bf->items);
    free(bf);
}

void add_item(bloom_filter_t* bf, item_t* item) {
    if(!bf || !item) return;

    pthread_rwlock_wrlock(&bf->lock); // lock for write operation
    size_t index = item->id % bf->capacity; // hash function is modulo capacity of the array

    if(bf->items[index]) {
        free(item); // duplicates not allowed in this simplified version, so we free new item immediately
    } else {
        bf->items[index] = item;
    }

    pthread_rwlock_unlock(&bf->lock);
}

int check_item(bloom_filter_t* bf, int id) {
    if(!bf) return 0;

    pthread_rwlock_rdlock(&bf->lock); // lock for read operation
    size_t index = id % bf->capacity;

    int result = (bf->items[index] != NULL && bf->items[index]->id == id) ? 1 : 0;

    pthread_rwlock_unlock(&bf->lock);

    return result;
}
```
This is a very basic implementation that uses a read/write lock for synchronization. The `create_bloom_filter` function initializes the bloom filter with a certain capacity and allocates memory for the array of items, while `destroy_bloom_filter` frees all allocated memory.

The `add_item` function adds an item to the bloom filter, using a modulo operation as a simple hash function. If the index in the array is already occupied (indicating a duplicate), it frees the new item immediately.

Finally, the `check_item` function checks if a given ID exists in the bloom filter by hashing the ID and checking if the corresponding slot in the array is not null and contains an item with the same ID. It uses a read lock to avoid blocking other threads while reading.

Remember that this code doesn't handle edge cases, error handling, dynamic resizing or memory fragmentation considerations. Implementing a production-quality bloom filter involves much more complex design decisions such as handling false positives, optimizing for speed and memory usage, implementing a robust garbage collection strategy etc., which are beyond the scope of this task.
