#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <limits.h>

// Define the struct to hold network device configurations
typedef struct {
    char interfaceId[256];
    int bandwidth;
    char modulation[20];
    int supportedChannels;
} NetworkDeviceConfig;

// Define a dynamic array to hold all configurations
typedef struct {
    NetworkDeviceConfig* configs;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} ArrayOfNetworkDeviceConfigs;

ArrayOfNetworkDeviceConfigs array = {NULL, 0, 0, PTHREAD_MUTEX_INITIALIZER};

// Function to add a new configuration
int AddNewConfiguration(const char* interfaceId, int bandwidth, const char* modulation, int supportedChannels) {
    pthread_mutex_lock(&array.mutex);

    if (array.count >= INT_MAX || array.capacity == SIZE_MAX) {
        // Handle the case where maximum device limits are reached
        pthread_mutex_unlock(&array.mutex);
        return -1;
    }

    if (bandwidth < 0 || supportedChannels < 0 || strlen(interfaceId) >= 256 || strlen(modulation) >= 20) {
        // Handle the case where invalid parameters are passed
        pthread_mutex_unlock(&array.mutex);
        return -1;
    }

    if (array.capacity == array.count) {
        size_t newCapacity = array.capacity ? array.capacity * 2 : 4;
        NetworkDeviceConfig* newArray = realloc(array.configs, sizeof(NetworkDeviceConfig) * newCapacity);

        if (!newArray) {
            pthread_mutex_unlock(&array.mutex);
            return -1; // Handle the case where memory allocation fails
        }

        array.capacity = newCapacity;
        array.configs = newArray;
    }

    NetworkDeviceConfig* config = &array.configs[array.count++];
    strcpy(config->interfaceId, interfaceId);
    config->bandwidth = bandwidth;
    strcpy(config->modulation, modulation);
    config->supportedChannels = supportedChannels;

    pthread_mutex_unlock(&array.mutex);
    return 0; // Return success
}

// Function to remove a configuration
int RemoveConfiguration(const char* interfaceId) {
    pthread_mutex_lock(&array.mutex);

    for (size_t i = 0; i < array.count; ++i) {
        if (!strcmp(interfaceId, array.configs[i].interfaceId)) {
            memmove(&array.configs[i], &array.configs[i + 1], sizeof(NetworkDeviceConfig) * (array.count - i - 1));
            --array.count;

            if (array.capacity >= 4 && array.count <= array.capacity / 2) {
                NetworkDeviceConfig* newArray = realloc(array.configs, sizeof(NetworkDeviceConfig) * (array.capacity / 2));

                if (!newArray) {
                    pthread_mutex_unlock(&array.mutex);
                    return -1; // Handle the case where memory allocation fails
                }

                array.configs = newArray;
            }

            pthread_mutex_unlock(&array.mutex);
            return 0; // Return success
        }
    }

    pthread_mutex_unlock(&array.mutex);
    return -1; // Handle the case where interfaceId is not found
}

// Function to update a configuration
int UpdateConfiguration(const char* interfaceId, int bandwidth, const char* modulation, int supportedChannels) {
    pthread_mutex_lock(&array.mutex);

    for (size_t i = 0; i < array.count; ++i) {
        if (!strcmp(interfaceId, array.configs[i].interfaceId)) {
            NetworkDeviceConfig* config = &array.configs[i];
            strcpy(config->interfaceId, interfaceId);

            if (bandwidth != -1) { // If bandwidth is not to be updated, keep the original value
                config->bandwidth = bandwidth;
            }

            if (modulation && modulation[0]) { // If modulation is not to be updated, keep the original value
                strcpy(config->modulation, modulation);
            }

            if (supportedChannels != -1) { // If supportedChannels is not to be updated, keep the original value
                config->supportedChannels = supportedChannels;
            }

            pthread_mutex_unlock(&array.mutex);
            return 0; // Return success
        }
    }

    pthread_mutex_unlock(&array.mutex);
    return -1; // Handle the case where interfaceId is not found
}
```
