typedef struct CallSessionInfo_t {
    // Structure fields here
} CallSessionInfo;

// Custom memory allocator and free function prototypes go here
void* customAlloc(size_t size, size_t alignment);
void customFree(void* ptr);

// Dynamic array structure with mutex for thread safety
typedef struct {
    atomic_int size;
    CallSessionInfo** sessions;
    pthread_mutex_t lock;
} SessionArray;

// Function to add a new session to the dynamic array
void addNewSession(SessionArray* array, CallSessionInfo* session) {
    // Lock mutex before modifying the array
    pthread_mutex_lock(&array->lock);

    int oldSize = atomic_load(&array->size);
    // Allocate memory for a new session and assign it to the array
    array->sessions[oldSize] = customAlloc(sizeof(CallSessionInfo), alignof(CallSessionInfo));
    *array->sessions[oldSize] = *session;

    atomic_fetch_add(&array->size, 1);

    // Unlock mutex after modifying the array
    pthread_mutex_unlock(&array->lock);
}

// Function to remove a session by ID from the dynamic array
void removeSession(SessionArray* array, int id) {
    // Lock mutex before modifying the array
    pthread_mutex_lock(&array->lock);

    int i;
    for (i = 0; i < atomic_load(&array->size); i++) {
        if (array->sessions[i]->id == id) {
            customFree(array->sessions[i]);
            break;
        }
    }

    // Shift elements to fill the gap created by removing an element
    for (; i < atomic_load(&array->size)-1; i++) {
        array->sessions[i] = array->sessions[i+1];
    }

    atomic_fetch_sub(&array->size, 1);

    // Unlock mutex after modifying the array
    pthread_mutex_unlock(&array->lock);
}

// Function to update a session by ID in the dynamic array
void updateSession(SessionArray* array, int id, CallSessionInfo* newSession) {
    // Lock mutex before modifying the array
    pthread_mutex_lock(&array->lock);

    for (int i = 0; i < atomic_load(&array->size); i++) {
        if (array->sessions[i]->id == id) {
            *array->sessions[i] = *newSession;
            break;
        }
    }

    // Unlock mutex after modifying the array
    pthread_mutex_unlock(&array->lock);
}

// Function to deallocate all sessions and the dynamic array itself
void cleanup(SessionArray* array) {
    for (int i = 0; i < atomic_load(&array->size); i++) {
        customFree(array->sessions[i]);
    }

    free(array->sessions);
}
