typedef enum {
    DEVICE_TYPE_A,
    DEVICE_TYPE_B,
    DEVICE_TYPE_C,
} DeviceType;

typedef struct {
    DeviceType type;
    int setting1;
    float setting2;
    char* setting3;
} DeviceConfiguration;

int processAndStoreConfigurationData(char* filename) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        printf("Failed to open configuration file.\n");
        return -1;
    }

    int configCount = 0;
    DeviceConfiguration* configurations = malloc(sizeof(DeviceConfiguration));
    if (configurations == NULL) {
        printf("Memory allocation failed for device configurations array.\n");
        fclose(file);
        return -1;
    }

    char section[50];
    while (fscanf(file, "[%49s", section) == 1) {
        DeviceType type;
        if (strcmp(section, "DEVICE_TYPE_A") == 0) {
            type = DEVICE_TYPE_A;
        } else if (strcmp(section, "DEVICE_TYPE_B") == 0) {
            type = DEVICE_TYPE_B;
        } else if (strcmp(section, "DEVICE_TYPE_C") == 0) {
            type = DEVICE_TYPE_C;
        } else {
            printf("Skipping unknown section: %s\n", section);
            continue;
        }

        DeviceConfiguration* newConfig = realloc(configurations, sizeof(DeviceConfiguration) * (configCount + 1));
        if (newConfig == NULL) {
            free(configurations);
            printf("Memory allocation failed for device configurations array during reallocation.\n");
            fclose(file);
            return -1;
        }
        configurations = newConfig;
        DeviceConfiguration* config = &configurations[configCount];

        if (fscanf(file, " setting1=%d setting2=%f setting3=%ms", &config->setting1, &config->setting2, &config->setting3) != 3) {
            printf("Failed to parse settings for section: %s\n", section);
            free(config->setting3);
            continue;
        }

        configCount++;
    }

    if (configCount == 0) {
        printf("No valid sections found in configuration file.\n");
        fclose(file);
        return -1;
    }

    for (int i = 0; i < configCount; i++) {
        DeviceConfiguration* config = &configurations[i];
        printf("Device %d: Type=%d, Setting1=%d, Setting2=%.2f, Setting3=%s\n", 
               i + 1, config->type, config->setting1, config->setting2, config->setting3);
    }

    fclose(file);

    for (int i = 0; i < configCount; i++) {
        free(configurations[i].setting3);
    }
    free(configurations);

    return 0;
}
```
