['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <assert.h>
#include <time.h>
#define MAX_PAYLOAD 65535
typedef struct Packet {
    int version;
    char *source_ip, *destination_ip;
    size_t payload_size;
    struct Packet *next;
} packet_t;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

packet_t* new_node(int version, char* source_ip, char* destination_ip, size_t payload_size) {
    packet_t *newNode = (packet_t*) malloc(sizeof(packet_t));
    if(!newNode) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    newNode->version = version;
    newNode->source_ip = strdup(source_ip);
    newNode->destination_ip = strdup(destination_ip);
    newNode->payload_size = payload_size;
    newNode->next = NULL;
    return newNode;
}

packet_t* add_node(int version, char* source_ip, char* destination_ip, size_t payload_size) {
    pthread_mutex_lock(&lock);
    packet_t *head = new_node(version, source_ip, destination_ip, payload_size);
    if(!head) {
        fprintf(stderr, "Invalid input parameters\n");
        return NULL;
    }
    pthread_mutex_unlock(&lock);
    return head;
}

void delete_node(packet_t *node) {
    packet_t *temp;
    while(node != NULL) {
        temp = node;
        node = node->next;
        free(temp->source_ip);
        free(temp->destination_ip);
        free(temp);
    }
}
```
