import os
import hashlib
from multiprocessing import Pool

def md5_chunk(filepath):
    # Calculate MD5 for each chunk and return it.

def md5_file(filename, chunksize=1024):
    with open(filename, 'rb') as file:
        pool = Pool()  # Use multiprocessing to spread work on multiple cores.
        hashes = []

        while True:
            chunk = file.read(chunksize)

            if not chunk: break

            hashes.append(pool.apply_async(md5_chunk, args=(chunk,)))

    # Wait for all processes to finish and combine their results.
    pool.close() 
    pool.join()

    return hashlib.md5(''.join([h.get() for h in hashes]).encode()).hexdigest()
