typedef struct {
    MAC_RX_QUEUE_T* queue;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock; // for thread safety
} QueueArray;

QueueArray* createQueue(size_t initialCapacity) {
    assert(initialCapacity > 0);

    QueueArray* qa = malloc(sizeof(QueueArray));
    if (!qa) return NULL; // handle memory allocation failure...

    qa->queue = malloc(initialCapacity * sizeof(MAC_RX_QUEUE_T));
    if(!qa->queue){
        free(qa);
        return NULL; // handle memory allocation failure...
    }

    qa->capacity = initialCapacity;
    qa->size = 0;

    pthread_mutex_init(&qa->lock, NULL);

    return qa;
}

int push(QueueArray* qa, MAC_RX_QUEUE_T item) {
    assert(qa != NULL);

    pthread_mutex_lock(&qa->lock);
    if (qa->size == qa->capacity) {
        size_t newCapacity = qa->capacity * 2; // double capacity on full queue
        MAC_RX_QUEUE_T* temp = realloc(qa->queue, newCapacity * sizeof(MAC_RX_QUEUE_T));
        if (!temp) {
            pthread_mutex_unlock(&qa->lock);
            return -1; // handle memory allocation failure...
        }

        qa->queue = temp;
        qa->capacity = newCapacity;
    }

    qa->queue[qa->size++] = item;

    pthread_mutex_unlock(&qa->lock);

    return 0; // success
}
