    free(q->data);
    free(q);
}

int enqueue(dynamic_array_t *q, MAC_RX_QUEUE_T value) {
    pthread_mutex_lock(&q->mutex);  // Lock mutex

    if (q->count == q->capacity) {
        size_t newCapacity = q->capacity * 2;  // Double capacity when full
        MAC_RX_QUEUE_T* tempData = realloc(q->data, newCapacity * sizeof(MAC_RX_QUEUE_T));
