['Below is a basic implementation of the requested features in C. It uses a combination of locks, memory pooling, and error handling. Note that this is a simplified version and may need adjustments based on your actual use case, including performance requirements and the specific details of your sensor data and system architecture. The main points are covered: memory allocation optimization, thread safety, scalability, usability, and error handling.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Define the structure for sensor data 
typedef struct SensorData {
    int id;
    double value;
    struct SensorData* next;
} SensorData;

// Create a mutex to handle concurrent access by multiple threads
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

SensorData* createMemoryPool(int size) {
    // Allocate memory for the pool in one block 
    SensorData *pool = (SensorData *)malloc(sizeof(SensorData) * size);

    if (!pool) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    // Initialize the pool 
    for (int i = 0; i < size; ++i) {
        pool[i].id = -1;   // Indicate that this slot is empty
        pool[i].next = (i == size-1) ? NULL : &pool[i+1];
    }

    return pool;
}

SensorData* allocateMemory(SensorData *head) {
    pthread_mutex_lock(&lock); // Lock the mutex to ensure thread safety

    if (!head) {
        fprintf(stderr, "Pool is empty\n");
        exit(EXIT_FAILURE);  // Handle memory allocation failures gracefully
    }

    SensorData *temp = head;
    head = head->next;

    pthread_mutex_unlock(&lock); // Unlock the mutex after access to the pool

    return temp; // Return the allocated memory block
}

void deallocateMemory(SensorData *node, SensorData **head) {
    if (!(*head)) {
        node->next = NULL;
    } else {
        node->next = *head;
    }

    pthread_mutex_lock(&lock); // Lock the mutex to ensure thread safety

    *head = node;  // Return the memory block back into the pool

    pthread_mutex_unlock(&lock); // Unlock the mutex after access to the pool
}

int main() {
    const int POOL_SIZE = 1000000;

    SensorData *pool = createMemoryPool(POOL_SIZE);
    SensorData *node;

    // Test allocating and deallocating memory
    for (int i = 0; i < POOL_SIZE; ++i) {
        node = allocateMemory(pool);
        printf("Allocated %d\n", node->id);

        if (i % 10 == 0) {
            deallocateMemory(node, &pool);
        }
    }

    return 0;
}
```
This code creates a dynamic memory pool and provides functions for allocating and deallocating memory. It uses locks to ensure thread safety when accessing the pool. The allocation strategy is very basic: it simply returns the first available slot in the pool, which can lead to fragmentation over time. In a real-world scenario, you would likely need a more sophisticated data structure to manage the available slots and prevent or reduce fragmentation.
']

