void init_queue(size_t num) {
    pthread_mutex_lock(&lock);
    if (num > 50000 || num < 1) {
        printf("Invalid number of elements.\n");
        exit(-1);
    }

    queue = malloc(num * sizeof(MAC_RX_QUEUE_T));
    if (!queue) {
        printf("Memory allocation failed.\n");
        exit(-1);
    }

    for (size_t i = 0; i < num; ++i) {
        queue[i].PDCP_PDU = rand();
        queue[i].RX_SEQ_NUMBER = rand();
        queue[i].TX_SEQ_NUMBER = rand();
    }

    size = num;
    pthread_mutex_unlock(&lock);
}

void destroy_queue() {
    free(queue);
    queue = NULL;
    size = 0;
}

int get_size() {
    return size;
}

MAC_RX_QUEUE_T get_element(int idx) {
    pthread_mutex_lock(&lock);

    if (idx < 0 || idx >= size) {
        printf("Index out of bounds.\n");
        exit(-1);
    }

    MAC_RX_QUEUE_T element = queue[idx];

    pthread_mutex_unlock(&lock);

    return element;
}
