#include <stdlib.h>
#include <pthread.h>

typedef struct Frame {
    void* data; // actual frame data
    struct Frame *next, *prev; // linked list for cache management
} Frame;

Frame* allocate_frame() {
    Frame* new_frame = malloc(sizeof(Frame));

    if (new_frame == NULL) {
        // handle error: memory allocation failed
        return NULL;
    }

    // initialize frame data here

    return new_frame;
}

// Use a lock-free linked list for caching recent frames. A fixed-size pool is a good alternative as well.
typedef struct Cache {
    Frame *head, *tail; 
    pthread_mutex_t mutex; // ensure thread safety with this mutex
} Cache;

Frame* cache_get(Cache* cache) {
    pthread_mutex_lock(&cache->mutex);

    Frame* frame = cache->head;
    if (frame != NULL) {
        // remove from the list
        if (frame == cache->tail) {
            cache->tail = frame->prev;
        } else {
            frame->next->prev = frame->prev;
        }

        frame->prev->next = frame->next;
    }

    pthread_mutex_unlock(&cache->mutex);

    return frame;
}

void cache_put(Cache* cache, Frame* frame) {
    pthread_mutex_lock(&cache->mutex);

    if (frame == NULL) {
        // handle error: invalid input
        goto unlock;
    }

    // add to the end of the list
    frame->prev = cache->tail;
    frame->next = NULL;

    if (cache->tail != NULL) {
        cache->tail->next = frame;
    } else {
        cache->head = frame;
    }

    cache->tail = frame;

unlock:
    pthread_mutex_unlock(&cache->mutex);
}
```
This is a basic example and real world implementations could be more complex depending on the specific requirements. Please adapt this code as needed based on your actual needs, such as error handling or thread safety considerations. The memory pool and cache management strategy should also take into account the characteristics of the frames (e.g., resolution, format) to optimize performance.
