typedef struct {
    int key;
    char* value;
} Item;

int load_resource_bundle(const char* path, Item** items) {
    FILE *file = fopen(path, "rb");

    if (file == NULL) {
        perror("Failed to open file: ");
        return -1;
    }

    int count = 0;
    while (!feof(file)) {
        // Read key-value pair from binary file format
        Item* item = malloc(sizeof(*item));
        if (item == NULL) {
            perror("Failed to allocate memory: ");
            fclose(file);
            return -1;
        }

        // Assume key and value are 4 bytes each in the binary file format
        if (fread(&item->key, sizeof(int), 1, file) != 1 ||
            fread(&item->value, sizeof(char*), 1, file) != 1) {

            free(item);
            break;
        }

        *items = realloc(*items, (count + 1) * sizeof(**items));
        if (*items == NULL) {
            perror("Failed to reallocate memory: ");
            fclose(file);
            return -1;
        }

        (*items)[count] = item;
        count++;
    }

    fclose(file);

    // Return number of items
    return count;
}
