['Here's a simple implementation of these requirements. This code has not been thoroughly tested and may have bugs or limitations, but it should give you a starting point for creating your own logging system in C. You might want to add more error checking and exception handling depending on your specific needs. 

```c
#include <stdio.h>
#include <stdarg.h>
#include <pthread.h>
#include <string.h>

enum LogLevel {DEBUG, INFO, WARN, ERROR};

typedef struct {
    const char *name;
    enum LogLevel min_level;
} Logger;

Logger *current_logger = NULL;
size_t max_log_message_size = 1024; // Default maximum log message size is 1KB
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void log_error_message(const char *format, enum LogLevel level, va_list args) {
    pthread_mutex_lock(&lock); // Ensure thread safety

    if (current_logger == NULL || current_logger->min_level > level) {
        pthread_mutex_unlock(&lock); // Release lock before returning
        return;
    }

    char buffer[max_log_message_size];
    int size = vsnprintf(buffer, sizeof(buffer), format, args);
    if (size < 0) {
        pthread_mutex_unlock(&lock); // Release lock before returning on error
        return;
    }

    printf("[%s] %.*s\n", current_logger->name, size, buffer);
    pthread_mutex_unlock(&lock); // Release lock after successful operation
}

int add_logger(Logger *logger) {
    if (current_logger != NULL) return -1; // Return error code if a logger already exists

    current_logger = logger;
    return 0; // Return success code
}

void set_current_logger(Logger *logger) {
    pthread_mutex_lock(&lock); // Ensure thread safety
    current_logger = logger;
    pthread_mutex_unlock(&lock); // Release lock after setting the new logger
}

Logger* get_current_logger(void) {
    return current_logger;
}

void limit_log_message_size(size_t max_size) {
    max_log_message_size = max_size; // Update maximum log message size
}

void ensure_memory_allocation(size_t required_bytes) {
    if (required_bytes > max_log_message_size) {
        limit_log_message_size(required_bytes); // Increase the maximum log message size to fit the new requirement
    }
}
```
This code assumes that you want a single logger at any given time. If multiple concurrent loggers are required, more advanced thread synchronization mechanisms would be necessary. The memory allocation limit is enforced by limiting the buffer size in `log_error_message` to ensure it does not exceed the allocated space for the message and its variable arguments. The logger struct currently supports a minimum logging level but does not support other features like setting log levels or destinations. You might want to extend this struct with additional fields based on your specific requirements.
']

