typedef struct QueueNode {
    NFAPI_RX_INDICATION_PDU_T indication;
    struct QueueNode* next;
} QueueNode;

QueueNode* front = NULL;
int queueSize = 0;
pthread_mutex_t lock; // For thread-safety

void populateIndication(NFAPI_RX_INDICATION_PDU_T* indication, int msgType, size_t payloadSize) {
    if (msgType < 0 || msgType > 127) { // Example for invalid RRC message type. Adjust accordingly
        fprintf(stderr, "Invalid RRC message type\n");
        return;
    }

    if (payloadSize > 65535) { // Example for maximum payload size. Adjust accordingly
        fprintf(stderr, "Payload size exceeded\n");
        return;
    }

    indication->RRC_UE_CONTEXT = malloc(sizeof(void*)); 
    indication->rrc_pdu_tag = (RRC_PDU_TAG*)malloc(sizeof(RRC_PDU_TAG));

    if (!indication->RRC_UE_CONTEXT || !indication->rrc_pdu_tag) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    indication->rrc_pdu_tag->size = payloadSize; // Assuming that this is the size of the payload
}

void addToQueue(NFAPI_RX_INDICATION_PDU_T* indication) {
    pthread_mutex_lock(&lock);

    QueueNode* newNode = (QueueNode*)malloc(sizeof(QueueNode));
    if (!newNode) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }
    newNode->indication = *indication; // Copy the indication to the queue node

    if (queueSize >= 1000) { // Drop the oldest indication if queue is full
        QueueNode* temp = front;
        front = front->next;
        free(temp);
        queueSize--;
    }

    newNode->next = NULL;
    if (!front) {
        front = newNode;
    } else {
        QueueNode* temp = front;
        while (temp->next) {
            temp = temp->next;
        }
        temp->next = newNode;
    }

    queueSize++;
    pthread_mutex_unlock(&lock);
}
```
