import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.stream.*;

class Document {
    String id;
    long processingTime;

    // Constructor, getters, and setters go here...
}

public class BatchProcessor {
    private static final int EXPECTED_DOCUMENTS = 1000000;  // Change as needed
    private ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());

    public void batchProcessDocuments(String[] filePaths) {
        if (filePaths == null) {
            System.out.println("Input array is null.");
            return;
        }

        long start = System.nanoTime();
        List<CompletableFuture<Document>> futuresList =  new ArrayList<>();

        for(String filePath : filePaths) {
            CompletableFuture<Document> completableFuture = 
                CompletableFuture.supplyAsync(() -> processFile(filePath), executor);
            futuresList.add(completableFuture);
        }

        List<Document> documents = new ArrayList<>();
        try {
            documents = CompletableFuture.allOf(futuresList.toArray(new CompletableFuture[0]))
                .thenApply(v -> 
                    futuresList.stream()
                        .map(CompletableFuture::join)
                        .collect(Collectors.toList())
                ).get();
        } catch (Exception e) {
            System.out.println("Error processing files: " + e);
        }

        long end = System.nanoTime();
        double averageProcessingTimePerDocument = 0;
        if(!documents.isEmpty()) {
            averageProcessingTimePerDocument = 1D * (end - start) / documents.size();
        }

        Set<String> uniqueIds = new HashSet<>();
        for(Document document : documents) {
            uniqueIds.add(document.getId());
        }

        System.out.println("Total documents processed: " + documents.size());
        System.out.printf("Average processing time per document: %.2f ms%n", averageProcessingTimePerDocument/1000000);
        System.out.println("Count of unique document IDs found across all files: " + uniqueIds.size());
    }

    private Document processFile(String filePath) {
        long start = System.nanoTime();

        String id;
        try (Stream<String> lines = Files.lines(Paths.get(filePath))) {
            Optional<String> firstLine = lines.findFirst();

            if(!firstLine.isPresent()) {
                System.out.println("Document doesn't contain ID: " + filePath);
                return new Document(null, System.nanoTime() - start);
            }

            id = firstLine.get().split("=")[1]; // Assuming the format is 'id=DOC_ID'. Change as needed.
        } catch (IOException e) {
            throw new RuntimeException(e);
        }

        long end = System.nanoTime();
        return new Document(id, end - start);
    }
}
```
