import java.io.*;
import java.util.concurrent.ConcurrentHashMap;
import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.Random;

public class MacRxQueue {
    private ConcurrentHashMap<Integer, MAC_RX_QUEUE_T> queue = new ConcurrentHashMap<>();
    private final int MAX_SIZE = 50000;
    private String timestamp;

    public MacRxQueue() {
        // Generate a timestamp for this instance
        SimpleDateFormat dateFormat = new SimpleDateFormat("YYYYMMDDHHmmss");
        timestamp = dateFormat.format(new Date());
    }

    public MAC_RX_QUEUE_T getElement(int index) {
        return queue.get(index);
    }

    public void addElement(MAC_RX_QUEUE_T element, int index) {
        if (queue.size() < MAX_SIZE && index >= 0 && index <= MAX_SIZE) {
            queue.put(index, element);
        } else {
            throw new IllegalArgumentException("Index out of bounds or max size exceeded");
        }
    }

    public void removeElement(int index) {
        if (queue.containsKey(index)) {
            queue.remove(index);
        } else {
            throw new IllegalArgumentException("No element found at given index");
        }
    }

    // Deserialization function
    public Object deserializeObject(byte[] data, String className) {
        try (ByteArrayInputStream bais = new ByteArrayInputStream(data); 
             ObjectInputStream ois = new ObjectInputStream(bais)) {
            return Class.forName(className).cast(ois.readObject());
        } catch (IOException | ClassNotFoundException e) {
            throw new RuntimeException("Failed to deserialize object", e);
        } 
    }

    // Filename modification function
    public String modifyFilename(String filename, String fileType) {
        Random random = new Random();
        int randomNumDigits = 1 + random.nextInt(5);

        if (filename.length() + timestamp.length() + randomNumDigits + 1 > MAX_SIZE) {
            throw new IllegalArgumentException("Filename exceeds maximum length after modification");
        }

        return filename + "_" + timestamp 
                + String.format("%0" + randomNumDigits + "d", random.nextInt((int) Math.pow(10, randomNumDigits))) 
                + fileType;
    }
}
```
