#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct RRC_PDU_TAG {
    int msgType;
    size_t payloadSize;
    time_t timestamp;
} RRC_PDU_TAG;

typedef struct NFAPI_RX_INDICATION_PDU_T {
    void* RRC_UE_CONTEXT;
    RRC_PDU_TAG *message;
} NFAPI_RX_INDICATION_PDU_T;

#define MAX_MSG 1024
#define QUEUE_SIZE 1000

NFAPI_RX_INDICATION_PDU_T queue[QUEUE_SIZE];
int front = 0, rear = -1, itemCount = 0;
pthread_mutex_t lock;

// Function to initialize and populate an array of NFAPI_RX_INDICATION_PDU_T structures
NFAPI_RX_INDICATION_PDU_T* initAndPopulate(void *RC_UE_CONTEXT, int msgType, size_t payloadSize) {
    if (payloadSize > 65535 || itemCount >= MAX_MSG){
        return NULL; // Handle error conditions
    } 

    pthread_mutex_lock(&lock); // Lock for thread safety

    // If queue is full, drop oldest indication and move the front pointer
    if(itemCount == QUEUE_SIZE) {
        free(queue[front].message->payloadSize);  // Free dynamically allocated memory
        front = (front + 1) % QUEUE_SIZE;  
        itemCount--;  // Decrement the number of items in queue
    }

    rear = (rear + 1) % QUEUE_SIZE;  // Move the rear pointer
    NFAPI_RX_INDICATION_PDU_T* newIndication = malloc(sizeof(NFAPI_RX_INDICATION_PDU_T));  // Dynamically allocate memory for indication structure

    if (!newIndication) {
        return NULL; // Handle allocation error
    }

    RRC_PDU_TAG* newMessage = malloc(sizeof(RRC_PDU_TAG));  // Dynamically allocate memory for message

    if (!newMessage) {
        free(newIndication);
        return NULL; // Handle allocation error
    }

    newMessage->msgType = msgType;
    newMessage->payloadSize = payloadSize;
    newMessage->timestamp = time(NULL);

    newIndication->RRC_UE_CONTEXT = RC_UE_CONTEXT;
    newIndication->message = newMessage;

    queue[rear] = *newIndication;  // Add the indication to the rear of queue
    itemCount++;  // Increment the number of items in queue

    pthread_mutex_unlock(&lock); // Unlock for thread safety

    return newIndication;
}
```

