            var buffer = new byte[bufferSize];

            long totalRead = 0;
            using (var stream = File.OpenRead(filePath))
            {
                int bytesRead;

                while ((bytesRead = await stream.ReadAsync(buffer, 0, buffer.Length).ConfigureAwait(false)) != 0)
