#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int max;
    float average;
} Result;

void process_input(Result (*callback)(int *arr, int n)) {
    int size = 0;
    int capacity = 10;  // initial capacity
    int* arr = malloc(capacity * sizeof(*arr));

    if (arr == NULL) {
        printf("Memory allocation failed.\n");
        return;
    }

    int num;
    while (scanf("%d", &num) == 1) {
        // Resize array when full
        if (size >= capacity) {
            capacity *= 2;
            arr = realloc(arr, capacity * sizeof(*arr));

            if (arr == NULL) {
                printf("Memory allocation failed.\n");
                return;
            }
        }

        arr[size++] = num;
    }

    Result result = callback(arr, size);
    printf("Max number: %d\n", result.max);
    printf("Average: %f\n", result.average);

    free(arr);
}

Result find_largest_and_average(int *arr, int n) {
    Result result;
    int sum = 0;

    if (n <= 0 || arr == NULL) {
        result.max = -1;
        result.average = -1.0f;

        return result;
    }

    result.max = arr[0];

    for (int i = 0; i < n; i++) {
        if (arr[i] > result.max) {
            result.max = arr[i];
        }

        sum += arr[i];
    }

    result.average = (float)sum / n;
    return result;
}
```
