typedef struct PATIENT_RECORD_T {
    int PATIENT_ID;
    char* NAME;
    int AGE;
    char* DIAGNOSIS;
    char** MEDICATION_LIST;
} PATIENT_RECORD_T;

typedef struct Config {
    int retryLimit;
    int cacheExpirationTime;
    int dbConnectionTimeout;
    // Add more configuration options as needed.
} Config;

typedef struct CacheNode {
    atomic_uint refCount;
    time_t lastAccessed;
    PATIENT_RECORD_T* data;
    struct CacheNode* prev, * next;
} CacheNode;

CacheNode* cacheHead = NULL, * cacheTail = NULL;
int maxCacheSize = 1000; // Default maximum cache size.
pthread_mutex_t cacheMutex = PTHREAD_MUTEX_INITIALIZER;
atomic_uint totalHits = 0, cacheMisses = 0;

// Helper function to add a record to the cache.
void cacheAdd(PATIENT_RECORD_T* record) {
    pthread_mutex_lock(&cacheMutex);
    CacheNode* newNode = malloc(sizeof(CacheNode));
    newNode->data = record;
    atomic_init(&newNode->refCount, 1);
    time(&newNode->lastAccessed);
    if (cacheHead == NULL) {
        cacheHead = cacheTail = newNode;
        newNode->prev = newNode->next = NULL;
    } else {
        newNode->prev = NULL;
        newNode->next = cacheHead;
        cacheHead->prev = newNode;
        cacheHead = newNode;
    }
    if (atomic_load(&totalHits) > maxCacheSize) { // Evict the least recently used node.
        atomic_fetch_add(&cacheMisses, 1);
        CacheNode* last = cacheTail;
        cacheTail = last->prev;
        if (cacheTail != NULL)
            cacheTail->next = NULL;
        else
            cacheHead = NULL;
        free(last);
    }
    pthread_mutex_unlock(&cacheMutex);
}

// Helper function to check the cache for a record.
PATIENT_RECORD_T* cacheCheck(int PATIENT_ID) {
    pthread_mutex_lock(&cacheMutex);
    CacheNode* node = cacheHead;
    while (node != NULL && node->data->PATIENT_ID != PATIENT_ID)
        node = node->next;
    if (node == NULL) {
        atomic_fetch_add(&cacheMisses, 1);
        pthread_mutex_unlock(&cacheMutex);
        return NULL; // Record not found in cache.
    } else {
        node->refCount++;
        time(&node->lastAccessed);
        atomic_fetch_add(&totalHits, 1);
        pthread_mutex_unlock(&cacheMutex);
        return node->data; // Record found in cache.
    }
}

