void initializeTransactionRecord(int id, double txPower, double rxPower) {
    pthread_mutex_lock(&mutex);
    ++arraySize;
    transactionArray = realloc(transactionArray, arraySize * sizeof(*transactionArray));
    if (!transactionArray) {
        perror("Failed to allocate memory for new transaction");
        exit(EXIT_FAILURE);
    }
    MAC_TRANSACTION_RECORD* record = &transactionArray[arraySize - 1];
    record->TRANSACTION_ID = id;
    record->TX_POWER = txPower;
    record->RECEIVER_POWER = rxPower;
    record->TIMESTAMP = time(NULL);
    pthread_mutex_unlock(&mutex);
}
