    PDCP_PDU pdu;
    RX_SEQ_NUMBER rxSeqNumber;
    TX_SEQ_NUMBER txSeqNumber;
} MAC_RX_QUEUE_T;

// Custom dynamic array
typedef struct {
    MAC_RX_QUEUE_T* data;
    size_t size;
    size_t capacity;
    atomic_int lock; // used for synchronization
} DynamicArray;

// Memory pool to optimize memory usage
typedef struct {
    void* pool;
    size_t size;
    size_t remaining;
    pthread_mutex_t mutex;
} MemoryPool;

MemoryPool memoryPool = {NULL, 0, 0};

// Initialize a dynamic array of MAC_RX_QUEUE_T structures with custom memory pool
int initDynamicArray(DynamicArray* arr) {
    if (arr == NULL) return -1; // error: invalid argument

    pthread_mutex_lock(&memoryPool.mutex);

    // If no more space in the pool, allocate new memory
    if (memoryPool.remaining < sizeof(MAC_RX_QUEUE_T)) {
        size_t additionalSize = 50000 * sizeof(MAC_RX_QUEUE_T);
        void* newMemory = mmap(NULL, additionalSize, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (newMemory == MAP_FAILED) {
            pthread_mutex_unlock(&memoryPool.mutex);
            return -2; // error: allocation failed
        }

        memoryPool.pool = newMemory;
        memoryPool.size += additionalSize;
        memoryPool.remaining = additionalSize;
    }

    arr->data = memoryPool.pool + (memoryPool.size - memoryPool.remaining); // assign from end of pool
    memoryPool.remaining -= sizeof(MAC_RX_QUEUE_T);

    pthread_mutex_unlock(&memoryPool.mutex);

    arr->capacity = 50000;
    arr->size = 0;
    atomic_init(&arr->lock, 0); // initialize lock
    return 0; // success
}
```
