PacketsArray_t gPacketsArray;

// Initialize packet array and its lock, call this function before any other calls to the array
void initPackets() {
    pthread_mutex_init(&gPacketsArray.mutex, NULL);
    gPacketsArray.size = 0;
    gPacketsArray.packets = malloc(sizeof(PacketInfo_t*)); // Start with 1 slot for now
}

// Allocate and initialize a new packet
PacketInfo_t* createNewPacket(char* ipAddress, ProtocolType type, int payloadLength) {
    PacketInfo_t* packet = malloc(sizeof(PacketInfo_t));

    // Initialize the packet with given data
    packet->ipAddress = strdup(ipAddress);
    packet->type = type;
    packet->payloadLength = payloadLength;

    // Allocate memory for payload and generate random byte sequence
    packet->payload = malloc(payloadLength);
    srand(time(NULL)); // Initialize seed for rand()
    for (int i = 0; i < payloadLength; ++i) {
        packet->payload[i] = rand() % 256; // Random byte value between 0 and 255
    }

    return packet;
}

// Add a new packet to the array, ensuring thread safety with locking
void addPacket(char* ipAddress, ProtocolType type, int payloadLength) {
    PacketInfo_t* packet = createNewPacket(ipAddress, type, payloadLength);

    pthread_mutex_lock(&gPacketsArray.mutex); // Lock array for thread safety

    // Expand the array if necessary and add new packet to the end
    gPacketsArray.packets = realloc(gPacketsArray.packets, (gPacketsArray.size + 1) * sizeof(PacketInfo_t*));
    gPacketsArray.packets[gPacketsArray.size++] = packet;

    pthread_mutex_unlock(&gPacketsArray.mutex); // Unlock array after modification
}

// Mark a packet as urgent, ensuring thread safety with locking
void markAsUrgent(int index) {
    if (index < 0 || index >= gPacketsArray.size) {
        printf("Error: Invalid packet index\n");
        return;
    }

    pthread_mutex_lock(&gPacketsArray.mutex); // Lock array for thread safety

    gPacketsArray.packets[index]->isUrgent = true;

    pthread_mutex_unlock(&gPacketsArray.mutex); // Unlock array after modification
}
