['Here's a C# implementation of your task using `lock` to make sure it's thread safe:

```csharp
using System;
using System.Threading;

public class RandomValueGenerator
{
    private readonly int _min;
    private readonly int _max;
    private static readonly object Lock = new object();
    private readonly ThreadLocal<Random> _random = new ThreadLocal<Random>(() => new Random());

    public RandomValueGenerator(int min, int max)
    {
        if (min > max) throw new ArgumentException("Minimum value cannot be greater than maximum value");

        _min = min;
        _max = max;
    }

    private double NextDouble()
    {
        lock(Lock) return _random.Value.NextDouble();
    }

    public int GetRandomInt(bool inclusive=false)
    {
        if (inclusive) 
            return _min + (int)(NextDouble() * (_max - _min + 1));

        lock(Lock){
            var range = _max - _min;
            return _min + (int)(_random.Value.NextDouble() * range);
        }
    }

    public double GetRandomFloat(bool inclusive=false)
    {
        if (inclusive) 
            return _min + NextDouble() * (_max - _min + 1);

        lock(Lock){
            var range = _max - _min;
            return _min + _random.Value.NextDouble() * range;
        }
    }

    public Tuple<int, int> GetExclusiveRangeValues()
    {
        lock(Lock)
        {
            var firstNumber = _random.Value.Next(_max);
            var secondNumber = _random.Value.Next(_max - 1);

            if (secondNumber >= firstNumber) 
                secondNumber += 1;

            return new Tuple<int, int>(firstNumber, secondNumber);
        }
    }

    public override string ToString()
    {
        lock(Lock){
            return $"Min: {_min}, Max: {_max}";
        }
    }
}
```
This code generates a thread-safe `Random` instance for each thread using `ThreadLocal<T>` and ensures that only one thread can modify the state of this instance at any given time. The `NextDouble()` method is thread-safe because it's invoked inside a lock statement. 

Also, the constructor now throws an exception when the minimum value is greater than the maximum to handle invalid inputs.
']

