MAC_RX_QUEUE_T* queue;
int currentSize = 0;
int maxSize = 50000;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void initQueue() {
    queue = malloc(maxSize * sizeof(MAC_RX_QUEUE_T));
}

// Function to dynamically resize the array when full or when load decreases.
void resizeQueue(int newSize) {
    pthread_mutex_lock(&mutex);
    MAC_RX_QUEUE_T* temp = realloc(queue, newSize * sizeof(MAC_RX_QUEUE_T));
    if (temp != NULL) {
        queue = temp;
        maxSize = newSize;
    } else {
        // Handle error: reallocation failed.
    }
    pthread_mutex_unlock(&mutex);
}

// Function to add a new element to the queue.
void enqueue(MAC_RX_QUEUE_T elem) {
    pthread_mutex_lock(&mutex);
    if (currentSize == maxSize) resizeQueue(maxSize * 2); // Double the size when full.
    queue[currentSize++] = elem;
    pthread_mutex_unlock(&mutex);
}

// Function to remove and return an element from the queue.
MAC_RX_QUEUE_T dequeue() {
    pthread_mutex_lock(&mutex);
    if (currentSize <= maxSize / 2) resizeQueue(maxSize / 2); // Halve size when load is low.
    MAC_RX_QUEUE_T elem = queue[--currentSize];
    memset(&queue[currentSize], 0, sizeof(MAC_RX_QUEUE_T)); // Clear the memory for reuse.
    pthread_mutex_unlock(&mutex);
    return elem;
}
```
