```c
#include <stdio.h>
#include <openssl/md5.h>
#include <pthread.h>
#include <time.h>
#include <unistd.h>

// Struct to hold the string and timestamp
typedef struct {
    char str[1024];
    clock_t time;
} StringWithTimeStamp;

// Global data structures for hash map, mutex lock, total count, and average time.
StringWithTimeStamp hashes[65536] = { 0 };
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
unsigned long total = 0;
double avg_time = 0.0;

// Function to compute MD5 hash and add it to the hash map if not already there
void *computeHash(void *arg) {
    StringWithTimeStamp *s = (StringWithTimeStamp *) arg;

    // Get current time before processing
    clock_t start = clock();

    unsigned char md5[MD5_DIGEST_LENGTH];
    MD5((unsigned char*)&s->str, strlen(s->str), md5);

    pthread_mutex_lock(&lock);
        if (hashes[(int)md5[0]].time == 0) { // check if hash not in map
            hashes[(int)md5[0]] = *s;      // add to map
            total++;                      // increment total count
            avg_time += ((double)(clock() - start)) / CLOCKS_PER_SEC; // calculate and add time 
        }
    pthread_mutex_unlock(&lock);

    return NULL;
}

int main(int argc, char **argv) {
    if (argc == 1) {       // If no arguments, print number of lines in file.
        FILE *file = fopen("input.txt", "r");
        int ch = 0;
        while (!feof(file))
            if ((ch = fgetc(file)) == '\n') total++;
        fclose(file);
    } else {               // Otherwise, compute hash for each line in file and print.
        FILE *file = fopen(argv[1], "r");
        char buffer[1024];

        while (fgets(buffer, sizeof(buffer), file) != NULL) {
            StringWithTimeStamp s;
            strcpy(s.str, buffer);

            pthread_t thread;
            pthread_create(&thread, NULL, computeHash, &s);
        }

        fclose(file);
    }

    printf("Total unique hashes: %lu\n", total);
    printf("Average processing time per hash: %f sec\n", avg_time / total);

    return 0;
}
```
This code simply reads each line from an input file and creates a separate thread for computing the MD5 hash of that line. It uses a mutex to ensure that updates to the `hashes` map are atomic, updating the total count and average processing time accordingly when a new hash is added to the map. 

Please note:
1. You need to install openssl library using `sudo apt-get install libssl-dev` for MD5 computation function.
