```c
#include <stdarg.h>
#include <pthread.h>

enum LogLevel {
    DEBUG,
    INFO,
    WARN,
    ERROR
};

typedef struct Logger {
    const char *name;
    enum LogLevel min_level;
    size_t max_size;
} Logger;

Logger *current_logger = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void log_error_message(const char *format, ...) {
    va_list args;
    va_start(args, format);

    pthread_mutex_lock(&lock);

    if (current_logger != NULL && current_logger->min_level <= ERROR) {
        char buffer[current_logger->max_size];
        vsnprintf(buffer, current_logger->max_size, format, args);

        // You should add your own code here to log the message.
    }

    pthread_mutex_unlock(&lock);
}

int set_current_logger(Logger *logger) {
    if (logger == NULL) return -1;

    pthread_mutex_lock(&lock);
    current_logger = logger;
    pthread_mutex_unlock(&lock);

    return 0;
}

void set_log_level_for_logger(enum LogLevel level) {
    pthread_mutex_lock(&lock);

    if (current_logger != NULL) current_logger->min_level = level;

    pthread_mutex_unlock(&lock);
