        return 1;
    }

    for(p = servinfo; p != NULL; p = p->ai_next) {
        h = (struct sockaddr_in *) p->ai_addr;
        strcpy(ipstr, inet_ntoa(h->sin_addr)); 
    }

    freeaddrinfo(servinfo); // free the linked list
    return 0;
}
```
