// Forward declaration
typedef struct LTE_DL_FRAMEINFO LTE_DL_FRAMEINFO;

struct DynamicArray {
    size_t currentSize;
    size_t maxSize;
    pthread_mutex_t lock;
    LTE_DL_FRAMEINFO* array;
};

void InitDynamicArray(struct DynamicArray* dynArr, size_t initialSize) {
    assert(initialSize > 0);

    // Allocate memory for the dynamic array and initialize its fields
    dynArr->array = malloc(sizeof(LTE_DL_FRAMEINFO) * initialSize);
    dynArr->currentSize = 0;
    dynArr->maxSize = initialSize;

    // Initialize mutex for thread safety
    if (pthread_mutex_init(&dynArr->lock, NULL) != 0) {
        free(dynArr->array);
        assert(0 && "Mutex init failed!");
    }
}

void AddToDynamicArray(struct DynamicArray* dynArr, LTE_DL_FRAMEINFO element) {
    pthread_mutex_lock(&dynArr->lock);  // Acquire lock

    if (dynArr->currentSize >= dynArr->maxSize) {
        LogError("Dynamic array limit reached, cannot add more elements!");
        return;
    }

    // Add element to the dynamic array
    dynArr->array[dynArr->currentSize++] = element;

    pthread_mutex_unlock(&dynArr->lock);  // Release lock
}
```

