using System;

public class CustomRandomGenerator {
    private int minValue, maxValue;

    public CustomRandomGenerator(int minValue, int maxValue) {
        if (minValue > maxValue) throw new ArgumentException("Invalid range");

        this.minValue = minValue;
        this.maxValue = maxValue;
    }

    public float GenerateFloat() {
        Random random = new Random();
        return (float)(random.NextDouble() * (this.maxValue - this.minValue) + this.minValue);
    }

    public int GenerateInteger() {
        Random random = new Random();
        return random.Next(this.minValue, this.maxValue + 1);
    }

    public override string ToString() {
        return $"Range: [{this.minValue}, {this.maxValue}]";
    }
}
