['Here's an example implementation of such a feature in C using pthread mutex for thread-safe operation, variadic arguments for dynamic logging, and fixed buffer for log entry size limitation. This code also uses a simple file rotation mechanism for handling large logs. For the existing logging framework integration, only the basic setup of `log_init` and `log_close` are provided:

```c
#include <pthread.h>
#include <stdarg.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

enum LogLevel {DEBUG, INFO, WARNING, ERROR};

typedef struct {
    char* log_file;
    FILE* file_handle;
    enum LogLevel level;
    size_t max_entry_size;
    pthread_mutex_t lock;
} Logger;

Logger logger;

void log_init(const char* config_file) {
    // Implement configuration setup with a JSON file for example.

    /* Set up logger parameters here */
}

void log_close() {
    if (logger.file_handle != NULL)
        fclose(logger.file_handle);

    pthread_mutex_destroy(&logger.lock);
}

const char* level_strings[] = {"DEBUG", "INFO", "WARNING", "ERROR"};

void log_message(enum LogLevel level, const char* message, ...) {
    if (level < logger.level) return; // Ignore lower levels than set in configuration.

    pthread_mutex_lock(&logger.lock);

    time_t now = time(NULL);
    struct tm *timeinfo = localtime(&now);

    char buffer[logger.max_entry_size];
    int prefix_len = strftime(buffer, sizeof(buffer), "%F %T ", timeinfo);

    va_list args;
    va_start(args, message);
    vsnprintf(buffer + prefix_len, sizeof(buffer) - prefix_len, message, args);
    va_end(args);

    fputs(level_strings[level], logger.file_handle);
    fputs(": ", logger.file_handle);
    fputs(buffer, logger.file_handle);
    fputs("\n", logger.file_handle);
    fflush(logger.file_handle); // Flush to disk immediately.

    pthread_mutex_unlock(&logger.lock);
}
```
The `log_init` function can be used to initialize the logging framework, and `log_message` is then used for actual logging:

```c
