public class PokemonTypeService {
    private static final String API_URL = "https://pokeapi.co/api/v2/type";

    // Using Guava Cache to cache the responses from external API
    LoadingCache<String, TypeStats> cache; 

    public PokemonTypeService() {
        this.cache = CacheBuilder.newBuilder()
            .maximumSize(100)
            .expireAfterWrite(24, TimeUnit.HOURS) // update frequency can be adjusted here
            .build(new CacheLoader<String, TypeStats>() { 
                public TypeStats load(String key) throws Exception { 
                    return getTypeStatsFromAPI(key); 
                }
        });
    }

    private static class TypeStats{
        String[] weaknesses;
        String[] resistances;
        String[] immunities;

        public TypeStats(String[] w, String[] r, String[] i){
            this.weaknesses = w;
            this.resistances = r;
            this.immunities = i;
        }
    }

    private TypeStats getTypeStatsFromAPI(String type) throws Exception {
        CloseableHttpClient httpclient = HttpClients.createDefault();
        HttpGet httpget = new HttpGet(API_URL + "/" + type);
        try (CloseableHttpResponse response = httpclient.execute(httpget)) {
            if (response.getStatusLine().getStatusCode() == HttpStatus.SC_OK) {
                String jsonResponse = EntityUtils.toString(response.getEntity());
                // parse the json response and get weaknesses, resistances, immunities 
                // this depends on the structure of API's response 
            } else {
                throw new Exception("Unexpected status code: " + response.getStatusLine().getStatusCode());
            }
        }
    }

    public String processPokemon(List<Pokemon> pokemons) throws ExecutionException, InterruptedException {
        Gson gson = new Gson(); 
        for (Pokemon poke : pokemons){
            List<String> types = poke.getTypes(); // assume getters and setters exist
            Map<String, TypeStats> typeStatsMap = new HashMap<>();

            for(String type: types){
                Future<TypeStats> future = executorService.submit(() -> cache.getUnchecked(type)); 
                // get the stats from cache or fetch if not present and update the cache  
                TypeStats typeStats = future.get();
                typeStatsMap.put(type, typeStats);
            }

            poke.setTypeStats(typeStatsMap);
        }

        return gson.toJson(pokemons);  // returns a json response
    }
}
```
