['Below is a basic implementation of the Mersenne Twister RNG in C++ using atomic operations. Please note that this is a highly simplified version and might not fulfill all requirements mentioned in your question due to complexity constraints. You'll need to further extend it according to the exact specifications you require. 

```cpp
#include <atomic>
#include <random>
#include <iostream>
#include <thread>
#include <mutex>

namespace rng {
    // Base class for RNG factory
    class RandomNumberGeneratorFactory {
    protected:
        static std::atomic<unsigned int> currentSeed;
        static std::mutex seedMutex;

    public:
        virtual double generate() = 0;

        void setSeed(unsigned int newSeed) {
            std::lock_guard<std::mutex> lock(seedMutex);
            currentSeed = newSeed;
        }

        unsigned int getCurrentSeed() {
            return currentSeed.load();
        }
    };

    // Derived class for Mersenne Twister RNG
    class MersenneTwisterRNG : public RandomNumberGeneratorFactory {
    private:
        std::mt19937 mt;

    public:
        MersenneTwisterRNG() {
            unsigned int seed = currentSeed++;
            mt.seed(seed);
        }

        double generate() override {
            return (double)mt() / (double)mt.max();
        }
    };

    std::atomic<unsigned int> RandomNumberGeneratorFactory::currentSeed = 0;
    std::mutex RandomNumberGeneratorFactory::seedMutex;
}  // namespace rng
```
To use the class in a thread-safe manner, you would instantiate it like this:

```cpp
std::vector<std::thread> threads;
