['```csharp
using System;
using System.Collections.Generic;
using System.Data.SqlClient;
using System.Threading.Tasks;
using Polly;
using Serilog;

public class DataPipeline
{
    private SqlConnection _connection;
    public DataPipeline(SqlConnection connection)
    {
        _connection = connection ?? throw new ArgumentNullException(nameof(connection));
    }

    public async IAsyncEnumerable<T> StreamResults<T>(string sqlCommand, List<KeyValuePair<string, string>> filters)
    {
        var command = new SqlCommand(sqlCommand, _connection);

        foreach (var filter in filters)
            command.Parameters.AddWithValue("@" + filter.Key, filter.Value);

        var policy = Policy
            .Handle<SqlException>()
            .WaitAndRetryAsync(3, retryAttempt => TimeSpan.FromSeconds(Math.Pow(2, retryAttempt)));

        await _connection.OpenAsync();
        using (var reader = await policy.ExecuteAsync(() => command.ExecuteReaderAsync()))
        {
            while (await reader.ReadAsync())
                yield return (T)reader[0]; // Assuming the result is a single column of type T
        }
    }
}
```
This implementation uses Microsoft's Polly library for retry logic, Serilog for logging and async/await for asynchronous operation. It also assumes that your SQL connection string has been properly configured to handle connection pooling, connection timeouts and retry policies. 

Please install the necessary nuget packages by running:
```bash
Install-Package Microsoft.Data.SqlClient
Install-Package Polly
Install-Package Serilog
```
Before you use this, please adjust it as per your requirements and handle logging and error handling properly.
