const express = require('express');
const mongoose = require('mongoose');
let app = express();
app.use(express.json());

// Connect to the database
mongoose.connect("mongodb://localhost/testdb", {useNewUrlParser: true, useUnifiedTopology: true});

let ResourceSchema = new mongoose.Schema({name: String, data: Object}, {versionKey: false});
let Resource = mongoose.model('Resource', ResourceSchema);

// PUT endpoint to update a resource
app.put('/resources/:id', async (req, res) => {
    let id = req.params.id;
    // Validate the incoming request, ensure the resource identifier is correct and data within constraints
    if (!mongoose.Types.ObjectId.isValid(id)) return res.status(400).send('Invalid Resource ID'); 
    if (req.body.name && typeof req.body.name !== 'string') return res.status(400).send('Name must be a string');

    let session = await mongoose.startSession();
    try {
        session.startTransaction();
        // Find and update the resource, handling concurrency with versioning
        let updatedResource = await Resource.findOneAndUpdate({_id: id}, req.body, {new: true, runValidators: true});

        if (!updatedResource) return res.status(404).send('No such Resource');

        // Commit the transaction
        await session.commitTransaction();
        res.send(updatedResource);
    } catch (error) {
        // Rollback on failure, restoring resource state
        await session.abortTransaction();
        res.status(500).send('Update Failed');
    } finally {
        session.endSession();
    }
});

// DELETE endpoint to remove a resource
app.delete('/resources/:id', async (req, res) => {
    let id = req.params.id;
    // Validate the incoming request, ensure the resource identifier is correct
    if (!mongoose.Types.ObjectId.isValid(id)) return res.status(400).send('Invalid Resource ID');

    let session = await mongoose.startSession();
    try {
        session.startTransaction();

        // Find and remove the resource, returning a new default one on success
        let removedResource = await Resource.findOneAndRemove({_id: id});

        if (!removedResource) return res.status(404).send('No such Resource');

        let newDefaultResource = new Resource();  // Create a new resource with default values
        await newDefaultResource.save({session}); 

        // Commit the transaction
        await session.commitTransaction();

        res.status(200).send('Successfully removed');
    } catch (error) {
        // Rollback on failure, restoring resource state
        await session.abortTransaction();
        res.status(500).send('Removal Failed');
    } finally {
        session.endSession();
    }
});

app.listen(3000, () => console.log("Server running on port 3000"));
```

This is a basic example and does not handle all potential edge cases. In production code, you should also include:
- Error handling for unexpected system failures and database connection issues.
- More complex request validation depending on the constraints of your data model.
- Robust logging and monitoring to track performance, handle errors, etc.
- Load testing to ensure that the API can scale up to support a growing number of requests.
']

