public class ConfigurationLoader {
    private static final Logger logger = Logger.getLogger(ConfigurationLoader.class.getName());
    private static Gson gson = new Gson();
    private static MessageDigest sha256Digest;
    static {
        try {
            sha256Digest = MessageDigest.getInstance("SHA-256");
        } catch (NoSuchAlgorithmException e) {
            logger.log(Level.SEVERE, "Error initializing SHA-256 digest", e);
        }
    }
    private static final long MAX_FILE_SIZE = 10 * 1024 * 1024; // 10 MB
    private static Map<URL, Object> cache = Collections.synchronizedMap(new LinkedHashMap<>() {
        @Override
        protected boolean removeEldestEntry(Map.Entry eldest) {
            return size() > getCacheSize();
        }
    });

    private static int getCacheSize(){
      // Implement a method to read the cache size from your configuration manager. 
      // You might have other logic for setting this value, so modify as needed.
      return 100; 
    }

    public static Object loadConfig(URL fileUrl) {
        if (cache.containsKey(fileUrl)) {
            logger.info("Cache hit: " + fileUrl);
            return cache.get(fileUrl);
        }

        try {
            URLConnection connection = fileUrl.openConnection();

            String expectedHash = getExpectedFileHashFromConfigManager(fileUrl); // Implement a method to retrieve the expected hash from your configuration manager
            if (!verifySignature(connection, expectedHash)) {
                logger.warning("Invalid signature for: " + fileUrl);
                return null;
            }

            long size = connection.getContentLength();
            if (size > MAX_FILE_SIZE || size < 0) {
                logger.warning("File too large or length unavailable: " + fileUrl);
                return null;
            }

            InputStream inputStream = new BufferedInputStream(connection.getInputStream());
            String jsonString = IOUtils.toString(inputStream, StandardCharsets.UTF_8);
            Object configObject = gson.fromJson(jsonString, Object.class);

            if (configObject instanceof AppConfig) {
                cache.put(fileUrl, configObject);
                return configObject;
            } else {
                logger.warning("Configuration object is not an instance of AppConfig: " + fileUrl);
                return null;
            }
        } catch (IOException e) {
            logger.log(Level.SEVERE, "Error loading configuration file", e);
            return null;
        } finally {
            gson = null; // Close the JSON deserializer by setting it to null
        }
    }

    private static boolean verifySignature(URLConnection connection, String expectedHash) throws IOException {
        InputStream inputStream = new BufferedInputStream(connection.getInputStream());
        byte[] dataBytes = IOUtils.toByteArray(inputStream);

        String actualHash = DatatypeConverter.printHexBinary(sha256Digest.digest(dataBytes));
        return expectedHash.equalsIgnoreCase(actualHash);
    }

    private static String getExpectedFileHashFromConfigManager(URL fileUrl){
      // Implement this method to retrieve the expected hash from your configuration manager
      return ""; 
    }
}
```
In this code, replace `AppConfig` with whatever class you're expecting in your JSON files. If you don't want any caching behaviour or have an external configuration manager, remove or modify relevant parts of the code.

