class ConfigManager():
    def __init__(self, schema, default_location):
        self.config = {}
        self.schema = schema
        self.default_location = default_location
        self.last_update = 0
        self.cached_config = None

    def load(self, custom_location=None):
        if not custom_location:
            try:
                with open(self.default_location) as f:
                    self.config = json.load(f)
            except Exception as e:
                logging.error("Failed to read default config file")
