                with open(custom_location) as f:
                    self.config = json.load(f)
            except Exception as e:
                logging.error("Failed to read custom config file")
                return False

        if datetime.now() - self.last_update > timedelta(minutes=10):
            try: 
                response = requests.get('https://api.endpoint.com/config')
                api_data = response.json()
                self.cached_config = self.merge(self.config, api_data)
                self.last_update = datetime.now()
            except Exception as e: 
                if not self.cached_config:
                    logging.error("Failed to fetch and merge API data")
                    return False
                else:
                    self.config = self.cached_config # fall back to cached config
        return True

    def apply(self, override):
        try: 
            validate(instance=override, schema=self.schema)
            self.config.update(override)
            logging.info("Configuration overridden")
        except ValidationError as e:
            logging.error(f"Failed to apply override due to validation error {e}")

    def merge(self, dict1, dict2): 
        for key in dict2: 
            if isinstance(dict2[key], dict) and isinstance(dict1.get(key), dict):
                self.merge(dict1[key], dict2[key])
            else: 
                dict1[key] = dict2[key]
        return dict1
```
