```rust
use hyper::Client;
use std::net::ToSocketAddrs;
use futures::FutureExt;
use tokio::net::lookup_host;
use tokio::sync::RwLock;
use std::collections::HashMap;
use tokio::time::Duration;
use hyper::body::HttpBody;
use reqwest::Error as ReqwestError;
use std::error::Error as StdError;

pub struct HttpClient {
    client: Client,
    cache: Cache,
    max_retries: usize,
    backoff_base: Duration,
}

impl HttpClient {
    pub fn new(max_retries: usize, backoff_base: Duration) -> Self {
        let client = Client::new();
        let cache = Cache::default();
        Self { client, max_retries, backoff_base, cache }
    }

    pub async fn get(&self, url: &str) -> Result<HttpBody, ReqwestError> {
        if self.cache.contains(url) {
            return Ok(self.cache.get(url));
        }
        let mut attempt = 0;
        loop {
            match self.client.get(url).send().await {
                Ok(res) => {
                    if res.status() == 200 {
                        self.cache.insert(url, res);
                        return Ok(res);
                    } else {
                        return Err(ReqwestError::StatusCode(res.status()));
                    }
                },
                Err(_) => {
                    if attempt >= self.max_retries {
                        break;
                    }
                    let delay = self.backoff_base * 2u32.pow(attempt);
                    tokio::time::sleep(delay).await;
                    attempt += 1;
                },
            };
        }
    }
}

#[derive(Default)]
pub struct Cache {
    data: RwLock<HashMap<String, HttpBody>>,
}

impl Cache {
    pub async fn insert(&self, url: &str, body: HttpBody) {
        let mut map = self.data.write().await;
        map.insert(url.to_string(), body);
    }

    // Similar methods for contains and get operations...
}
```
This code uses `hyper` as the HTTP client, caches responses in a thread-safe hashmap using `tokio::sync::RwLock`, and implements exponential backoff retries with configurable base delay. However, it doesn't support disabling certificate validation, configuring proxy settings, or LRU or LFU eviction policies for cache management.

For production-ready code, you would want to use a more robust HTTP client library like `reqwest` and consider integrating something like Redis (or another caching service) for persistent storage of cache data. The cache invalidation logic could be implemented in a number of ways depending on the specifics of your application.
