```python
import time
from functools import wraps
from pymongo import MongoClient
import requests
from requests.exceptions import Timeout

client = MongoClient()
db = client['database_name']  # replace with your actual database name
collection = db['collection_name']  # replace with your actual collection name

def retry(ExceptionToCheck, tries=4, delay=3, backoff=2):
    """Retry calling the decorated function using an exponential backoff.
    http://www.saltycrane.com/blog/2009/11/trying-out-retry-decorator-python/"""

    def deco_retry(f):
        @wraps(f)
        def f_retry(*args, **kwargs):
            mtries, mdelay = tries, delay
            while mtries > 1:
                try:
                    return f(*args, **kwargs)
                except ExceptionToCheck:
                    time.sleep(mdelay)
                    mtries -= 1
                    mdelay *= backoff
            return f(*args, **kwargs)
        return f_retry  # true decorator
    return deco_retry

@retry(Timeout, tries=3, delay=2, backoff=2)
def make_transaction(user_id, amount):
    headers = {'Authorization': 'Bearer your-api-token'}
    data = {
        'amount': amount,
        # other transaction details...
