['Here is an example of how you could start implementing this task. This code only handles a basic structure with a few keys and values in the ACF file. The real implementation will be more complex, including error checking for invalid formats, nested structures, memory management, thread safety, etc.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct KeyList {
    char* key;
    char* value;
    struct KeyList *next;
} KeyList;

// Global variable for thread safety
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

KeyList* parseACF(char** keys, int keyCount, char* acfFile, int lastKeyIndex, int verbose) {
    FILE *filePointer;
    char line[1024];
    KeyList *head = NULL;
    KeyList *tail = NULL;
    KeyList *currentNode = NULL;

    filePointer = fopen(acfFile, "r"); // read mode

    if (filePointer == NULL) {
        perror("Error while opening the file.\n");
        return NULL;
    }

    pthread_mutex_lock(&lock);  // Acquire lock for thread safety

    while(fgets(line, sizeof line, filePointer) != NULL) {
        char *key = strtok(line, ":");
        if (key == NULL) continue;  // skip invalid lines

        for(int i = 0; i < keyCount; ++i) {
            if(!strcmp(keys[i], key)) {
                char *value = strtok(NULL, "\n");  // get value

                currentNode = (KeyList*) malloc(sizeof(KeyList));
                currentNode->key = strdup(key);
                currentNode->value = strdup(value ? value : "");
                currentNode->next = NULL;  // end of list initially

                if (head == NULL) {  // first node
                    head = currentNode;
                } else {
                    tail->next = currentNode;
                }
                tail = currentNode;  // update tail for next iteration
            }
        }
    }

    pthread_mutex_unlock(&lock);  // Release lock
    fclose(filePointer);

    if (verbose > 1) {  // Logging information
        printf("Parsed ACF file successfully.\n");
    }

    return head;
}
```
