    if (g_hash_table_lookup(transactions, &transaction.id)) {
        logWarning("Duplicate transaction ID: %d", transaction.id);
        return;
    }

    g_queue_push_tail(queue, &transaction);
    weightedSum += weightFactor;

    if (g_queue_get_length(queue) > 1000) {
