async function AsyncReduction(array, initialValue, callback) {
    try {
        let value = await Promise.resolve(initialValue);
        for (let i = 0; i < array.length; i++) {
            try {
                value = await Promise.race([callback(value, array[i]), value]);
            } catch (error) {
                console.log('Callback error:', error);
            }
        }
        return value;
    } catch (error) {
        console.log('Initial value error:', error);
