```csharp
using System;
using System.Threading.Tasks;
using System.Collections.Generic;
using System.Linq;

public class NetworkDataProcessor {
    private int minValue;
    private int maxValue;
    private object lockObj = new Object(); // used for thread safety

    public NetworkDataProcessor(int min, int max) {
        if (min > max) throw new ArgumentException("Minimum value cannot exceed maximum value");
        this.minValue = min;
        this.maxValue = max;
    }

    public float GenerateFloat() {
        lock (lockObj) { // Ensures thread safety
            Random rand = new Random();
            return (float)rand.NextDouble() * (maxValue - minValue) + minValue;
        }
    }

    public int GenerateIntExcludingMax() {
        lock (lockObj) { // Ensures thread safety
            Random rand = new Random();
            return rand.Next(minValue, maxValue);
        }
    }

    public async Task<List<int>> ShuffleArrayAsync(List<int> array) {
        if (!array.All(x => x >= minValue && x < maxValue)) throw new ArgumentException("Invalid value in array");

        return await Task.Run(() => {
            Random rand = new Random(); // Create a local instance for concurrent usage 

            int n = array.Count;  
            while (n > 1) {  
                n--;  
                int k = rand.Next(n + 1);  
                int value = array[k];  
                array[k] = array[n];  
                array[n] = value;  
            } 

            return array;
        });
    }

    // Data processing and sending to storage methods are omitted for brevity. You can add them according to your specific use case.
}
```

