// Define a task structure with the required fields
typedef struct {
    int (*task)(void*); // Pointer to function
    void* args; // Arguments for the function
    int priority; // Priority of the task
} Task;

// Global variables
pthread_mutex_t mutexQueue;
pthread_cond_t condMaxTasks;
FILE* logFile;
Task tasks[MAX_TASKS]; // Array to store tasks
int numTasks = 0; 
int maxTasks = MAX_CONCURRENT_THREADS;
volatile sig_atomic_t stopExecution = 0;

// Function to handle SIGINT and SIGTERM signals
void signalHandler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        stopExecution = 1; // Set the flag to indicate that execution should be stopped
    }
}

// Function for thread cleanup and resource release
void* cleanupThread(void* arg) {
    pthread_exit(NULL);
}

// Task execution function
void* executeTask(void* arg) {
    int taskIndex = *((int*)arg); // Get the index of the task from arguments

    struct rusage usage;
    getrusage(RUSAGE_SELF, &usage);

    pthread_cleanup_push(cleanupThread, NULL);

