    tasks[numTasks] = *task;
    numTasks++;

    // Signal a waiting thread that a new task is available
    if (numTasks == 1) {
        pthread_cond_signal(&condMaxTasks);
    }

    pthread_mutex_unlock(&mutexQueue);

    return 1; // Return success
}

