public static class DecryptionService
{
    private const int MaxConcurrentDecryptions = 5;

    private static SemaphoreSlim semaphore = new SemaphoreSlim(MaxConcurrentDecryptions, MaxConcurrentDecryptions);

    public static async Task<string> DecryptAsync(string keyId, byte[] encryptedMessage)
    {
        await semaphore.WaitAsync();

        try
        {
            // Load the key and IV from a separate configuration file or other source using `keyId`. 

            var config = LoadKeyConfiguration(keyId);

            using (var desAlg = new TripleDESCryptoServiceProvider())
            {
                desAlg.Mode = CipherMode.CBC;
                desAlg.Padding = PaddingMode.PKCS7;

                var decryptor = desAlg.CreateDecryptor(config.Key, config.IV);

                using (var msDecrypt = new MemoryStream())
                {
                    using (var csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Write))
                    {
                        await csDecrypt.WriteAsync(encryptedMessage);
                    }

                    return Convert.ToBase64String(msDecrypt.ToArray());
                }
            }
        }
        finally
        {
            semaphore.Release();
        }
    }

    public static List<string> ProcessTokenResponsesAndMessages(List<Tuple<string, byte[]>> tokenResponseEncryptedMessagePairs)
    {
        var tasks = new List<Task<string>>();

        foreach (var pair in tokenResponseEncryptedMessagePairs.Take(100))
        {
            var tokenResponseString = pair.Item1;

            try
            {
                var tokenResponse = JsonSerializer.Deserialize<TokenResponse>(tokenResponseString);

                if (string.IsNullOrEmpty(tokenResponse?.access_token) ||
                    string.IsNullOrEmpty(tokenResponse.token_type) || 
                    tokenResponse.expires_in < 0 ||
                    tokenResponse.token_type != "Bearer")
                {
                    throw new ArgumentException("Invalid Token Response");
                }

                tasks.Add(DecryptAsync(tokenResponse.access_token, pair.Item2));
            }
            catch (JsonException)
            {
                throw new ArgumentException("Invalid JSON string for token response");
            }
        }

        Task.WhenAll(tasks).Wait();

        var results = tasks.Select(task => task.Result).ToList();

        return results;
    }
}
```
