use tokio::time::delay_for;
use tokio::sync::RwLock;
use futures::executor::blocking;
use std::error::Error;
use std::thread;
use std::time::Duration;

async fn async_task(id: u32, lock: RwLock<u32>) -> Result<(), Box<dyn Error>> {
    let mut guard = lock.write().await;
    *guard += 1;
    println_sleep(&format![ "Task {} started", id]);
    delay_for(Duration::from_secs(3)).await;
    println_sleep(&format![ "Task {} ended", id]);
    Ok(())
}

fn main() {
    let lock = RwLock::new(0);
    let mut rt = tokio::runtime::Runtime::new().unwrap();

    for i in 1..6 {
        rt.spawn(async_task(i, Arc::clone(&lock)));
    }
}
```

