['Here is an example of how you might structure this function using Rust's `std::env` module for environment variables and `std::fs` module for file system operations:

```rust
use std::env;
use std::fs;
use std::io::ErrorKind;
use log::{info, error};
use lazy_static::lazy_static;
use regex::Regex;

lazy_static_start {
    static ref RE: Regex = Regex::new(r"^\w+(\/\w+)*$").unwrap();
}
lazy_static_end

pub fn manage_config_dir(name: &str, path: Option<&str>) -> std::io::Result<()> {
    let env_var = "CONFIG_DIR";
    let dir_path = match path {
        Some(p) => p.to_string(),
        None => format!["./{}", name],
    };

    if !RE.is_match(&dir_path) {
        return Err(ErrorKind::InvalidInput.into());
    }

    let current = match env::var(env_var) {
        Ok(val) => val,
        Err(_) => "".to_string(),
    };

    if Some(&*dir_path) == current.deref() {
        info_start![format_start![Environment variable {} already set to the desired configuration directory: {}]{}!]
        return Ok(());
    }

    match fs::create_dir_all(&dir_path) {
        Err(e) => {
            error_start![format_start![Error creating configuration directory at path {}: {:?}{}]{}]
            if let ErrorKind::AlreadyExists = e.kind() {
                info_start![format_start![Directory already exists at path {}][]{}]
                return Ok(());
            } else {
                return Err(e);
            }
        },
        _ => (),
    };

    match env::set_var(env_var, &dir_path) {
        Err(e) => {
            error_start![format_start![Failed to set environment variable: {}{}][]{}]
            return Err(e);
        },
        _ => (),
    };

    info_start![format_start![Successfully created configuration directory at path {} and updated environment variable {}][]{}]
    Ok(())
}
```

Please note that: 
- This is a simple implementation and might not cover all edge cases in your real-world use case.
- The `lazy_static` crate is used for thread-safe, one-time initialization of expensive global state.
- The `regex` crate provides regular expressions capabilities in Rust. 

You may need to add this dependencies by adding these lines in your Cargo.toml:

```ini
[dependencies]
lazy_static = "1.4.0"
log = "0.4.8"
regex = "1.2.1"
```
