['Below is a basic implementation of your requested program using Python and some external libraries like pyyaml for YAML parsing and schedule for scheduling tasks. Note that this is just a very basic version, you may need to adapt or extend it according to your exact requirements. 

```python
import yaml
import os
import time
import logging
from functools import wraps
import schedule

class TaskManager:
    def __init__(self):
        self._tasks = {}
        self._logger = self._create_logger()

    @staticmethod
    def _handle_exceptions(func):
        """Decorator to handle exceptions"""
        @wraps(func)
        def wrapper(*args, **kwargs):
            try:
                return func(*args, **kwargs)
            except Exception as e:
                print(f"Task execution failed with error {e}")
        return wrapper

    @staticmethod
    def _create_logger():
        """Create a logger"""
        logger = logging.getLogger('TaskManager')
        logger.setLevel(logging.INFO)
        handler = logging.StreamHandler()
        formatter = logging.Formatter('%(asctime)s - %(name)s - %(levelname)s - %(message)s')
        handler.setFormatter(formatter)
        logger.addHandler(handler)
        return logger

    def register_task(self, task):
        """Register a new task"""
        if not self._tasks.get(task['id']):
            self._logger.info(f"Registering task with id {task['id']}")
            self._tasks[task['id']] = task
        else:
            print("Task already exists.")

    @_handle_exceptions
    def execute_task(self, task_id):
        """Execute a registered task"""
        if not (task := self._tasks.get(task_id)):
            raise ValueError(f"No such task: {task_id}")

        # Execute the task according to its type
        print(f'Executing task with id: {task["id"]}')
        if isinstance(task['script'], str):  # If it's a custom script
            os.system(task['script'])
        elif callable(task['script']):  # If it's a predefined function
            task['script']()

    def list_tasks(self):
        """List all registered tasks"""
        print("Registered tasks:")
        for task in self._tasks.values():
            print(task)

    @staticmethod
    def load_from_yaml(filepath):
        """Load tasks from a YAML configuration file"""
        with open(filepath, 'r') as stream:
            try:
                return yaml.safe_load(stream)
            except yaml.YAMLError as e:
                print(e)

    def schedule_tasks(self):
        """Schedule tasks based on their frequency"""
        for task in self._tasks.values():
            if 'frequency' in task:  # If the task has a specified frequency
                getattr(schedule.every(task['frequency']['value']), task['frequency']['unit']).do(self.execute_task, task_id=task['id'])

    def run_scheduled_tasks(self):
        """Run all scheduled tasks"""
        while True:
            schedule.run_pending()
            time.sleep(1)  # Wait one second before checking again
```

In this script, the TaskManager class has a few important methods: register_task(), execute_task(), list_tasks(), load_from_yaml(), and schedule_tasks(). It also includes basic error handling for task failures and logging. The YAML file should be structured like so: 

```yaml
- id: '1'
  script: 'echo "hello world"'
  frequency:
    value: 5
    unit: minutes
- id: '2'
  script: my_function
  dependencies: ['1']
```
The TaskManager class expects a list of task definitions, where each task definition is a dictionary with an 'id', a 'script', and optionally a 'frequency'. The 'script' can be either a string representing a command-line script to run or a function to execute. If the 'script' is a custom script, it should be represented as a string.
']

