        return -1;
    }

    for(int i = 0; i < randNumOfDigits; i++){
        randomNums[i] = '0' + (rand() % 10);
    }
    randomNums[randNumOfDigits] = '\0';

    char *extPoint = strrchr(path, '.');
    if (!extPoint) {
        // handle error here
        free(randomNums);
        return -1;
    }

    int pathLength = extPoint - path;
