    ERROR_INSUFFICIENT_SPACE = -2,
    ERROR_PATH_NOT_VALID = -3,
} ErrorCode;

void logEvent(const char *filename, const char *newFilename, time_t timestamp, ErrorCode error) {
    FILE *logFile = fopen("modification.log", "a");
    if (logFile != NULL) {
        // Log the event in JSON format for easy parsing and searchability
        fprintf(logFile, "{ \"filename\": \"%s\", \"newFilename\": \"%s\", \"timestamp\": %ld, \"errorCode\": %d }\n", filename, newFilename, timestamp, error);

        fclose(logFile);
    }
}

ErrorCode modifyFileName(char *filename, size_t maxLength, const char *fileType) {
    if (strlen(filename) > maxLength) {
        logEvent(filename, "", 0, ERROR_FILENAME_TOO_LONG);
        return ERROR_FILENAME_TOO_LONG;
    }

    time_t timestamp = time(NULL);
    struct tm *timeinfo = localtime(&timestamp);

    char buffer[50];
    strftime(buffer, sizeof(buffer), "%Y%m%d%H%M%S", timeinfo);

    int randomDigits = (rand() % 5) + 1;
    sprintf(buffer + strlen(buffer), ".%ld.%d.", timestamp, randomDigits);

    if (strlen(filename) + strlen(buffer) + strlen(fileType) + 1 > maxLength) {
        // Truncate the filename to fit within the limit
        char *lastDot = strrchr(filename, '.');

        if (lastDot == NULL || lastDot - filename > maxLength) {
            logEvent(filename, "", timestamp, ERROR_FILENAME_TOO_LONG);
            return ERROR_FILENAME_TOO_LONG;
        }

        strcpy(filename + (maxLength - strlen(buffer) - strlen(fileType)), "");
    }

    strcat(filename, buffer);
    strcat(filename, fileType);

    logEvent(filename, filename, timestamp, 0);

    return 0;
}

