void rename_files(char *dir_path, char *ext1, char *ext2) {
    DIR *dir;
    struct dirent *ent;
    int id = 0;

    if ((dir = opendir(dir_path)) != NULL) {
        while ((ent = readdir(dir)) != NULL) {
            char *dot = strrchr(ent->d_name, '.');

            if (dot && !strcmp(dot + 1, ext1)) {
                char oldpath[256];
                snprintf(oldpath, sizeof(oldpath), "%s/%s", dir_path, ent->d_name);

                char newpath[256];
                snprintf(newpath, sizeof(newpath), "%s/%d.%s", dir_path, id++, ext2);

                rename(oldpath, newpath);
            }
        }

        closedir(dir);
    }
}
