typedef struct memoryPool {
    pthread_mutex_t lock;
    void *memoryPtr;
    size_t remainingMemory;
} MemoryPool;

MemoryPool *initializeMemoryPool(size_t poolSize) {
    // Allocate a large chunk of memory
    void *pool = mmap(NULL, POOL_SIZE, PROT_READ | PROT_WRITE, MAP_ANONYMOUS | MAP_PRIVATE, -1, 0);

    if (pool == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }

    MemoryPool *memoryPool = malloc(sizeof(MemoryPool));
    memoryPool->lock = (pthread_mutex_t)PTHREAD_MUTEX_INITIALIZER;
    memoryPool->memoryPtr = pool;
    memoryPool->remainingMemory = poolSize;

    return memoryPool;
}

Frame *allocateFrame(MemoryPool *pool, size_t frameSize) {
    pthread_mutex_lock(&pool->lock);

    if (frameSize > pool->remainingMemory) {
        // Handle error: not enough memory
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }

    Frame *frame = malloc(sizeof(Frame));
    frame->data = pool->memoryPtr;
    pool->remainingMemory -= frameSize;

    pthread_mutex_unlock(&pool->lock);

    return frame;
}

void processVideo() {
    MemoryPool *pool = initializeMemoryPool(POOL_SIZE);
    Frame **frames = malloc(INITIAL_FRAMES * sizeof(Frame*));

