```c
#include <dirent.h>
#include <sys/stat.h>
#include <time.h>
#include <stdio.h>
#include <string.h>

void rename_files(const char* dir, const char* ext) {
    DIR *d;
    struct dirent *dirEntry;
    d = opendir(dir);

    if (d == NULL) {  // handle directory open error
        perror("Could not open directory");
        return;
    }

    while ((dirEntry = readdir(d)) != NULL) {
        char filePath[256];
        snprintf(filePath, sizeof(filePath), "%s/%s", dir, dirEntry->d_name);  // construct full path to the file

        struct stat st;
        if (stat(filePath, &st) == -1) {  // handle file stat error
            perror("Could not get file status");
            continue;
        }

        time_t now = time(NULL);
        double diffInDays = difftime(now, st.st_mtime) / (60 * 60 * 24);  // calculate the last modified date

        if ((diffInDays > 7.0) && strstr(dirEntry->d_name, ext) != NULL) {  // check the last modified date and extension
            char newPath[256];
            snprintf(newPath, sizeof(newPath), "%s/%s", dir, "renamed");  // construct new file name

            if (rename(filePath, newPath) != 0) {  // handle rename error
                perror("Could not rename file");
                continue;
            }
        }
    }

    closedir(d);
