["Here's an example of how you might implement this in C using OpenSSL. This code is relatively complex due to the need for PBKDF2 key derivation, error checking, secure random number generation, and cipher context management. It also has a memory management scheme that allows for multiple simultaneous contexts without data corruption or memory leaks:

```c
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <stdlib.h>

typedef struct CipherContext {
    EVP_CIPHER_CTX* cipher;
    unsigned char key[EVP_MAX_KEY_LENGTH];
    unsigned char iv[EVP_MAX_IV_LENGTH];
} CipherContext;

CipherContext* createCipher(const char* password, const unsigned char* salt, int iterations, int keyLength) {
    if (keyLength < 16 || keyLength > 32) {
        return NULL; // Invalid key length
    }

    CipherContext* context = malloc(sizeof(CipherContext));
    if (!context) {
        return NULL; // Failed to allocate memory
    }

    context->cipher = EVP_CIPHER_CTX_new();
    if (!context->cipher) {
        free(context);
        return NULL; // Failed to create cipher context
    }

    // Generate random IV
    RAND_bytes(context->iv, EVP_CIPHER_CTX_iv_length(context->cipher));

    // Derive key with PBKDF2
    if (!PKCS5_PBKDF2_HMAC_SHA1(password, -1, salt, -1, iterations, keyLength, context->key)) {
        EVP_CIPHER_CTX_free(context->cipher);
        free(context);
        return NULL; // Failed to derive key
    }

    // Initialize cipher with AES256-CBC and set IV and key
    if (!EVP_EncryptInit_ex(context->cipher, EVP_aes_256_cbc(), NULL, context->key, context->iv)) {
        EVP_CIPHER_CTX_free(context->cipher);
        free(context);
        return NULL; // Failed to initialize cipher
    }

    return context;
}

void cleanupCipher(CipherContext* context) {
    if (context) {
        EVP_CIPHER_CTX_free(context->cipher);
        free(context);
    }
}
```
This code creates a new cipher context with the given password and settings, deriving an encryption key using PBKDF2, generates a random IV, and initializes the AES-256-CBC cipher. The `cleanupCipher` function frees the cipher context and any associated memory when it's no longer needed.

Please note that this code is just an example and may need to be adjusted based on your exact requirements, particularly around error handling and edge cases such as incorrect passwords or invalid key lengths. Also, keep in mind that AES-256 with CBC mode can be quite slow when used with small amounts of data, so for performance critical applications you might want to use a different cipher mode or algorithm altogether.
