} AES256_context;

int init_AES256_CBC(const char* password, const unsigned char *salt, int iterations, size_t keylen, AES256_context *ctx) {
    if (keylen < 16 || keylen > 32) {
        printf("Invalid Key Length.\n");
        return 0;
