    if (configurations == NULL) {
        printf("Memory allocation failed.\n");
        fclose(fp);
        return NULL;
    }

    size_t numConfigs = 0;
    // Reading and parsing configuration file...
    while (!feof(fp)) {
        // Read section...
        // Parse fields...
        ++numConfigs;
        DeviceConfiguration *temp = realloc(configurations, numConfigs * sizeof(DeviceConfiguration));
        if (temp == NULL) {
            printf("Memory allocation failed.\n");
            free(configurations);
            fclose(fp);
            return NULL;
        } else {
            configurations = temp;
        }
    }

    *count = numConfigs;
    fclose(fp);
    return configurations;
}
