typedef struct {
    int key;
    long offset;
} Record;

typedef struct Node {
    Record record;
    struct Node* next;
} Node;

typedef struct HashTable {
    pthread_mutex_t lock;  // This is needed for thread safety.
    int size;              // Number of buckets in the hash table.
    Node** data;           // The actual array of buckets.
} HashTable;
```
Now you will need to implement functions that create, delete and manage your hash table:

```C
HashTable* create_hash_table(int size) {
    // Allocate memory for the table struct.
    HashTable* table = malloc(sizeof(HashTable));
    if (!table) {
        return NULL;
    }

    // Initialize the mutex.
    pthread_mutex_init(&table->lock, NULL);

    // Allocate memory for all buckets in the table data array.
    table->data = malloc(sizeof(Node*) * size);
    if (!table->data) {
        free(table);
        return NULL;
    }

    // Set each bucket to be empty.
    for (int i = 0; i < size; ++i) {
        table->data[i] = NULL;
    }

    table->size = size;
    return table;
}

void delete_hash_table(HashTable* table) {
    // Delete each bucket.
    for (int i = 0; i < table->size; ++i) {
        Node* node = table->data[i];
        while (node != NULL) {
            Node* next = node->next;
            free(node);
            node = next;
        }
    }

    // Delete the data array.
    free(table->data);

    // Delete the table struct.
    pthread_mutex_destroy(&table->lock);
    free(table);
}
```
Note: The actual management functions for your hash table (insert, delete, lookup) would also be quite involved and would need to consider thread safety using `pthread_mutex_lock`/`pthread_mutex_unlock`. This is a basic example to give you an idea about how it might start. You would have to handle the dynamic loading of modules, callbacks, error handling and many other aspects in addition to this.
