typedef struct UTB {
    int TBID;
    float SNR;
    int CRC_flag;
    time_t timestamp;
    struct UTB *next;
} UTB;

/* Memory Pool */
UTB* memoryPool[10000];
int poolPointer = 0;

void initMemoryPool() {
    for (int i=0; i<10000; i++) {
        UTB *node = malloc(sizeof(UTB));
        if (!node) {
            // Handle memory allocation error. 
            node->SNR = 50.0f; /* Default SNR value */
            continue;
        }
        node->next = NULL;
        memoryPool[i] = node;
    }
}

void freeMemoryPool() {
    for (int i=0; i<10000; ++i) {
        if (memoryPool[i]) 
            free(memoryPool[i]);
    }
}

UTB* getNewNode() {
    UTB *node = memoryPool[poolPointer++];
    if (!node || node->SNR == 50.0f) {
        // Handle allocation failure or default SNR value
        return NULL;
    } 
    else 
        return node;
}

void addUTB(int TBID, float SNR, int CRC_flag, time_t timestamp, UTB **head) {
    if (poolPointer >= 10000 || !*head) {
        // Manage backpressure and rate-limiting
        return;
    } 
    else {
        UTB *node = getNewNode();
        node->TBID = TBID;
        node->SNR = SNR;
        node->CRC_flag = CRC_flag;
        node->timestamp = timestamp;
        if (*head) 
            node->next = *head; /* Add new UTB to the head of the list */
        else {
            // Handle data duplication from external data source
            *head = node;
        }
    }
}
