```c
#include <pthread.h>
#include <stdlib.h>
#include <time.h>

#define MAX_PAYLOAD 1500 // typical MTU size
#define BUFFER_SIZE 4096 

typedef struct {
    time_t timestamp;
    int packetID;
    char protocol[8];
    unsigned short payloadSize;
    char sourceIP[INET_ADDRSTRLEN], destIP[INET_ADDRSTRLEN];
    uint32_t checksum;
} Packet;

typedef struct {
    pthread_mutex_t mutex;
    int packetCount, rateLimit; // count and limit of packets per second.
    Packet* buffer[BUFFER_SIZE];
    int front, rear; 
} PacketBuffer;

// Initialize the Packet Buffer
void initPacketBuffer(PacketBuffer* pb) {
    pthread_mutex_init(&pb->mutex, NULL);
    pb->packetCount = pb->rateLimit = 0;
    pb->front = pb->rear = 0;
}

// Adding packet to the buffer with rate limiting in mind.
void addPacket(PacketBuffer* pb, Packet* p) {
    time_t currentTime = time(NULL);

    // If more than one second has passed since last packet, reset counter.
    if (currentTime - pb->timestamp >= 1) {
        pb->packetCount = 0;
        pb->timestamp = currentTime;
    } 

    pthread_mutex_lock(&pb->mutex);

    // If packet limit is reached, sleep until a new second.
    while (pb->packetCount >= pb->rateLimit) {
        struct timespec t = {1,0};
        nanosleep(&t, NULL);
    } 

    if ((pb->rear + 1) % BUFFER_SIZE == pb->front) { // Queue is full. Resize?
        resizePacketBuffer(pb);
    }

    pb->buffer[pb->rear] = p;
    pb->rear = (pb->rear + 1) % BUFFER_SIZE; 
    pb->packetCount++;

    pthread_mutex_unlock(&pb->mutex);
}
```
This code illustrates how one might approach a high-throughput packet processing system in C, focusing on concurrency and asynchronous I/O. However, to meet all the requirements you listed, a complex architecture design would be necessary with more intricate handling of threads, error management, logging systems, external libraries for network communication, checksum calculation, etc. 

