    CallSessionInfo_t *session;
    struct Node *next;
}Node;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; 

void manageSessions(char* operation, int sessionId, char* token){
    static Node* sessionsList = NULL; // this will be our linked list to store the sessions

    if (strcmp(operation,"add") == 0){
        CallSessionInfo_t *newSession = malloc(sizeof(CallSessionInfo_t));
        newSession->id = sessionId;
        newSession->token = token; // assuming that this is the session token

        pthread_mutex_lock(&lock);  // using mutex for synchronization

        Node* node = malloc(sizeof(Node));
        node->session = newSession;
        node->next = sessionsList;
        sessionsList = node;

        pthread_mutex_unlock(&lock);  // unlock the mutex
    } else if (strcmp(operation,"remove") == 0){
        pthread_mutex_lock(&lock);

        Node* prevNode = NULL;
        for(Node* node = sessionsList; node != NULL; node = node->next) {
            if(node->session->id == sessionId){
                if(prevNode==NULL){  // first element to be deleted
                    sessionsList = node->next;
                } else {
                    prevNode->next = node->next;  
                }

                free(node->session);  // free session memory
                free(node);           // free node memory
                break;
            }

            prevNode = node;
        }

        pthread_mutex_unlock(&lock);
    } else if (strcmp(operation,"update") == 0){
        pthread_mutex_lock(&lock); 

        for(Node* node = sessionsList; node != NULL; node = node->next) {
            if(node->session->id == sessionId){
                free(node->session->token);  // free old token memory
                node->session->token = token;
                break;
            }
        }

        pthread_mutex_unlock(&lock);
    } else {
        printf("Unknown operation\n");
    }
}

