#include <pthread.h>
#include <stdlib.h>
#include <string.h>

typedef struct LTE_Ngap_UeContext {
    int rnti;
    // other fields here...
} LTE_Ngap_UeContext_t;

typedef struct ContextArray {
    pthread_mutex_t lock;
    size_t capacity;
    size_t count;
    LTE_Ngap_UeContext_t *contexts;
} ContextArray_t;

int ContextArrayInit(ContextArray_t *array, size_t initialCapacity) {
    array->count = 0;
    array->capacity = initialCapacity;

    if (pthread_mutex_init(&array->lock, NULL) != 0) {
        return -1;
    }

    array->contexts = malloc(initialCapacity * sizeof(LTE_Ngap_UeContext_t));
    if (array->contexts == NULL) {
        return -2;
    }

    return 0;
}

int ContextArrayAdd(ContextArray_t *array, LTE_Ngap_UeContext_t context) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        if (array->contexts[i].rnti == context.rnti) {
            pthread_mutex_unlock(&array->lock);
            return -1;  // RNTI already exists
        }
    }

    if (array->count >= array->capacity) {
        LTE_Ngap_UeContext_t *newArray = realloc(array->contexts, array->capacity * 2 * sizeof(LTE_Ngap_UeContext_t));
        if (newArray == NULL) {
            pthread_mutex_unlock(&array->lock);
            return -3; // Failed to resize array
        } else {
            array->contexts = newArray;
            array->capacity *= 2;
        }
    }

    array->contexts[array->count++] = context;

    pthread_mutex_unlock(&array->lock);
    return 0;
}

// Similar functions for remove, update... etc.
```
