#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int RNTI;
} LTE_Ngap_UeContext_t;

typedef struct Node {
    LTE_Ngap_UeContext_t context;
    struct Node *next;
} Node;

Node* head = NULL;
pthread_mutex_t lock;

void add(LTE_Ngap_UeContext_t context) {
    pthread_mutex_lock(&lock);

    Node* newNode = malloc(sizeof(Node));
    memcpy(&newNode->context, &context, sizeof(LTE_Ngap_UeContext_t));
    newNode->next = head;
    head = newNode;

    pthread_mutex_unlock(&lock);
}

void removeByRNTI(int RNTI) {
    pthread_mutex_lock(&lock);

    Node* curr = head, *prev = NULL;
    while (curr != NULL && curr->context.RNTI != RNTI) {
        prev = curr;
        curr = curr->next;
    }

    if (curr == NULL) {
        pthread_mutex_unlock(&lock);
        return;  // No such context exists. Do nothing.
    }

    if (prev != NULL) {
        prev->next = curr->next;
    } else {
        head = head->next;
    }

    free(curr);

    pthread_mutex_unlock(&lock);
}
``` 
Please remember, this is a very simplified example and lacks many aspects of your requirements such as robust error handling, memory efficiency (a linked list might be more efficient if the number of contexts changes frequently), dealing with system dependencies etc. You may need to consider these aspects depending on your specific use case.
