void configureInvertedIndex(const std::vector<Document>& docs, size_t maxSize, int threshold, bool enableCompression) {
    try {
        maxDocSize = maxSize;
        minThreshold = threshold;
        compressionEnabled = enableCompression;

        for (auto & doc : docs) {
            std::string term; 
            int freq;

            // Read input from standard input or another data source, handle empty inputs etc.
            if (term.empty() || freq < minThreshold) continue;

            mtx.lock();  // Acquire lock before modifying shared resource
            auto it = invertedIndex.find(term);

            if (it == invertedIndex.end()) {
                Term* newTerm = compressionEnabled ? new CompressedTerm() : new Term();
                newTerm->setData(term, freq);  // Helper function to set term and frequency data
                invertedIndex[term] = newTerm;
            } else {
                it->second->incrementFrequency(freq);
            }

            mtx.unlock();  // Release lock after modification
        }
