    Term *maxTerm = nullptr;

    for (auto & entry : invertedIndex) {
        if (!maxTerm || maxTerm->getFrequency() < entry.second->getFrequency()) {
            maxTerm = entry.second;
        }
    }

    mtx.unlock();  // Release lock after accessing shared resource

    return maxTerm;
}
