void add_to_list(NFAPI_CRC_INDICATION_PDU_T *new_item) {
    pthread_mutex_lock(&lock);  // acquire the lock

    if (list_size >= max_list_size) {
        printf("Error: List is full\n");
        pthread_mutex_unlock(&lock);  // release the lock and return
        return;
    }

    list[list_size] = new_item;
    list_size++;

    unsigned char data[SHA_DIGEST_LENGTH];
