    char destServiceName[20];
    int requestID;
    double requestDuration;
    int statusCode;
    time_t timestamp;
} LogEntry;

typedef struct {
    pthread_mutex_t mutex;
    size_t maxSize;
    size_t currentSize;
    LogEntry** entries;
} DynamicLogList;

DynamicLogList* createDynamicLogList(size_t maxSize) {
    DynamicLogList* log = malloc(sizeof(DynamicLogList));
    if (log == NULL) return NULL;

    pthread_mutex_init(&log->mutex, NULL);
    log->maxSize = maxSize;
    log->currentSize = 0;
    log->entries = malloc(sizeof(LogEntry*) * maxSize);

    return log;
}

void addLogEntry(DynamicLogList* log, LogEntry* entry) {
    pthread_mutex_lock(&log->mutex);
    if (log->currentSize < log->maxSize) {
        log->entries[log->currentSize] = malloc(sizeof(LogEntry));
        *(log->entries[log->currentSize]) = *entry; // Deep copy
        time(&log->entries[log->currentSize]->timestamp);
        ++log->currentSize;
    }
    pthread_mutex_unlock(&log->mutex);
}

void destroyDynamicLogList(DynamicLogList* log) {
    for (size_t i = 0; i < log->currentSize; ++i)
        free(log->entries[i]);

    pthread_mutex_destroy(&log->mutex);
    free(log->entries);
    free(log);
}
