import java.security.AccessControlException;
import org.apache.commons.collections4.map.HashedMap;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;

public class FileMetadataCache {
    private static final Logger logger = LogManager.getLogger(FileMetadataCache.class);

    private static class Metadata {
        long id;
        LocalDateTime creationTime;
        LocalDateTime lastModifiedTime;
        String accessRights;
        String storageLocation;

        // Constructor, getters and setters omitted for brevity
    }

    private final int maxSize;
    private final HashedMap<Long, WeakReference<Metadata>> cache = new HashedMap<>();
    private long hitCount = 0L;
    private long missCount = 0L;
    private final Object lock = new Object();

    public FileMetadataCache(int maxSize) {
        this.maxSize = maxSize;
    }

    public Metadata get(long id) throws AccessControlException, FileNotFoundException {
        long startTime = System.nanoTime();

        synchronized (lock) {
            WeakReference<Metadata> reference = cache.get(id);

            if (reference != null) {
                Metadata metadata = reference.get();

                if (metadata != null) {
                    hitCount++;
                    logger.info("Cache hit, took {} ns", System.nanoTime() - startTime);
                    return metadata;
                } else {
                    missCount++;
                }
            } else {
                missCount++;
            }
        }

        throw new FileNotFoundException(); // or handle it differently according to your needs
    }

    public void put(Metadata data) throws IllegalStateException {
        synchronized (lock) {
            if (cache.size() >= maxSize) {
                throw new IllegalStateException("Cache is full!");
            }

            cache.put(data.getId(), new WeakReference<>(data));
        }
    }

    public double getHitRate() {
        synchronized (lock) {
            return ((double) hitCount / (hitCount + missCount)) * 100;
        }
    }
}
```

