public class FileMetadataCache {
    private static final int MAX_CACHE_SIZE = 1024 * 1024 * 50; // 50MB
    private ConcurrentHashMap<String, WeakReference<FileData>> cache = new ConcurrentHashMap<>();
    private long hitCount = 0L;
    private long missCount = 0L;
    private long totalTime = 0L;
    private Log log = LogFactory.getLog(this.getClass());
    private Tracer tracer;

    public FileMetadataCache(Tracer tracer) {
        this.tracer = tracer;
    }

    public void addEntry(String fileId, FileData data) {
        if (cache.size() >= MAX_CACHE_SIZE) {
            evict();
        }

        cache.put(fileId, new WeakReference<>(data));
    }

    public Optional<FileData> getEntry(String fileId) {
        long start = System.nanoTime();
        FileData data = null;

        try {
            if (cache.containsKey(fileId)) {
                WeakReference<FileData> weakRef = cache.get(fileId);
                data = weakRef.get();

                if (data != null) {
                    hitCount++;
                    log.debug("Cache hit for file: " + fileId);
                } else {
                    missCount++;
                    log.debug("Cache miss for file: " + fileId);
                }
            } else {
                missCount++;
                log.debug("Cache miss for file: " + fileId);
            }
        } finally {
            long end = System.nanoTime();
            totalTime += (end - start);

            double hitRate = ((double) hitCount / (hitCount + missCount)) * 100;
            log.info("Current hit rate: " + hitRate + "%");
        }

        return Optional.ofNullable(data);
    }

