// Struct to represent timestamp
typedef struct Timestamp {
    int year;
    int month;
    int day;
    int hour;
    int minute;
    int second;
} Timestamp;

// Enum for log levels
typedef enum LogLevel {
    DEBUG, INFO, WARNING, ERROR, CRITICAL
} LogLevel;

// Struct to represent a log entry
typedef struct LogEntry {
    Timestamp timestamp;
    atomic_int refCount; // Reference count
    pthread_mutex_t mutex; // Lock for synchronization
    LogLevel level;
    char* sourceId;
    char* messageContent;
} LogEntry;

// Array to store log entries
LogEntry* logs = NULL;
size_t logCount = 0;
pthread_mutex_t arrayMutex = PTHREAD_MUTEX_INITIALIZER; // Lock for synchronization of the log array

// Initialize a new log entry
LogEntry* createLog(Timestamp timestamp, LogLevel level, const char* sourceId, const char* messageContent) {
    LogEntry* log = malloc(sizeof(LogEntry));
    log->timestamp = timestamp;
    atomic_init(&log->refCount, 1); // Initialize ref count to 1
    pthread_mutex_init(&log->mutex, NULL); // Initialize mutex
    log->level = level;
    log->sourceId = strdup(sourceId);
    log->messageContent = strdup(messageContent);
    return log;
}

// Increment reference count safely
void incrementRefCount(LogEntry* log) {
    pthread_mutex_lock(&log->mutex); // Lock the log entry to ensure safe increment
    ++log->refCount;
    pthread_mutex_unlock(&log->mutex);
}

// Decrement reference count safely, freeing the memory if ref count is 0
void decrementRefCount(LogEntry* log) {
    pthread_mutex_lock(&log->mutex); // Lock the log entry to ensure safe decrement
    --log->refCount;
    if (log->refCount == 0) {
        free(log->sourceId);
        free(log->messageContent);
        pthread_mutex_destroy(&log->mutex); // Destroy the mutex before freeing memory
        free(log);
    } else {
        pthread_mutex_unlock(&log->mutex);
    }
}
```
This is just a high-level overview of how you could implement such a system in C. The actual implementation would require careful handling of potential race conditions, and the code provided above does not handle all aspects of your request. For example, there's no logging to disk or filtering logs based on log level, timestamp range, etc. which needs to be implemented as per requirement.
