['Here is a simple implementation in C using a linked list and pthreads for thread safety:

```c
#include <pthread.h>
#include <stdio.h>
#include <time.h>
#include <stdlib.h>

typedef struct packet_header {
    char *src;
    char *dest;
    int protocol;
    size_t payload_len;
    time_t timestamp;
} packet_header_t;

typedef struct node {
    packet_header_t data;
    struct node *next;
} node_t;

node_t *head = NULL;
pthread_mutex_t lock;
int age_threshold = 60; // seconds

void *insert(packet_header_t *data) {
    pthread_mutex_lock(&lock);

    node_t *current = NULL;
    if (head == NULL) {
        head = malloc(sizeof(node_t));
        head->data = *data;
        head->next = NULL;
    } else {
        current = head;
        while (current->next != NULL) {
            current = current->next;
        }

        /* Add a new packet_header node */
        current->next = malloc(sizeof(node_t));
        current->next->data = *data;
        current->next->next = NULL;
    }

    pthread_mutex_unlock(&lock);
}

void *get() {
    pthread_mutex_lock(&lock);

    node_t *current = head;
    while (current != NULL) {
        time_t current_time;
        time(&current_time);

        if ((intmax_t)difftime(current_time, current->data.timestamp) <= age_threshold) {
            printf("Source: %s, Destination: %s, Protocol: %d, Payload Length: %zu\n",
                current->data.src, current->data.dest, current->data.protocol, 
                current->data.payload_len);
        }

        current = current->next;
    }

    pthread_mutex_unlock(&lock);
}
```
This is a very simple example and doesn't include the logging or performance monitoring features you requested. It also does not clear old entries based on a configurable age threshold, nor does it handle varying network conditions gracefully. These would require significantly more complex code to implement correctly.
