['Here's a basic implementation of this class in C#. Note that implementing some features like support for internationalization, handling edge cases or caching frequently requested random values requires additional classes or libraries to be imported, which have been ommitted here due to the complexity and size of the required code. Please import appropriate namespaces for these features in your actual implementation.
```csharp
using System;
using System.Threading;

public class AdvancedRandomValueGenerator 
{
    private int minRange;
    private int maxRange;
    private Random rand = new Random();
    private ReaderWriterLockSlim lock_ = new ReaderWriterLockSlim();

    public AdvancedRandomValueGenerator(int min, int max) 
    {
        if (min > max) 
            throw new ArgumentException("Minimum value cannot be greater than maximum value.");

        this.minRange = min;
        this.maxRange = max;
    }

    public int GetRandomInt(bool inclusive = true) 
    {
        lock_.EnterReadLock();

        try 
        {
            return rand.Next(inclusive ? minRange : minRange + 1, inclusive ? maxRange + 1 : maxRange);
        } 
        finally 
        {
            lock_.ExitReadLock();
        }
    }

    public double GetRandomFloat() 
    {
        lock_.EnterReadLock();

        try 
        {
            return minRange + rand.NextDouble() * (maxRange - minRange);
        } 
        finally 
        {
            lock_.ExitReadLock();
        }
    }

    public int[] GetExclusiveRangeValues() 
    {
        lock_.EnterWriteLock();

        try 
        {
            int val1 = rand.Next(minRange, maxRange);
            int val2;

            do 
            {
                val2 = rand.Next(minRange, maxRange + 1);
            } while (val2 == val1);

            return new[] {val1, val2};
        } 
        finally 
        {
            lock_.ExitWriteLock();
        }
    }

    public int[] GetRandomWeightedValues(int count) 
    {
        lock_.EnterReadLock();

        try 
        {
            var values = new int[count];
            double step = (maxRange - minRange + 0.5) / count;

            for (var i = 0; i < count; ++i) 
            {
                values[i] = (int)(minRange + rand.NextDouble() * ((i+1)*step));
            }

            return values;
        } 
        finally 
        {
            lock_.ExitReadLock();
        }
    }

    public override string ToString() 
    {
        lock_.EnterReadLock();

        try 
        {
            return $"Range: [{minRange}, {maxRange}]";
        } 
        finally 
        {
            lock_.ExitReadLock();
        }
    }

    public long GetRandomTimestamp() 
    {
        DateTime start = new DateTime(1970, 1, 1, 0, 0, 0, DateTimeKind.Utc); // Epoch time
        int range = (maxRange - minRange) * 60; // One minute is considered here

        lock_.EnterReadLock();

        try 
        {
            return ((long)(start.AddSeconds(rand.Next(range) + minRange).Subtract(new DateTime(1970, 1, 1)).TotalSeconds)).ToString(); // Unix timestamp in seconds
        } 
        finally 
        {
            lock_.ExitReadLock();
        }
    }
}
```
Please note that the `GetRandomTimestamp()` method is a simplification and does not take leap seconds or time zone adjustments into account. To get accurate Unix timestamps considering these factors, you might need to use a different approach or consider using Noda Time library for date and time manipulations in C# which takes all those aspects into account. Also remember to implement unit tests according to the requirements described above to ensure the class's reliability under various conditions.
']

