        if (isprint(ch)) {
            total++;
        }
    }

    return total;
}

int main(int argc, char **argv) {
    int i, line_count = 0, total_characters = 0;
    FILE *file;
    char buffer[256], output_filename[FILENAME_MAX] = "";

    for (i=1; i<argc; i++){
        if (!strcmp(argv[i], "--manpage")) {
            print_manpage();
            exit(EXIT_SUCCESS);
        } else if (!strcmp(argv[i], "-cs")){
        	printf("Total characters: %d\n", total_characters);
        	exit(EXIT_SUCCESS);
    	} else if (!strcmp(argv[i], "-o")) {
