                strncpy(output_filename, argv[i], FILENAME_MAX - 1);
                output_filename[FILENAME_MAX - 1] = '\0';
            } else {
                fprintf(stderr, "Error: no filename provided for '-o' option.\n");
                exit(EXIT_FAILURE);
            }
        } else if ((file = fopen(argv[i], "r")) == NULL) {
        	fprintf(stderr, "%s: %s\n", argv[0], strerror(errno));
            continue; 
        }
    }

    if (strlen(output_filename) == 0){
		fprintf(stderr, "Error: no output file provided. Use '-o' option.\n");
	    exit(EXIT_FAILURE);
	}

    while ((file = fopen(*++argv, "r")) != NULL) {
        line_count = 0;
        do {
            if (fgets(buffer, sizeof buffer, file) == NULL) break;
            ++line_count;
            total_characters += count_chars(file);
            if (line_count % 10 == 0){
