using System;
using System.Linq;
using System.Collections.Concurrent;
using System.Threading;
using System.Globalization;

public class DynamicValueGenerator {
    private Random _random = new Random();
    private int _min, _max;

    public DynamicValueGenerator(int min, int max) {
        if (min > max) throw new ArgumentException("Minimum value cannot be greater than maximum");

        this._min = min;
        this._max = max;
    }

    public int GetRandomInt() => _random.Next(_min, _max + 1);

    public float GetRandomFloat() => (float) (_random.NextDouble() * (_max - _min) + _min);

    public Tuple<int, int> GetExclusiveRangeValues() {
        var firstValue = _random.Next(_min, _max);
        var secondValue = _random.Next(firstValue + 1, _max);

        return new Tuple<int, int>(firstValue, secondValue);
    }

    public int[] GetRandomWeightedValues(int count) {
        return Enumerable.Range(0, count).Select(_ => (int)(GetRandomFloat() * (_max - _min)) + _min).ToArray();
    }

    private ConcurrentDictionary<Tuple<int, int>, T[]> cache = new ConcurrentDictionary<Tuple<int, int>, T[]>();

    public override string ToString() => $"Min: {_min}, Max: {_max}";
}
