void print_usage() {
    printf("Usage: program [OPTION]... [FILE]\n\n"
           "-cs, --count-words          count words in each line and print\n"
           "--manpage                   display comprehensive documentation\n"
           "-o, --output=<file>         write output to specified file instead of standard output\n");
}

int main(int argc, char *argv[]) {
    FILE* fp = stdin;
    const char* output_filename = NULL;
    int print_word_count = 0;

    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "--manpage") == 0) {
            print_usage();
            return 0;
        } else if (strcmp(argv[i], "-cs") == 0) {
            print_word_count = 1;
        } else if (strncmp(argv[i], "-o", 2) == 0 || strncmp(argv[i], "--output=", 9) == 0) {
            output_filename = argv[i] + 2;
        } else if (fp == stdin && access(argv[i], F_OK) != -1 ) {
            fp = fopen(argv[i], "r");
            if (!fp) {
                perror("Error opening file");
                return 2;
            }
        } else {
            print_usage();
            return 1;
        }
    }

    FILE* output = stdout;
    if (output_filename != NULL) {
        output = fopen(output_filename, "w");
        if (!output) {
            perror("Error opening output file");
            return 3;
        }
    }

    char* line = NULL;
    size_t len = 0;
    ssize_t read;
    int line_count = 0;
    while ((read = getline(&line, &len, fp)) != -1) {
        if (print_word_count == 0) {
            line_count++;
        } else {
            char *token, *string;
            int word_count = 0;

            string = strdup(line);
            for(token = strtok(string, " \t\n"); token != NULL; token = strtok(NULL, " \t\n")) {
                word_count++;
            }

            fprintf(output, "%s: %d words\n", line, word_count);
        }
    }

    if (print_word_count == 0) {
        fprintf(output, "\nTotal lines in file: %d\n", line_count);
    }

    free(line);
    if (fp != stdin) fclose(fp);
    if (output != stdout) fclose(output);

    return 0;
}
```
