#include <dirent.h>
#include <stdio.h>
#include <string.h>
#include <sys/stat.h>
#include <time.h>

#define MAX_LOG_SIZE 10000

void renameFilesWithExtension(const char* dirPath, const char* targetExt, const char* newFileType) {
    DIR *dir;
    struct dirent *entry;
    struct stat fileInfo;

    if (!(dir = opendir(dirPath)))
        return;

    FILE *logFile = fopen("log.txt", "a");
    if (logFile == NULL) {
        printf("Failed to open log file.\n");
        return;
    }

    int count = 0;

    while ((entry = readdir(dir)) != NULL) {
        char oldPath[1024];
        snprintf(oldPath, sizeof(oldPath), "%s/%s", dirPath, entry->d_name);

        if (stat(oldPath, &fileInfo) < 0 || !S_ISREG(fileInfo.st_mode)) 
            continue;   // Skip if not a regular file

        char *dot = strrchr(entry->d_name, '.');

        if (dot && !strcmp(dot + 1, targetExt)) {
            time_t currentTime = time(NULL);
            double diffInDays = difftime(currentTime, fileInfo.st_mtime) / (60 * 60 * 24);

            if (diffInDays > 7) { // File is older than 7 days
                char newPath[1024];
                snprintf(newPath, sizeof(newPath), "%s/%d.%s", dirPath, count++, newFileType);

                if (rename(oldPath, newPath) != 0) {
                    fprintf(logFile, "Failed to rename file %s\n", oldPath);
                } else {
                    char timeString[50];
                    strftime(timeString, sizeof(timeString), "%a, %d %b %Y %H:%M:%S %z", localtime(&currentTime));

                    fprintf(logFile, "Renamed file from %s to %s at time %s\n", oldPath, newPath, timeString);
                }
            }
        }
    }

    fclose(logFile);
    closedir(dir);
}
```

