typedef struct thread_safe_array {
    MAC_TRANSACTION_RECORD* array;
    size_t used;
    size_t size;
    pthread_mutex_t lock;
} thread_safe_array;

void init_array(thread_safe_array *a, size_t initialSize) {
    a->array = (MAC_TRANSACTION_RECORD*)malloc(initialSize * sizeof(MAC_TRANSACTION_RECORD));
    if(a->array == NULL) exit(-1); // Handle memory allocation failures gracefully.
    a->used = 0;
    a->size = initialSize;
    pthread_mutex_init(&a->lock, NULL);  // Initialize mutex for concurrent access.
}

void insert_array(thread_safe_array *a, MAC_TRANSACTION_RECORD element) {
    pthread_mutex_lock(&a->lock);   // Lock the array to avoid race conditions.

    if (a->used == a->size) {
        a->size *= 2;
        a->array = (MAC_TRANSACTION_RECORD*)realloc(a->array, a->size * sizeof(MAC_TRANSACTION_RECORD));  // Reallocate memory for new elements.
        if(a->array == NULL) exit(-1); // Handle reallocation failures gracefully.
    }

    element.TIMESTAMP = time(NULL);   // Timestamp the record upon insertion.
    a->array[a->used++] = element;  // Insert the new element and increase the used size.

    pthread_mutex_unlock(&a->lock);  // Unlock the array after modification.
}
