typedef struct PacketData {
    int data;
    pthread_mutex_t mutex; // Used for atomic operations
} PacketData;

pthread_mutex_t allocationMutex = PTHREAD_MUTEX_INITIALIZER;
PacketData* packetPool[1024];  // Assume maximum of 1024 packets can be handled concurrently for now
int poolSize = 1024;

TX_PACKET_METADATA** handleDynamicMemoryForNetworkTraffic() {
    TX_PACKET_METADATA** packetMetadata = malloc(poolSize * sizeof(TX_PACKET_METADATA*));

    // Read integers from standard input and store them in allocated array
    int count = 0;
    while (count < poolSize) {
        int data;
        if (scanf("%d,", &data) != 1) break;  // Assume each integer is followed by a comma, or EOF

        pthread_mutex_lock(&allocationMutex);  // Lock mutex for atomic operation
        PacketData* newPacket = malloc(sizeof(PacketData));
        if (newPacket == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            pthread_mutex_unlock(&allocationMutex);  // Unlock mutex before returning to prevent deadlock
            return packetMetadata;
        }

        newPacket->data = data;
        pthread_mutex_init(&newPacket->mutex, NULL);
        packetPool[count] = newPacket;  // Store in packet pool for later deallocation
        packetMetadata[count] = malloc(sizeof(TX_PACKET_METADATA));  // Allocate memory for metadata
        if (packetMetadata[count] == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            pthread_mutex_unlock(&allocationMutex);  // Unlock mutex before returning to prevent deadlock
            return packetMetadata;
        }

        // Fill in the metadata fields here...
        count++;
    }

    return packetMetadata;
}

void freePacketData(TX_PACKET_METADATA** packetMetadata) {
    for (int i = 0; i < poolSize; i++) {
        pthread_mutex_lock(&allocationMutex);  // Lock mutex for atomic operation

        PacketData* packet = packetPool[i];
        free(packetMetadata[i]);  // Free metadata
        free(packet);  // Free individual packet data
        pthread_mutex_unlock(&allocationMutex);  // Unlock mutex after deallocating
    }

    free(packetMetadata);  // Finally, free the array of pointers
}
