```c
#include <stdlib.h>
#include <pthread.h>
#define MAX_PACKETS 50000

typedef struct {
    /* Add your fields here */
} TX_PACKET_METADATA;

static pthread_mutex_t allocMutex = PTHREAD_MUTEX_INITIALIZER;
static int totalAllocated = 0;
static int successfulAllocs = 0;
static double avgTimeForSuccessfulAllocs = 0.0;
static TX_PACKET_METADATA *txPacketMetadataArray[MAX_PACKETS];

// This function is called from multiple threads, we need to ensure thread safety
void* allocateMemory(size_t size) {
    pthread_mutex_lock(&allocMutex); // Lock the mutex before accessing totalAllocated

    if (totalAllocated >= MAX_PACKETS) {
        pthread_mutex_unlock(&allocMutex); 
        return NULL; // Return null if we have reached the maximum number of allocations.
    }

    TX_PACKET_METADATA *packetMetadata = malloc(sizeof(TX_PACKET_METADATA)); // Allocate memory for packet metadata

    if (packetMetadata == NULL) {
        pthread_mutex_unlock(&allocMutex); 
        return NULL; // Return null if the allocation failed.
    }

    txPacketMetadataArray[totalAllocated++] = packetMetadata; // Store the allocated memory in our array and increment totalAllocated

    pthread_mutex_unlock(&allocMutex); 
    return packetMetadata;
}

// This function is also called from multiple threads, we need to ensure thread safety
void freeMemory(TX_PACKET_METADATA *packetMetadata) {
    pthread_mutex_lock(&allocMutex); // Lock the mutex before accessing totalAllocated

    for (int i = 0; i < totalAllocated; ++i) {
        if (txPacketMetadataArray[i] == packetMetadata) { 
            free(packetMetadata); // Free the allocated memory.

            txPacketMetadataArray[i] = NULL; // Remove the freed memory from our array.

            --totalAllocated; // Decrement totalAllocated.
            break;
        }
    }

    pthread_mutex_unlock(&allocMutex); 
}
```
