typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[EVP_MAX_KEY_LENGTH];
    unsigned char iv[EVP_MAX_IV_LENGTH];
} aes256cbc_context;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

aes256cbc_context *initializeAES256CBC(const char *password) {
    if (password == NULL) {
        fprintf(stderr, "Password cannot be null\n");
        return NULL;
    }

    aes256cbc_context *ctx = malloc(sizeof(aes256cbc_context));
    if (ctx == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    pthread_mutex_lock(&lock);
    ctx->ctx = EVP_CIPHER_CTX_new();
    if (ctx->ctx == NULL) {
        fprintf(stderr, "EVP_CIPHER_CTX initialization failed\n");
        free(ctx);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    // Derive encryption key and IV from the password (for simplicity we use SHA-256 as KDF)
    if (!PKCS5_PBKDF2_HMAC(password, strlen(password), NULL, 0, EVP_sha256(), 1, EVP_MAX_KEY_LENGTH + EVP_MAX_IV_LENGTH, ctx->key)) {
        fprintf(stderr, "Key derivation failed\n");
        free(ctx);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    memcpy(ctx->iv, ctx->key + EVP_MAX_KEY_LENGTH, EVP_MAX_IV_LENGTH);
    if (!EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_cbc(), NULL, ctx->key, ctx->iv)) {
        fprintf(stderr, "Cipher initialization failed\n");
        free(ctx);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    EVP_CIPHER_CTX_set_padding(ctx->ctx, 1); // Enable PKCS#7 padding for block ciphers
    pthread_mutex_unlock(&lock);
    return ctx;
}

void cleanupAES256CBC(aes256cbc_context *ctx) {
    if (ctx == NULL) {
        fprintf(stderr, "Context cannot be null\n");
        return;
    }

    pthread_mutex_lock(&lock);
    EVP_CIPHER_CTX_free(ctx->ctx);
    free(ctx);
    pthread_mutex_unlock(&lock);
}
```
This code initializes an AES-256-CBC cipher by deriving an encryption key and IV from the given password using SHA-256. For simplicity, it uses PKCS#5 PBKDF2 HMAC with 1 iteration for key derivation. This is not strictly secure but sufficient for simple use cases.

It performs error checking for OpenSSL operations and ensures thread safety by locking a mutex before allocating memory or initializing the cipher context. The cleanup function frees all resources associated with the cipher context and disables it when it's no longer needed. It also handles edge cases such as null passwords, invalid cipher settings, and memory allocation failures gracefully.
