        fprintf(stderr, "Invalid parameters.\n");
        return;
    }

    pthread_mutex_lock(&lock);
    int len;
    if (!EVP_EncryptUpdate(data->ctx, ciphertext, &len, plaintext, plaintext_len)) {
        fprintf(stderr, "Failed to encrypt data.\n");
        pthread_mutex_unlock(&lock);
        return;
    }
    if (!EVP_EncryptFinal_ex(data->ctx, ciphertext + len, &len)) {
        fprintf(stderr, "Failed to finalize encryption process.\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    pthread_mutex_unlock(&lock);
}

void decryptData(aes_256_cbc *data, unsigned char *ciphertext, int ciphertext_len, unsigned char *plaintext) {
    if (data == NULL || ciphertext == NULL || plaintext == NULL){
        fprintf(stderr, "Invalid parameters.\n");
        return;
    }

    pthread_mutex_lock(&lock);
    int len;
    if (!EVP_DecryptUpdate(data->ctx, plaintext, &len, ciphertext, ciphertext_len)) {
        fprintf(stderr, "Failed to decrypt data.\n");
        pthread_mutex_unlock(&lock);
        return;
    }
    if (!EVP_DecryptFinal_ex(data->ctx, plaintext + len, &len)) {
        fprintf(stderr, "Failed to finalize decryption process.\n");
        pthread_mutex_unlock(&lock);
        return;
    }

    pthread_mutex_unlock(&lock);
}

void cleanup(aes_256_cbc *data) {
    if (data == NULL){
        fprintf(stderr, "Invalid parameter.\n");
        return;
    }

