#include <stdatomic.h>

typedef struct LTE_Ngap_UeContext_s {
    int rnti;
    void *ueInfo;
} LTE_Ngap_UeContext_t;

struct contextManager {
    atomic_int count;
    pthread_mutex_t lock;
    LTE_Ngap_UeContext_t **contexts;
};

void initContextManager(struct contextManager *manager) {
    manager->count = 0;
    pthread_mutex_init(&(manager->lock), NULL);
    manager->contexts = NULL;
}

int addContext(struct contextManager *manager, LTE_Ngap_UeContext_t *newContext) {
    int i;

    pthread_mutex_lock(&(manager->lock));

    // Check for duplicate RNTI
    for (i = 0; i < manager->count; ++i) {
        if (manager->contexts[i]->rnti == newContext->rnti) {
            pthread_mutex_unlock(&(manager->lock));
            return -1;  // Duplicate RNTI, return error code
        }
    }

    // Resize the array and add the new context
    manager->contexts = realloc(manager->contexts, sizeof(LTE_Ngap_UeContext_t *) * (manager->count + 1));
    manager->contexts[manager->count] = newContext;
    ++manager->count;

    pthread_mutex_unlock(&(manager->lock));

    return 0;  // Success
}

int removeContextByRnti(struct contextManager *manager, int rnti) {
    int i;

    pthread_mutex_lock(&(manager->lock));

    for (i = 0; i < manager->count; ++i) {
        if (manager->contexts[i]->rnti == rnti) {
            // Shift all elements after the found one to fill the gap
            --(manager->count);
            for (; i < manager->count; ++i) {
                manager->contexts[i] = manager->contexts[i + 1];
            }

            // Resize the array to remove the duplicate element
            manager->contexts = realloc(manager->contexts, sizeof(LTE_Ngap_UeContext_t *) * (manager->count));

            pthread_mutex_unlock(&(manager->lock));
            return 0;  // Success
        }
    }

    pthread_mutex_unlock(&(manager->lock));

    return -1;  // RNTI not found, return error code
}

int updateContextByRnti(struct contextManager *manager, int rnti, LTE_Ngap_UeContext_t *updatedContext) {
    int i;

    pthread_mutex_lock(&(manager->lock));

    for (i = 0; i < manager->count; ++i) {
        if (manager->contexts[i]->rnti == rnti) {
            // Update the context with new information
            free(manager->contexts[i]);
            manager->contexts[i] = updatedContext;

            pthread_mutex_unlock(&(manager->lock));
            return 0;  // Success
        }
    }

    pthread_mutex_unlock(&(manager->lock));

    return -1;  // RNTI not found, return error code
}
