} TaskDescriptor;

typedef struct MemoryPool {
    size_t size;
    void *pool;
    atomic_flag lock = ATOMIC_FLAG_INIT;
} MemoryPool;

MemoryPool pool;
pthread_mutex_t mtx;
TaskDescriptor *descriptors;
int numTasks = 0;

void allocateMemory(size_t size) {
    while (atomic_flag_test_and_set(&pool.lock));

    if ((pool.pool = realloc(pool.pool, pool.size + size)) == NULL) {
        atomic_flag_clear(&pool.lock);
        return;
    }

    pool.size += size;
    atomic_flag_clear(&pool.lock);
}

void populateDescriptor(TaskDescriptor *descriptor, int id, int priority, time_t deadline) {
    descriptor->id = id;
    descriptor->priority = priority;
    descriptor->deadline = deadline;

    pthread_mutex_lock(&mtx);
    descriptors[numTasks++] = *descriptor;
    pthread_mutex_unlock(&mtx);
}

