import json
from time import time
import logging
import sys
from concurrent.futures import ThreadPoolExecutor
from collections import defaultdict

class USER_SESSION_T:
    def __init__(self):
        self._sessions = defaultdict(int)
        self._executor = ThreadPoolExecutor(max_workers=10000)
        self.logger = logging.getLogger(__name__)

    @staticmethod
    def _deserialize(data, class_):
        try:
            obj = json.loads(data)
            if isinstance(obj, dict):
                return {k: class_(**v) for k, v in obj.items()}
            else:
                raise ValueError('Expected a dictionary')
        except Exception as e:
            print("Failed to deserialize data:", str(e))
            raise RuntimeError('Deserialization failed')

    def update_session(self, session):
        try:
            deserialized = self._deserialize(session, USER_SESSION)
            for sess in deserialized.values():
                if not isinstance(sess, USER_SESSION):
                    raise TypeError('Expected an instance of class USER_SESSION')

                session_id = sess.SESSION_ID
                self._executor.submit(self._update_session_task, session_id, sess)
        except Exception as e:
            logging.error("Error in update_session method", exc_info=True)

    def _update_session_task(self, session_id, session):
        if session_id not in self._sessions or \
           time() - self._sessions[session_id].LAST_ACTIVITY_TIME > 1800:  # If the session is new or inactive for more than 30 mins
            logging.info(f'New session with id {session_id} started at {session.LOGIN_TIME}')

        self._sessions[session_id] = session
        self._sessions[session_id].LAST_ACTIVITY_TIME = time()  # Update LAST_ACTIVITY_TIME
        logging.info(f'Session with id {session_id} updated')
