    manager->contexts = realloc(manager->contexts, (manager->size + 1) * sizeof(LTE_Ngap_UeContext_t));
    manager->contexts[manager->size] = newContext;
    ++manager->size;

    pthread_mutex_unlock(&manager->lock);
}

// Remove context function
void removeContext(UeContextManager* manager, int RNTI) {
    pthread_mutex_lock(&manager->lock);

    // Find the index of the context to be removed
    int i;
    for (i = 0; i < manager->size; ++i) {
        if (manager->contexts[i].RNTI == RNTI) break;
    }

    // If found, remove it by shifting the following contexts forward and reallocating memory
    if (i != manager->size) {
        --manager->size;
        for (; i < manager->size; ++i) {
            manager->contexts[i] = manager->contexts[i + 1];
        }
        manager->contexts = realloc(manager->contexts, manager->size * sizeof(LTE_Ngap_UeContext_t));
    } else {
        printf("RNTI not found, skipping...\n");
    }

    pthread_mutex_unlock(&manager->lock);
}
```

