void populateArray(MAC_FRAME_RECEIPT_T **array, int numFrames) {
    pthread_mutex_lock(&mutex);  // Lock the mutex to prevent race conditions

    *array = (MAC_FRAME_RECEIPT_T *) malloc(numFrames * sizeof(MAC_FRAME_RECEIPT_T));

    if (*array == NULL) {
