```csharp
using System;
using System.Security.Cryptography;
using System.Text;

public string DecryptWithAes(string ciphertext, string key, string iv, PaddingMode padding) {
    if (key == null || key.Length != 32 || iv == null || iv.Length != 16) return null; // Validate Key and IV length requirements

    try {
        using (Aes aes = Aes.Create()) {
            aes.KeySize = 256;
            aes.BlockSize = 128;
            aes.Padding = padding;
            aes.Mode = CipherMode.CBC;
            aes.IV = Encoding.UTF8.GetBytes(iv); // Set the initialization vector (IV)
            aes.Key = Encoding.UTF8.GetBytes(key); // Set the encryption key

            ICryptoTransform decryptor = aes.CreateDecryptor();
            byte[] cipherBytes = Convert.FromBase64String(ciphertext); // Assuming ciphertext is base64 encoded string

            byte[] plainBytes = decryptor.TransformFinalBlock(cipherBytes, 0, cipherBytes.Length);
            return Encoding.UTF8.GetString(plainBytes);
        }
    } catch (Exception e) {
        // Handle exception gracefully, log error message for instance.
        Console.WriteLine("An error occurred while decrypting the ciphertext: " + e);
        return null;
    }
}
```
