using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;

public class DataProcessor<T> where T : IComparable
{
    private List<T> dataEntries;
    private Func<T, bool> filterCriteria;
    private ReaderWriterLockSlim lock_ = new ReaderWriterLockSlim();

    public DataProcessor(List<T> dataEntries, Func<T, bool> filterCriteria)
    {
        this.dataEntries = dataEntries;
        this.filterCriteria = filterCriteria;
    }

    public void ApplyFilter()
    {
        lock_.EnterWriteLock();
        try
        {
            dataEntries = dataEntries.Where(filterCriteria).ToList();
        }
        finally
        {
            lock_.ExitWriteLock();
        }
    }

    public void ProcessData(Action<T> processingAlgorithm)
    {
        lock_.EnterReadLock();
        try
        {
            foreach (var entry in dataEntries)
            {
                processingAlgorithm(entry);
            }
        }
        finally
        {
            lock_.ExitReadLock();
        }
    }

    public void AdditionalDataProcessing(string algorithmName, object parameters)
    {
        // You would need to implement a dictionary of predefined algorithms here
    }

    public Dictionary<string, object> GetFilteredDataSummary()
    {
        lock_.EnterReadLock();
        try
        {
            return new Dictionary<string, object>
            {
                {"Count", dataEntries.Count},
                {"Average", dataEntries.Any() ? dataEntries.Average(x => Convert.ToDouble(x)) : 0},
                {"TotalSum", dataEntries.Sum(x => Convert.ToDouble(x))}
            };
        }
        finally
        {
            lock_.ExitReadLock();
        }
    }

    public void UpdateFilters(Func<T, bool> newCriteria)
    {
        filterCriteria = newCriteria;
    }

    public override string ToString()
    {
        return $"Filter Criteria: {filterCriteria}\nData Summary: {GetFilteredDataSummary().Count}, {GetFilteredDataSummary()["Average"]}, {GetFilteredDataSummary()["TotalSum"]}";
    }
}
