['Here is an example of a code snippet that can solve some parts of your problem. This solution uses Java NIO2 for file operations, Guava Cache for caching mechanism, Log4j2 for logging and Jackson CSV mapper to generate CSV output:

```java
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.dataformat.csv.CsvMapper;
import com.fasterxml.jackson.dataformat.csv.CsvSchema;
import com.google.common.cache.CacheBuilder;
import com.google.common.cache.CacheLoader;
import com.google.common.cache.LoadingCache;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;

import java.io.*;
import java.nio.file.*;
import java.nio.file.attribute.BasicFileAttributes;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.TimeUnit;

public class DirectoryScanner {
    private static final Logger logger = LogManager.getLogger(DirectoryScanner.class);

    // Define the cache to store directory scan results and configurations
    LoadingCache<Path, List<File>> fileCache = CacheBuilder.newBuilder()
            .maximumSize(10_000)  // Set a reasonable maximum size for your environment
            .expireAfterWrite(10, TimeUnit.MINUTES)
            .build(new CacheLoader<Path, List<File>>() {
                public List<File> load(Path key) throws Exception {
                    return scanDirectoryForFiles(key);
                }
            });

    private ObjectMapper mapper = new CsvMapper();
    private CsvSchema schema = mapper.schemaFor(File.class).withHeader().sortedBy("name", "size", "lastModified");

    public void scanDirectory(String directoryPath) {
        Path path = Paths.get(directoryPath);
        try {
            List<File> files = fileCache.get(path);  // Get or scan the directory
            mapper.writer().with(schema).writeValue(new FileOutputStream("output.csv"), files);  // Write to CSV
        } catch (ExecutionException e) {
            logger.error("Error scanning directory", e);
        } catch (IOException e) {
            logger.error("Error writing output file", e);
        }
    }

    private List<File> scanDirectoryForFiles(Path path) throws IOException {
        List<File> files = new ArrayList<>();
        Files.walkFileTree(path, new SimpleFileVisitor<Path>() {
            @Override
            public FileVisitResult visitFile(Path file, BasicFileAttributes attrs) {
                if (Files.isRegularFile(file)) {  // Exclude directories and other types of files
                    files.add(new File(file.toString(), attrs));
                }
                return FileVisitResult.CONTINUE;
            }
        });
        return files;
    }

    public static void main(String[] args) {
        new DirectoryScanner().scanDirectory("/path/to/directory");
    }
}
```

