// Structure to represent a file change event
typedef struct {
    char* path;
    time_t modificationTime;
    int type;  // Creation:1, Deletion:2, Modification:3
} Event;

// Queue structure for events
typedef struct Node{
    Event *event;
    struct Node *next;
} Node;

Node* front = NULL;
Node* rear = NULL;
int maxQueueSize = 10000;  // Default maximum queue size

void push(Event *event){
    if((rear+1)%maxQueueSize == front){
        printf("Queue is full\n");
        return;
    }else{
        Node* newNode = (Node*)malloc(sizeof(Node));
        newNode->event = event;
        newNode->next = NULL;
        if(rear == NULL){
            front = rear = newNode;
        }else{
            rear->next = newNode;
            rear = newNode;
        }
    }
}

Event* pop(){
    Event *event;
    Node* temp;
    if(front == NULL){
        printf("Queue is empty\n");
        return NULL;
    }else{
        event = front->event;
        temp = front;
        front = front->next;
        if(front==NULL) rear=NULL;
        free(temp);
    }
    return event;
}

