ArrayInfo* createAndPopulateArray(size_t sizeLimit) {
    if (sizeLimit == 0) {
        logError("Invalid input: maximum size limit cannot be 0.");
        return NULL;
    }

    ArrayInfo* info = malloc(sizeof(*info));
    if (!info) {
        logError("Failed to allocate memory for array information.");
        return NULL;
    }

    info->maxSize = sizeLimit;
    info->currSize = 0;
    pthread_mutex_init(&(info->mutex), NULL);

    info->array = malloc(sizeof(LTE_DL_FRAMEINFO) * sizeLimit);
    if (!info->array) {
        logError("Failed to allocate memory for array.");
        pthread_mutex_destroy(&(info->mutex));
        free(info);
        return NULL;
    }

    // populate array with valid SRS, cell identities, and CQIs. This is just a placeholder.
