        info->array[i].cell_id = /* populate */;
        info->array[i].CQI = /* populate */;
        ++(info->currSize);
    }

    return info;
}

void destroyArray(ArrayInfo* arrayInfo) {
    if (!arrayInfo) {
        logError("Invalid input: array information is NULL.");
        return;
    }

    pthread_mutex_lock(&(arrayInfo->mutex));  // Lock before modifying and accessing data.

    free(arrayInfo->array);
    arrayInfo->array = NULL;
    arrayInfo->currSize = 0;
    arrayInfo->maxSize = 0;

    pthread_mutex_unlock(&(arrayInfo->mutex));  // Unlock after done.
    pthread_mutex_destroy(&(arrayInfo->mutex));

    free(arrayInfo);
}
