['Here is a basic implementation using POSIX threads (pthreads) for synchronization and error handling. Please note that this is just a simple example and might need adjustments based on your actual data structures or requirements.

```c
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <pthread.h>

typedef struct {
    /* Define Uplink Control Channel (PUCCH) resource configurations */
} NR_DL_FRAMEINFO;

typedef struct {
    pthread_mutex_t mutex;
    size_t capacity;
    size_t count;
    NR_DL_FRAMEINFO *array;
} DynamicArray;

DynamicArray* initialize() {
    DynamicArray *da = malloc(sizeof(*da));
    if (da == NULL) {
        fprintf(stderr, "Memory allocation failed: %s\n", strerror(errno));
        return NULL;
    }

    da->capacity = 10; // Initial capacity
    da->count = 0;
    da->array = malloc(sizeof(*da->array) * da->capacity);
    if (da->array == NULL) {
        fprintf(stderr, "Memory allocation failed: %s\n", strerror(errno));
        free(da);
        return NULL;
    }

    pthread_mutex_init(&da->mutex, NULL);

    return da;
}

void append(DynamicArray *da, NR_DL_FRAMEINFO element) {
    if (pthread_mutex_lock(&da->mutex) != 0) {
        fprintf(stderr, "Mutex lock failed: %s\n", strerror(errno));
        return;
    }

    if (da->count == da->capacity) {
        // Double the capacity when full
        size_t newCapacity = da->capacity * 2;
        NR_DL_FRAMEINFO* newArray = realloc(da->array, sizeof(*newArray) * newCapacity);
        if (newArray == NULL) {
            fprintf(stderr, "Memory allocation failed: %s\n", strerror(errno));
            pthread_mutex_unlock(&da->mutex);
            return;
        }

        da->array = newArray;
        da->capacity = newCapacity;
    }

    // Copy the element into the array
    memcpy(&da->array[da->count], &element, sizeof(element));
    da->count++;

    if (pthread_mutex_unlock(&da->mutex) != 0) {
        fprintf(stderr, "Mutex unlock failed: %s\n", strerror(errno));
    }
}

void destroy(DynamicArray *da) {
    pthread_mutex_destroy(&da->mutex);
    free(da->array);
    free(da);
}
```
This implementation uses a single mutex to protect the append operation. You might want to use more granular synchronization depending on your requirements, for example using separate reader and writer locks if reads outnumber writes significantly. 

