    array->length = 0;
    array->capacity = 10;  // Initial capacity. Adjust as needed.
    array->data = malloc(sizeof(UserSessionInfo_t) * array->capacity);
}

int AddSession(SessionArray_t* array, const UserSessionInfo_t* session) {
    pthread_mutex_lock(&array->mutex);  // Acquire lock.

    for (size_t i = 0; i < array->length; ++i) {
        if (strcmp(session->sessionId, array->data[i].sessionId) == 0) {
            pthread_mutex_unlock(&array->mutex);  // Release lock.
            return -1;  // Duplicate session ID detected.
        }
    }

    if (array->length >= array->capacity) {
        array->capacity *= 2;  // Double the capacity when full.
        array->data = realloc(array->data, sizeof(UserSessionInfo_t) * array->capacity);
    }

    array->data[array->length++] = *session;

    pthread_mutex_unlock(&array->mutex);  // Release lock.
    return 0;  // Successfully added session.
}

