    int found = 0;

    pthread_mutex_lock(&array->mutex);  // Acquire lock.

    for (size_t i = 0; i < array->length; ++i) {
        if (strcmp(id, array->data[i].sessionId) == 0) {
            found = 1;

            // Shift all elements after the removed one to cover up the gap.
            for (size_t j = i + 1; j < array->length; ++j) {
                array->data[j - 1] = array->data[j];
            }

            --array->length;
            break;
        }
    }

    pthread_mutex_unlock(&array->mutex);  // Release lock.
    return found ? 0 : -1;  // Successfully removed session or non-existent session.
}

