#include <errno.h>

typedef struct MediaStreamingInfo {
    int streamID;
    char* mediaSettings;
} MediaStreamingInfo_t;

typedef struct DynamicArray {
    MediaStreamingInfo_t** streams;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray_t;

DynamicArray_t* createDynamicArray() {
    DynamicArray_t* array = malloc(sizeof(DynamicArray_t));
    if (array == NULL) {
        exit(EXIT_FAILURE);
    }
    array->streams = calloc(10, sizeof(MediaStreamingInfo_t*));
    array->capacity = 10;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void addStream(DynamicArray_t* array, MediaStreamingInfo_t* stream) {
    if (stream == NULL) {
        return;
    }
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->size; ++i) {
        if (array->streams[i]->streamID == stream->streamID) {
            // Handle duplicate ID error.
            pthread_mutex_unlock(&array->lock);
            return;
        }
    }
    if (array->size >= array->capacity) {
        array->streams = realloc(array->streams, 2 * array->capacity * sizeof(MediaStreamingInfo_t*));
        if (array->streams == NULL) {
            exit(EXIT_FAILURE);
        }
        array->capacity *= 2;
    }
    array->streams[array->size++] = stream;
    pthread_mutex_unlock(&array->lock);
}

void removeStreamByID(DynamicArray_t* array, int id) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->size; ++i) {
        if (array->streams[i]->streamID == id) {
            free(array->streams[i]);
            array->streams[i] = array->streams[--array->size];
            pthread_mutex_unlock(&array->lock);
            return;
        }
    }
    // Handle non-existent ID error.
    pthread_mutex_unlock(&array->lock);
}

void updateStream(DynamicArray_t* array, int id, MediaStreamingInfo_t* newStream) {
    if (newStream == NULL || id != newStream->streamID) {
        return;
    }
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->size; ++i) {
        if (array->streams[i]->streamID == id) {
            free(array->streams[i]);
            array->streams[i] = newStream;
            pthread_mutex_unlock(&array->lock);
            return;
        }
    }
    // Handle non-existent ID error.
    pthread_mutex_unlock(&array->lock);
}
