#include <stdlib.h>
#include <string.h>

typedef struct Node {
    void* data;
    size_t size;
    struct Node* next;
} Node;

Node* createList(void* data, size_t size) {
    Node* head = malloc(sizeof(Node));
    if (head == NULL) return NULL; // handle memory allocation failure

    head->data = malloc(size);
    if (head->data == NULL) { 
        free(head);
        return NULL; // handle memory allocation failure
    }

    memcpy(head->data, data, size);
    head->size = size;
    head->next = NULL;

    return head;
}

Node* addToList(Node* list, void* data, size_t size) {
    Node* newNode = malloc(sizeof(Node));
    if (newNode == NULL) return list; // handle memory allocation failure

    newNode->data = malloc(size);
    if (newNode->data == NULL) { 
        free(newNode);
        return list; // handle memory allocation failure
    }

    memcpy(newNode->data, data, size);
    newNode->size = size;
    newNode->next = NULL;

    Node* lastNode = list;
    while (lastNode != NULL && lastNode->next != NULL) {
        lastNode = lastNode->next;
    }

    if (lastNode == NULL) return newNode;

    lastNode->next = newNode;
    return list;
}
