typedef struct MemoryPool {
    void *start;
    size_t size;
    size_t allocatedCount;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool createMemoryPool(size_t initialSize, size_t objectSize) {
    // Initialize memory pool with initial size and object size.
}

void *allocateFromMemoryPool(MemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);

    if (pool->allocatedCount < pool->size / pool->objectSize) {
        void *ptr = pool->start + pool->allocatedCount * pool->objectSize;
        ++(pool->allocatedCount);
        pthread_mutex_unlock(&pool->lock);
        return ptr;
    } else if (realloc(pool->start, 2 * pool->size) != NULL) {
        // Reallocation successful. Update the size and continue allocation.
        pool->size = 2 * pool->size;
        ++(pool->allocatedCount);
        pthread_mutex_unlock(&pool->lock);
        return allocateFromMemoryPool(pool);
    } else {
        // Reallocation failed. Return NULL to indicate out of memory.
        pthread_mutex_unlock(&pool->lock);
        return NULL;
    }
}

void freeFromMemoryPool(MemoryPool *pool, void *ptr) {
