omp_lock_t *locks;
LTE_Ngap_UeContext_t **hashTable;
int size;

void init() {
    size = 1024;  // initial size of the hash table
    locks = malloc(sizeof(omp_lock_t) * size);
    for (int i = 0; i < size; i++) omp_init_lock(&locks[i]);

    hashTable = malloc(sizeof(LTE_Ngap_UeContext_t*) * size);
    // initialize the hash table with NULL pointers.
}

int hashFunc(int RNTI) {
    return RNTI % size;  // simple hashing function, can be replaced with better functions for optimization
}

void addContext(LTE_Ngap_UeContext_t *context) {
    int index = hashFunc(context->RNTI);
    omp_set_lock(&locks[index]);  // lock the specific bucket.

    if (hashTable[index] != NULL) {
        // handle duplicate RNTI or other edge cases
    } else {
        hashTable[index] = context;
    }

    omp_unset_lock(&locks[index]);  // unlock the bucket.
}

void removeContext(int RNTI) {
    int index = hashFunc(RNTI);
    omp_set_lock(&locks[index]);

    if (hashTable[index] != NULL && hashTable[index]->RNTI == RNTI) {
        free(hashTable[index]);  // need to free the memory allocated for this context
        hashTable[index] = NULL;
    } else {
        // handle non-existent RNTI or other edge cases
    }

    omp_unset_lock(&locks[index]);
}

void updateContext(int RNTI, LTE_Ngap_UeContext_t *newContext) {
    removeContext(RNTI);
    addContext(newContext);
}
