static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void handleErrors(char *errorMessage) {
    fprintf(stderr, "%s", errorMessage);
}

DES_cblock desKey[3]; // Key for triple DES. First byte is the parity of the key. 
int mode = DES_ENCRYPT; // Encryption or Decryption

void flexcrypt(unsigned char *in, unsigned char *out, int size, int operation) {
    if (operation == 0 || operation == 3) { // Null encryption
        memcpy(out, in, size);
        return;
    } 

    pthread_mutex_lock(&lock); // Lock the critical section to ensure thread safety.

    switch (mode) {
      case DES_ENCRYPT:
          mode = DES_DECRYPT;
          break;
      case DES_DECRYPT:
          mode = DES_ENCRYPT;
          break;
      default:
          handleErrors("Invalid operation\n");
          return;
    }

    DES_key_schedule schedule[3]; // Schedule for triple DES.

    int i = 0; 
    for (; i < 3; ++i) {
        if (!DES_set_key_checked(&desKey[i], &schedule[i])) {
            handleErrors("Weak key error\n");
            return;
        }
    }

    DES_ede3_cbc_encrypt(in, out, size, &schedule[0], &desKey[2], &mode, &DES_quad_permute); 

    pthread_mutex_unlock(&lock); // Unlock the critical section.
}
```
