// Custom memory pool can be implemented using a linked list. Each node in the list represents a memory chunk. 
typedef struct MemoryChunk{
    void* memory;
    int isAllocated;
    struct MemoryChunk* next;
} MemoryChunk;

MemoryChunk* head = NULL; // Start of memory pool
pthread_mutex_t mutexPool = PTHREAD_MUTEX_INITIALIZER;

void* allocate(size_t size){
    pthread_mutex_lock(&mutexPool); 

    MemoryChunk* chunk = head;
    while(chunk != NULL && (chunk->isAllocated || chunk->memory < size)) {
        chunk = chunk->next;
    }

    if (chunk == NULL){ // No available memory chunks, create new one.
        void* mem = malloc(size); 

        MemoryChunk* newNode = (MemoryChunk*)malloc(sizeof(MemoryChunk));
        newNode->memory = mem;
        newNode->isAllocated = 1;
        newNode->next = head;
        head = newNode; 

        pthread_mutex_unlock(&mutexPool);
        return mem;
    } else { // Mark the found chunk as allocated.
        chunk->isAllocated = 1;
        pthread_mutex_unlock(&mutexPool);
        return chunk->memory;
    }
}
```

