['Here's a basic implementation of `NetworkInterfaceManager` in C. However, please note that this is just an example and may need modifications for specific usage scenarios based on your requirements.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

typedef struct InterfaceDescriptor {
    char* name;
    char* ipAddr;
    char* subnetMask;
    char* gateway;
} InterfaceDescriptor;

InterfaceDescriptor** interfaceList = NULL;
int interfaceCount = 0;
pthread_mutex_t lock;
clock_t start, end;
double cpu_time_used;

void addInterface(char* name, char* ipAddr, char* subnetMask, char* gateway) {
    pthread_mutex_lock(&lock);
    ++interfaceCount;
    interfaceList = realloc(interfaceList, interfaceCount * sizeof(InterfaceDescriptor*));
    InterfaceDescriptor* desc = malloc(sizeof(InterfaceDescriptor));
    desc->name = name;
    desc->ipAddr = ipAddr;
    desc->subnetMask = subnetMask;
    desc->gateway = gateway;
    interfaceList[interfaceCount - 1] = desc;
    pthread_mutex_unlock(&lock);
}

void removeInterface(char* name) {
    pthread_mutex_lock(&lock);
    int indexToRemove = -1;
    for (int i = 0; i < interfaceCount; ++i) {
        if (strcmp(interfaceList[i]->name, name) == 0) {
            indexToRemove = i;
            break;
        }
    }

    if (indexToRemove != -1) {
        free(interfaceList[indexToRemove]);

        for (int j = indexToRemove; j < interfaceCount - 1; ++j) {
            interfaceList[j] = interfaceList[j + 1];
        }

        --interfaceCount;
    }

    pthread_mutex_unlock(&lock);
}

void testConnectivity(char* name) {
    int sockfd, connfd;
    struct sockaddr_in servaddr, cli;

    sockfd = socket(AF_INET, SOCK_STREAM, 0);

    if (sockfd == -1) {
        printf("Socket creation failed...\n");
        return;
    } else
        printf("Socket successfully created..\n");

    bzero(&servaddr, sizeof(servaddr));

    servaddr.sin_family = AF_INET;
    servaddr.sin_addr.s_addr = inet_addr("127.0.0.1");
    servaddr.sin_port = htons(5603);

    if (connect(sockfd, (struct sockaddr *)&servaddr, sizeof(servaddr)) != 0) {
        printf("Connection with the server failed...\n");
        return;
    } else
        printf("Connected to the server..\n");

    pthread_mutex_lock(&lock);
    start = clock();

    for (int i = 0; i < interfaceCount; ++i) {
        if (strcmp(interfaceList[i]->name, name) == 0) {
            printf("Interface '%s' is up.\n", name);
            break;
        }
    }

    end = clock();
    cpu_time_used = ((double) (end - start)) / CLOCKS_PER_SEC;

    printf("Test connectivity took %f seconds to execute \n", cpu_time_used);

    pthread_mutex_unlock(&lock);
}

void readConfigFile(char* filename) {
    // Implement reading config file logic here.
}

int main() {
    if (pthread_mutex_init(&lock, NULL) != 0) {
        printf("\n Mutex init has failed\n");
        return 1;
    }

    addInterface("eth0", "192.168.1.10", "255.255.255.0", "192.168.1.1");
    testConnectivity("eth0");

    pthread_mutex_destroy(&lock);

    return 0;
}
```
