    pthread_mutex_t lock;
    pthread_cond_t cond;
} SessionManager;

void initSessionManager(SessionManager* manager) {
    manager->sessions = NULL;
    manager->count = 0;
    manager->capacity = 0;
    pthread_mutex_init(&manager->lock, NULL);
    pthread_cond_init(&manager->cond, NULL);
}

void addSession(SessionManager* manager, UserSessionInfo* info) {
    pthread_mutex_lock(&manager->lock);

    // check for existing session ID
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->sessions[i]->sessionID == info->sessionID) {
            pthread_mutex_unlock(&manager->lock);
            return;
