    // resize array if necessary
    if (manager->count >= manager->capacity) {
        size_t newCapacity = manager->capacity == 0 ? 1 : manager->capacity * 2;
        UserSessionInfo** newSessions = realloc(manager->sessions, newCapacity * sizeof(*newSessions));

        if (newSessions == NULL) {
            pthread_mutex_unlock(&manager->lock);
