SessionArray *create_session_array() {
    SessionArray *arr = mmap(NULL, sizeof(*arr), PROT_READ | PROT_WRITE, MAP_SHARED | MAP_ANONYMOUS, -1, 0);
    assert(arr != MAP_FAILED);

    pthread_mutexattr_t attr;
    assert(pthread_mutexattr_init(&attr) == 0);
    assert(pthread_mutexattr_setpshared(&attr, PTHREAD_PROCESS_SHARED) == 0); // Allows lock to be shared between processes.

    assert(pthread_mutex_init(&arr->lock, &attr) == 0);
    atomic_store(&arr->size, 0);

    return arr;
}

void add_session(_Atomic(SessionArray*) array, UserSessionInfo session) {
    SessionArray *arr = atomic_load(array);
    pthread_mutex_lock(&arr->lock); // Lock to ensure thread safety

    int size = atomic_fetch_add(&arr->size, 1); // Increase the array size before writing.
    arr->sessions[size] = session; // Add new session

    pthread_mutex_unlock(&arr->lock); // Unlock after we're done
}

// Remove a session by its ID
void remove_session(_Atomic(SessionArray*) array, int id) {
    SessionArray *arr = atomic_load(array);
    pthread_mutex_lock(&arr->lock); // Lock to ensure thread safety

    for (int i = 0; i < arr->size; i++) {
        if (arr->sessions[i].sessionID == id) {
            memmove(&arr->sessions[i], &arr->sessions[i + 1], sizeof(*arr->sessions) * (arr->size - i)); // Shift array elements down
            atomic_fetch_sub(&arr->size, 1); // Decrease size after deleting an entry.
            break;
        }
    }

    pthread_mutex_unlock(&arr->lock); // Unlock after we're done
}

// Asynchronous update
void async_update(_Atomic(SessionArray*) array, UpdateItem item) {
    pthread_t thread;
    assert(pthread_create(&thread, NULL, (void *(*)(void*))&do_async_update, &item) == 0); // Start a new thread to perform the update.
}

// This function is called by async_update in a separate thread.
void do_async_update(UpdateItem *item) {
    SessionArray *arr = atomic_load(&sessionArray);
    pthread_mutex_lock(&arr->lock); // Lock to ensure thread safety

