#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <netdb.h> 

#define MAX_BUFFER 1024

void sendMessage(int sockfd, struct addrinfo *servinfo) {
    char buffer[MAX_BUFFER];

    printf("Enter message: ");
    fgets(buffer, sizeof(buffer), stdin);

    if (sendto(sockfd, buffer, strlen(buffer), 0, servinfo->ai_addr, servinfo->ai_addrlen) == -1) {
        perror("sendto");
        exit(EXIT_FAILURE);
    }
}

void receiveMessage(int sockfd, struct addrinfo *servinfo) {
    char buffer[MAX_BUFFER];

    if (recvfrom(sockfd, buffer, sizeof(buffer), 0, servinfo->ai_addr, &servinfo->ai_addrlen) == -1) {
        perror("recvfrom");
        exit(EXIT_FAILURE);
    }

    printf("Received: %s\n", buffer);
}

int main() {
    struct addrinfo hints, *servinfo;
    int sockfd;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // IPv4 or IPv6
    hints.ai_socktype = SOCK_DGRAM;

    if (getaddrinfo("localhost", "8080", &hints, &servinfo) != 0) {
        perror("getaddrinfo");
        exit(EXIT_FAILURE);
    }

    sockfd = socket(servinfo->ai_family, servinfo->ai_socktype, servinfo->ai_protocol);

    sendMessage(sockfd, servinfo);
    receiveMessage(sockfd, servinfo);

    freeaddrinfo(servinfo);
    close(sockfd);

    return 0;
}
```
This code is a basic UDP client that sends a message to the server at localhost:8080 and then receives a response. It uses POSIX sockets for network communication, getaddrinfo() for resolving hostnames into usable addresses, sendto() and recvfrom() for sending/receiving messages respectively.

