```c
#include <stdlib.h>
#include <time.h>

// Define a struct for TCP connection details.
typedef struct {
    char IP_ADDRESS[16];
    int PORT_NUMBER;
    int CONNECTION_STATE; // For simplicity, using integers, can be changed to enum or string depending on use case
    time_t LAST_ACTIVE_TIME;
} TCP_CONNECTION_INFO;

#define MAX_CONNECTIONS 10000
TCP_CONNECTION_INFO *connections[MAX_CONNECTIONS]; // Array to store connection info.
int currentConnections = 0;

// Function to add a new connection.
void addConnection(char* ip, int port) {
    if (currentConnections >= MAX_CONNECTIONS) {
        printf("Maximum number of connections reached.\n");
        return;
    }

    TCP_CONNECTION_INFO *newConnection = malloc(sizeof(TCP_CONNECTION_INFO)); // Allocate memory for new connection.
    if (newConnection == NULL) {
        printf("Failed to allocate memory.\n");
        return;
    }

    strcpy(newConnection->IP_ADDRESS, ip);
    newConnection->PORT_NUMBER = port;
    newConnection->CONNECTION_STATE = 0; // Start with default state.
    newConnection->LAST_ACTIVE_TIME = time(NULL);

    connections[currentConnections++] = newConnection; 
}

// Function to remove a connection by index.
void removeConnection(int index) {
    if (index < 0 || index >= currentConnections) {
        printf("Invalid index.\n");
        return;
    }

    free(connections[index]); // Free memory of the removed connection.
    connections[index] = NULL; 
    currentConnections--;
}
```
In this code, a simple array is used to store pointers to `TCP_CONNECTION_INFO` structures. This choice was made due to its simplicity and efficiency for memory access operations. However, it's worth noting that with the current design, adding or removing connections might require shifting elements in the array, which could be costly under high load conditions. Depending on future use cases, a more efficient data structure like a hashmap or linked list might be needed to optimize performance. 

