public class CustomRandomGenerator {
    private readonly int minValue;
    private readonly int maxValue;
    private Random rand = new Random();

    public CustomRandomGenerator(int min, int max) {
        if (min > max) throw new ArgumentOutOfRangeException("Minimum value must be less than or equal to maximum value.");

        minValue = min;
        maxValue = max + 1;
    }

    public float GetRandomFloat() {
        return (float)(rand.NextDouble() * (maxValue - minValue) + minValue);
    }

    public int GetRandomInt() {
        return rand.Next(minValue, maxValue);
    }

    // Generate an integer value within [minValue, maxValue - 1] in this method.
    public int GetRandomIntExclusiveMax() {
        if (maxValue <= minValue + 1) throw new InvalidOperationException("Range must have at least two values to exclude the maximum.");

        return rand.Next(minValue, maxValue - 1);
    }

    public override string ToString() {
        return $"Random number generator between {minValue} and {maxValue - 1}";
    }
}
