    arr->length = 0;
    arr->array = malloc(sizeof(int) * arr->capacity);
}

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void insert(DynamicArray *arr, int val) {
    if (val < 0){
        printf("Invalid value: %d\n", val);
        return;
    }

    pthread_mutex_lock(&lock);  // locking before writing to shared data.
    if(arr->length == arr->capacity) {
        arr->capacity *= 2;
        arr->array = realloc(arr->array, sizeof(int) * arr->capacity);
    }
    arr->array[arr->length] = val;
    arr->length++;
    pthread_mutex_unlock(&lock);  // unlocking after writing to shared data.
}

void printMax(DynamicArray *arr) {
    if (arr->length == 0){
        printf("Array is empty\n");
        return;
    }

    int max = arr->array[0];  // Initialize maximum element
    for(int i = 1; i < arr->length; ++i) { 
       if (arr->array[i] > max)
           max = arr->array[i];
    }
    printf("Largest element: %d\n", max);
