    int count = 0;
    for(int i=0; i < arr->length; ++i) {
        if (arr->array[i] == -1)
            printf("Orphaned element detected\n");
        else 
            ++count;
    }

    // Print statistics.
    printf("Total elements: %d, Orphans: %d\n", count, arr->length - count);
}

