float *read_floats(size_t *count) {
    float *data = NULL;
    size_t capacity = 0;
    size_t size = 0;

    float number;
    while (scanf("%f", &number) == 1) {
        if (!isfinite(number)) continue;  // Skip non-finite numbers.

        if (size >= capacity) {
            capacity = (capacity * 3) / 2 + 8;  // Exponential growth strategy.

            float *new_data = realloc(data, capacity * sizeof(*new_data));
            if (!new_data) goto error;  // Handle memory allocation failure.

            data = new_data;
        }

        data[size++] = number;
    }

    *count = size;
    return data;

error:
    free(data);
    return NULL;
}
```

2) Calculating mean and standard deviation:

These functions assume you have a function for summing an array of floats. Note that calculating the standard deviation involves dividing by `n - 1` (sample standard deviation), not `n` (population standard deviation).

```c
float calculate_mean(const float *data, size_t count) {
    return sum_floats(data, count) / count;
}

float calculate_standard_deviation(const float *data, size_t count, float mean) {
    float variance = 0.0f;

    for (size_t i = 0; i < count; ++i) {
        float deviation = data[i] - mean;
        variance += deviation * deviation;
    }

    return sqrt(variance / (count - 1));
}
```

