```c
#include <stdlib.h>
#include <string.h>
#include <netdb.h>
#include <arpa/inet.h>

struct addrinfo hints;
struct addrinfo *res = NULL, *p = NULL;
int status;
char ipstr[INET6_ADDRSTRLEN];

void getaddrbyname(const char* hostname) {
    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // use IPv4 and IPv6
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return 1;
    }

    for(p = res; p != NULL; p = p->ai_next) {
        void *addr;

        // get pointer to address, different fields in IPv4 and IPv6:
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            addr = &(ipv4->sin_addr);
        } else { // IPv6
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
            addr = &(ipv6->sin6_addr);
        }

        inet_ntop(p->ai_family, addr, ipstr, sizeof ipstr);
        printf("IP address for %s: %s\n", hostname, ipstr);
    }

    freeaddrinfo(res); // free linked list
}
```

This function resolves a hostname to its IPv4 and IPv6 addresses. If the DNS resolution fails for any reason, it prints an error message and returns 1 (an arbitrary value representing "failure"). The results are printed out via printf().

