typedef struct List {
    Node *head;
    pthread_mutex_t lock;  // For thread-safe operations
} List;

List* listCreate() {
    List* list = malloc(sizeof(List));
    if (list == NULL) return NULL;

    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);  // Initialize the lock for thread safety

    return list;
}

void listDestroy(List *list) {
    Node* node = list->head;
    while (node != NULL) {
        Node* tmp = node->next;
        free(node);
        node = tmp;
    }

    pthread_mutex_destroy(&list->lock);  // Destroy the lock
    free(list);
}

