    int RNTI;
    int SRP_DECISION;
    int SRS_REQUEST;
    bool SRS_FLAG; // assuming this is a boolean type
    pthread_mutex_t lock;
} frame_t;

#define MAX_FRAMES 10000
frame_t frames[MAX_FRAMES];
pthread_mutex_t global_lock = PTHREAD_MUTEX_INITIALIZER;
int next_id = 0;

void *propagation_model(void *arg) {
    frame_t* frame = (frame_t*) arg;

    // Propagation model goes here. This might involve complex computation, 
    // so we can benefit from parallelism to reduce total execution time

    pthread_mutex_unlock(&(frame->lock));
    return NULL;
}

void process_frames() {
#pragma omp parallel for schedule(dynamic)
    for (int i = 0; i < next_id; i++) {
        pthread_mutex_lock(&(frames[i].lock));

        // Create a new thread to run the propagation model. This will allow us 
        // to execute other threads while waiting for the model results
        pthread_t thread;
        if (pthread_create(&thread, NULL, propagation_model, &(frames[i])) != 0) {
            exit(1); // Handle error
        }

        pthread_detach(thread); // We don't need to join this thread since it will 
                               // write results into a shared memory location and we 
                               // can safely detach it. This will also prevent zombie threads
    }

    for (int i = 0; i < next_id; i++) {
        pthread_mutex_lock(&(frames[i].lock));

        // At this point, the propagation model should have finished running. 
        // We can safely use the results here.
    }
}

frame_t* allocate_frame() {
    pthread_mutex_lock(&global_lock);

    if (next_id >= MAX_FRAMES) {
        return NULL; // No more space in our frame pool
    }

    frames[next_id].RX_FRAME_ID = next_id++;
    frames[next_id].SRS_FLAG = rand() % 2 == 0; // Randomly generate SRS flag
    pthread_mutex_init(&(frames[next_id - 1].lock), NULL);

    pthread_mutex_unlock(&global_lock);
    return &(frames[next_id - 1]);
}

void deallocate_frame(frame_t* frame) {
    // Free the mutex associated with this frame and reset its ID to indicate it's available again

    pthread_mutex_lock(&global_lock);
    next_id--;
    int id = frame - frames;
    if (next_id != id) {
        // Swap the last frame with this one and update its ID to match its position in the array
        frame_t temp = frames[next_id];
        frames[next_id] = *frame;
        frames[id] = temp;
        frames[id].RX_FRAME_ID = id;
    }

    pthread_mutex_unlock(&global_lock);
    pthread_mutex_destroy(&(frame->lock));
}
```
