#include <string.h>
#include <time.h>
#include "jansson.h"

// Define a structure to represent parsed JSON objects
typedef struct {
    char* key;
    json_t* value;
} ParsedObject;

// This function parses the given JSON string and returns a dynamically allocated array of parsed objects
ParsedObject* parseJSON(const char* input) {
    // Parse the JSON data
    json_error_t error;
    json_t *root = json_loads(input, 0, &error);
    if(!root) {
        fprintf(stderr, "Error parsing JSON: on line %d: %s\n", error.line, error.text);
        return NULL;
    }

    // Allocate memory for an array of parsed objects
    ParsedObject* result = malloc(json_object_size(root) * sizeof(ParsedObject));
    if(!result) {
        fprintf(stderr, "Memory allocation error\n");
        json_decref(root);
        return NULL;
    }

    // Iterate over the JSON object and populate the array of parsed objects
    const char *key;
    json_t *value;
    size_t i = 0;
    json_object_foreach(root, key, value) {
        result[i].key = strdup(key);  // Duplicate the string to ensure it's not deallocated
        if(!result[i].key) {
            fprintf(stderr, "Memory allocation error\n");
            freeParsedObjects(result, i);
            json_decref(root);
            return NULL;
        }

        result[i].value = value;  // Store a reference to the JSON value
        json_incref(value);      // Increment the reference count to ensure it's not deallocated
        i++;
    }

    // Clean up
    json_decref(root);

    return result;
}
```
