// Error handling constants
#define ERR_SUCCESS 0
#define ERR_UNKNOWN -1
#define ERR_TRUSTED_DOMAIN -2
#define ERR_MEMORY_ALLOCATION -3

u_char* resolve(const char *hostname, int *error) {
    struct addrinfo hints;
    struct addrinfo *result;
    u_char *ip = NULL;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = PF_UNSPEC; // IPv4 and IPv6 options
    hints.ai_socktype = SOCK_STREAM; // TCP stream sockets
    hints.ai_flags |= AI_CANONNAME; // Use the canonname if possible

    int res = getaddrinfo(hostname, NULL, &hints, &result);

    if (res != 0) {
        *error = ERR_UNKNOWN; // Error handling is simplified for this example. 
        return ip;
    }

    /* 
      Check if the domain is in a trusted list... 
      If it isn't, set error to ERR_TRUSTED_DOMAIN and return NULL. 

      This part requires file I/O operations (reading from whitelist file)
      which are out of scope for this example. You might want to use a database or some other persistent storage system instead.
    */

    /* Allocate memory for IP address */
    ip = malloc(result->ai_addrlen); 
    if (ip == NULL) {
        *error = ERR_MEMORY_ALLOCATION;
        return NULL;
    }

    /* Copy the resolved IP address to 'ip' buffer */
    memcpy(ip, &((struct sockaddr_in*)result->ai_addr)->sin_addr, result->ai_addrlen); 

    /* Free memory allocated by getaddrinfo() */
    freeaddrinfo(result); 

    *error = ERR_SUCCESS; // Resolved successfully
    return ip;
}
