void addSession(CallSessionInfo_t session) {
    pthread_mutex_lock(&sessionLock);
    if (numSessions >= maxSessions) {
        maxSessions *= 2;
        sessions = realloc(sessions, maxSessions * sizeof(CallSessionInfo_t));
    }
    for (int i = 0; i < numSessions; ++i) {
        if (sessions[i].sessionID == session.sessionID) {
            printf("Error: Duplicate session ID\n");
            pthread_mutex_unlock(&sessionLock);
            return;
        }
    }
    sessions[numSessions++] = session;
    sem_post(&sessionsSemaphore);
    pthread_mutex_unlock(&sessionLock);
}

// Remove a session from the array
void removeSession(int sessionID) {
    pthread_mutex_lock(&sessionLock);
    int index = -1;
    for (int i = 0; i < numSessions; ++i) {
        if (sessions[i].sessionID == sessionID) {
            index = i;
            break;
        }
    }
    if (index == -1) {
        printf("Error: Session not found\n");
    } else {
        --numSessions;
        sessions[index] = sessions[numSessions];
    }
    pthread_mutex_unlock(&sessionLock);
}

// Update an existing session in the array
void updateSession(CallSessionInfo_t newSession) {
    pthread_mutex_lock(&sessionLock);
    for (int i = 0; i < numSessions; ++i) {
        if (sessions[i].sessionID == newSession.sessionID) {
            sessions[i] = newSession;
            break;
        }
    }
    pthread_mutex_unlock(&sessionLock);
}

