        contexts[i] = contexts[i + 1];
    }
    contexts = realloc(contexts, numContexts * sizeof(LTE_Ngap_UeContext_t));

    pthread_mutex_unlock(&mutex);
}

void updateContextByRNTI(int RNTI, LTE_Ngap_UeContext_t newContext) {
    pthread_mutex_lock(&mutex);

    // Update context in contexts array. 
