typedef int (*func_ptr)();

void* loadLib(const char *filename, int flags) {
    void *handle = dlopen(filename, flags);
    if (!handle) {
        fprintf(stderr, "Failed to open library %s: %s\n", filename, dlerror());
        exit(EXIT_FAILURE);
    }
    return handle;
}

func_ptr loadFunc(void *handle, const char *symbol) {
    dlerror();  // Clear any existing error

    func_ptr f = (func_ptr)dlsym(handle, symbol);

    const char *error = dlerror();
    if (error != NULL) {
        fprintf(stderr, "Failed to load symbol %s from library: %s\n", symbol, error);
        exit(EXIT_FAILURE);
    }

    return f;
}
```
