```c
#include <stdlib.h>
#include <pthread.h>

typedef struct LTE_Ngap_UeContext {
    int RNTI;
    // Other fields...
} LTE_Ngap_UeContext_t;

typedef struct ContextArray {
    pthread_mutex_t lock;
    LTE_Ngap_UeContext_t **contexts;
    size_t count, capacity;
} ContextArray_t;

// Initialize the context array
int init(ContextArray_t *array) {
    if (pthread_mutex_init(&array->lock, NULL) != 0) {
        return -1;  // Failed to initialize lock.
    }

    array->count = 0;
    array->capacity = 16;
    array->contexts = malloc(sizeof(LTE_Ngap_UeContext_t *) * array->capacity);
    if (array->contexts == NULL) {
        return -2;  // Failed to allocate memory.
    }

    return 0;  // Success.
}

// Add a new context
int add(ContextArray_t *array, LTE_Ngap_UeContext_t *context) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        if (array->contexts[i]->RNTI == context->RNTI) {
            return -1;  // Duplicate RNTI.
        }
    }

    if (array->count >= array->capacity) {
        array->capacity *= 2;
        LTE_Ngap_UeContext_t **newContexts = realloc(array->contexts, sizeof(LTE_Ngap_UeContext_t *) * array->capacity);
        if (newContexts == NULL) {
            pthread_mutex_unlock(&array->lock);
            return -2;  // Failed to reallocate memory.
        }

        array->contexts = newContexts;
    }

    array->contexts[array->count++] = context;

    pthread_mutex_unlock(&array->lock);

    return 0;  // Success.
}

// Remove a context by RNTI
int removeByRnti(ContextArray_t *array, int rnti) {
    pthread_mutex_lock(&array->lock);

    for (size_t i = 0; i < array->count; ++i) {
        if (array->contexts[i]->RNTI == rnti) {
            free(array->contexts[i]);  // Free the context.

            // Shift all subsequent contexts one position to left.
            for (size_t j = i; j < array->count - 1; ++j) {
                array->contexts[j] = array->contexts[j + 1];
            }

            --array->count;
            pthread_mutex_unlock(&array->lock);

            return 0;  // Success.
        }
    }

    pthread_mutex_unlock(&array->lock);

    return -1;  // RNTI not found.
}
```
This code provides a basic outline of how you can manage dynamic arrays in a multi-threaded environment, including thread safety through mutex locking and efficient handling of memory. However, as this is a very simplified version of your task, please modify it according to your requirements and constraints. This example does not include large scale deployment scenarios and other considerations that you mentioned. 

The `add` function checks for duplicate RNTI's before adding the new context. If a duplicate is found, the add fails with an error code of -1. The removeByRnti function searches through all existing contexts to find the one matching the provided RNTI and removes it if found. If no match is found, it returns an error code of -1.
