    pthread_mutex_t lock; // For thread safety.
} DynamicArray;

DynamicArray *initArray(size_t initialSize) {
    DynamicArray *a = malloc(sizeof *a);
    a->array = malloc(initialSize * sizeof *(a->array));
    a->used = 0;
    a->size = initialSize;
    pthread_mutex_init(&a->lock, NULL); // Initialize the mutex.
    return a;
}

void insertArray(DynamicArray *a, NFAPI_RRC_MEASUREMENT_REPORT element) {
    pthread_mutex_lock(&a->lock);  // Lock to prevent race conditions.

    if (a->used == a->size) {
        a->size *= 2;
        a->array = realloc(a->array, a->size * sizeof *(a->array));
    }
    a->array[a->used++] = element;

    pthread_mutex_unlock(&a->lock);  // Unlock after the critical section.
}

void freeArray(DynamicArray *a) {
    free(a->array);
    a->array = NULL;
    a->used = a->size = 0;

    pthread_mutex_destroy(&a->lock); // Destroy the mutex.
}
