#include <stdio.h>
#include <sys/stat.h>
#include <time.h>
#include <vips/vips.h>

#define MAX_FILE_SIZE (1024 * 1024) // Set to 1MB for demonstration purposes

void processImage(const char* input, const char* outputDir, int width, int height, double quality){
    if(access(outputDir, F_OK) != 0){
        mkdir(outputDir, 0755);
    }

    VipsImage *inputImage;
    vips_magic(&inputImage, input, NULL);

    // Check for image size
    int64_t imageSize = vips_image_get_height(inputImage) * vips_image_get_width(inputImage);
    if (imageSize > MAX_FILE_SIZE){
        printf("File is too large. Skipping...\n");
        return;
    }

    // Perform resizing
    VipsImage* outputImage = vips_resize(inputImage, (double)1/quality, "vscale", width, NULL);
    if(outputImage == NULL){
        printf("Failed to resize image. Skipping...\n");
        return;
    }

    // Generate timestamp and create output filename
    time_t currentTime = time(NULL);
    char timestamp[20];
    strftime(timestamp, 20, "%Y%m%d%H%M%S", localtime(&currentTime));
    int len = snprintf(NULL, 0, "%s/resized_%s_q%d.jpg", outputDir, timestamp, (int)quality);
    char* outputFile = malloc(len + 1);
    sprintf(outputFile, "%s/resized_%s_q%d.jpg", outputDir, timestamp, (int)quality);

    // Save resized image to file
    vips_jpegsave(outputImage, outputFile, "Q", 80, NULL);

    // Clean up
    g_object_unref(inputImage);
    g_object_unref(outputImage);
    free(outputFile);
}
