ImageData process_image(const char* inputFile, const char* outputDir, int compressionLevel, int targetResolution, size_t maxAllowedSize) {
    ImageData result = {0, 0, NULL};

    // Check if the directory exists and create it if necessary
    struct stat st = {0};
    if (stat(outputDir, &st) == -1) {
        mkdir(outputDir, 0700);
    }

    CvSize targetSize;
    // Determine the aspect ratio of the image and resize it
    IplImage* inputImg = cvLoadImage(inputFile, CV_LOAD_IMAGE_COLOR);
    if (!inputImg) {
        return result;
    }

    targetSize.width = targetResolution * (double)inputImg->width / (double)inputImg->height;
    targetSize.height = targetResolution;

    IplImage* resizedImg = cvCreateImage(targetSize, inputImg->depth, inputImg->nChannels);
    if(!resizedImg){
        return result;
    }

    cvResize(inputImg, resizedImg, CV_INTER_LINEAR);

    // Compress the image to meet the maximum allowed size 
    IplImage* compressedImg = NULL;
    int params[] = {CV_IMWRITE_JPEG_QUALITY, compressionLevel};

    while (compressedImg->imageSize > maxAllowedSize) {
        // If compression fails for the first time, try a different algorithm or fallback to default settings
        compressedImg = cvEncodeImage(".jpg", resizedImg, params);

        if (!compressedImg && compressionLevel > 0) {
            compressionLevel -= 10;
            params[0] = 1; // Change compression algorithm or use fallback settings
        } else {
            return result;
        }
    }

    time_t t = time(NULL);
    struct tm* now = localtime(&t);

    char outputFileName[256];
    sprintf(outputFileName, "%s/%ld_compression-level-%d.jpg", outputDir, mktime(now), compressionLevel);

    // Save the compressed image to a file with a unique name based on timestamp and compression level 
    if(!cvSaveImage(outputFileName, compressedImg)){
        return result;
    }

    result.data = compressedImg->imageData;
    result.width = targetSize.width;
    result.height = targetSize.height;

    cvReleaseImage(&inputImg);
    cvReleaseImage(&resizedImg);
    cvReleaseImage(&compressedImg);

    return result;
}
``` 
