['Here is a basic structure of how you can implement this in C using OpenCV and POSIX functions for filesystem manipulations. Please note that the code here doesn't include all the mentioned functionalities due to its complexity, but it should give an idea about how these tasks could be performed. 

```c
#include <opencv2/imgproc/imgproc.hpp>
#include <sys/stat.h>
#include <time.h>
#include <unistd.h>
#include <pthread.h>

#define MAX_IMAGE_SIZE 10000000 // 10MB

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int process_image(char *input, char *outputDir, int compressLevel, int targetResolution[2], int maxExecutionTime) {
    // Verify if output directory exists and create if not
    struct stat st = {0};
    if (stat(outputDir, &st) == -1) {
        mkdir(outputDir, 0755);
    }

    // Load image using OpenCV
    cv::Mat img = cv::imread(input, CV_LOAD_IMAGE_COLOR);
    if(!img.data ) {
       printf("Could not open or find the image\n"); 
       return -1;
    }

    // Check size of the image to prevent processing large files
    int imgSize = img.total() * img.elemSize();
    if(imgSize > MAX_IMAGE_SIZE) {
        printf("Image is too large\n"); 
        return -1;
    }

    // Lock mutex to avoid race conditions
    pthread_mutex_lock(&mutex);

    // Generate output filename with timestamp
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char path[1024];
    sprintf(path, "%s/output_%d-%d-%d_%d:%d:%d.jpg", outputDir, tm->tm_year + 1900, tm->tm_mon + 1, tm->tm_mday, tm->tm_hour, tm->tm_min, tm->tm_sec);

    // Resize and compress the image
    cv::Mat resized;
    cv::resize(img, resized, cv::Size(targetResolution[0], targetResolution[1]), 0, 0, CV_INTER_LINEAR);
    std::vector<int> compression_params;
    compression_params.push_back(cv::IMWRITE_JPEG_QUALITY);
    compression_params.push_back(compressLevel);

    // Check if the execution time exceeds the maximum allowed
    clock_t start = clock();
    cv::imwrite(path, resized, compression_params);
    clock_t end = clock();
    double elapsedTime = ((double) (end - start)) / CLOCKS_PER_SEC; // in seconds

    if(elapsedTime > maxExecutionTime/1000.0) {
        printf("Maximum allowed execution time exceeded\n"); 
        return -1;
    }

    pthread_mutex_unlock(&mutex);

    // Release memory
    img.release();
    resized.release();

    return 0;
}
```

Please note that actual implementation may vary depending on the exact requirements and specifics of the third-party image processing library used (in this case OpenCV). Make sure to handle errors properly, especially when working with external libraries. Also remember to release any allocated resources once you are done with them.
