['To solve this task, we would need to use specific libraries such as libjpeg-turbo for compression, OpenMP for parallelism, and libvips library for resizing images. I'm writing a basic solution that you can customize according to your needs.

```c
#include <dirent.h>
#include <omp.h>
#include <sys/stat.h>
#include <time.h>
#include <vips/vips.h>

typedef struct {
    char *filename;
    int success; // 1 for successful, 0 for failed
} ImageProcessResult;

void process_image(char* input_dir, char* output_dir, float compression, int width, int height) {
    DIR *d;
    struct dirent *dir;
    d = opendir(input_dir);

    if (!d) return; // Handle error here

    mkdir(output_dir, 0700); // Create output directory if it doesn't exist

    ImageProcessResult* results = malloc(sizeof(ImageProcessResult));
    int result_count = 0;

    if (d) {
        while ((dir = readdir(d)) != NULL) {
            // Skip directories and . and ..
            if (strcmp(dir->d_name, ".") == 0 || strcmp(dir->d_name, "..") == 0 || dir->d_type == DT_DIR) continue;

            #pragma omp parallel for num_threads(omp_get_num_procs())
            for (int i = 0; i < omp_get_max_threads(); i++) {
                VipsImage *input, *output;
                char output_path[256];

                // Load image
                if(vips_jpegload(dir->d_name, &input, NULL) != 0) {
                    // Handle error here
                    continue;
                }

                // Resize and compress
                if (vips_resize(input, &output, compression / 100.0, "centre", width, height, NULL)!=0){
                     vips_image_free(input);
                     // Handle error here
                     continue;
                }

                sprintf(output_path, "%s/%s_compressed%.2f.jpg", output_dir, dir->d_name, compression / 100.0);

                if (vips_jpegsave(output, output_path, "Q", compression, NULL) != 0){
                     vips_image_free(input);
                     vips_image_free(output);
                     // Handle error here
                     continue;
                }

                vips_image_free(input);
                vips_image_free(output);

                results = realloc(results, (result_count + 1) * sizeof(ImageProcessResult));
                results[result_count].filename = strdup(dir->d_name);
                results[result_count].success = 1; // Successful operation
                result_count++;
            }
        }
    }
}
```
Please note that error handling and logging are very basic here. It's a good practice to implement meaningful error codes, verbose error messages and robust logging. Also this is just a simple demo, in reality you would want to use more sophisticated methods for file IO operations and handle concurrency better.
