void process_image(const char *input, const char *outputDir, int compressionLevel, cv::Size targetResolution, long maxExecTime) {
    // Check if the output directory exists and create it if necessary
    struct stat st = {0};
    if (stat(outputDir, &st) == -1) {
        mkdir(outputDir, 0755);
    }

    cv::Mat image;
    // Load the input image
    try {
        image = imread(input, IMREAD_COLOR);
    } catch (cv::Exception &e) {
        printf("Error loading image: %s\n", e.what());
        return;
    }

    // Check if the image is empty or not
    if(!image.data ) {
        printf("Image file '%s' could not be open or it's not an image.\n", input);
        return;
    }

    clock_t start = clock();
    double duration = 0.0;

    // Resize the image to target resolution
    cv::Mat resizedImage;
    try {
        resize(image, resizedImage, targetResolution);
    } catch (cv::Exception &e) {
        printf("Error resizing image: %s\n", e.what());
        return;
    }

    // Compress the image with specified level
    std::vector<int> compressionParams;
    compressionParams.push_back(IMWRITE_JPEG_QUALITY);
    compressionParams.push_back(compressionLevel);
    char output[512];

    // Generate unique filename
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    sprintf(output, "%s/%lu.jpg", outputDir, (long)tm.tv_sec);

    try {
        imwrite(output, resizedImage, compressionParams);
    } catch (cv::Exception &e) {
        printf("Error writing image: %s\n", e.what());
        return;
    }

    // Calculate elapsed time for performance measurement
    duration = ((double)(clock() - start)) / CLOCKS_PER_SEC;
    if(duration * 1000 > maxExecTime) {
        printf("Processing image took too long: %f sec. Limit is %ld ms.\n", duration, maxExecTime);
        return;
    }

    printf("Image successfully processed and saved to '%s'.\n", output);
}
