```c
#include <stdio.h>
#include <pthread.h>
#include <semaphore.h>
#include <sys/time.h>

typedef struct NFAPI_RLC_LAYER {
    int type;
    size_t size;
    int priority;
    char *Packet_ID;
    int Sequence_Number;
    bool Acknowledgment_Status;
} NFAPI_RLC_LAYER;

typedef struct resource_and_packet_manager {
    pthread_mutex_t lock;
    sem_t semaphore;
    size_t max_resources;
    size_t allocated_resources;
    NFAPI_RLC_LAYER *pdus;
} resource_and_packet_manager;

void init_resource_and_packet_manager(resource_and_packet_manager *manager, size_t max_resources) {
    sem_init(&manager->semaphore, 0, max_resources);
    pthread_mutex_init(&manager->lock, NULL);
    manager->max_resources = max_resources;
    manager->allocated_resources = 0;
    manager->pdus = calloc(sizeof(NFAPI_RLC_LAYER), max_resources);
}

void allocate_resource(resource_and_packet_manager *manager, NFAPI_RLC_LAYER pdu) {
    sem_wait(&manager->semaphore);  // wait until there's an available resource
    pthread_mutex_lock(&manager->lock);  // acquire the lock before modifying shared data
    manager->pdus[manager->allocated_resources++] = pdu;  // add the new PDU
    pthread_mutex_unlock(&manager->lock);  // release the lock after modification
}

NFAPI_RLC_LAYER deallocate_resource(resource_and_packet_manager *manager, int index) {
    NFAPI_RLC_LAYER res;
    pthread_mutex_lock(&manager->lock);  // acquire the lock before modifying shared data
    if (index < manager->allocated_resources) {
        res = manager->pdus[index];
        for(int i=index+1; i<manager->allocated_resources; ++i) {
            manager->pdus[i-1] = manager->pdus[i];  // shift all remaining PDUs to fill the space
        }
        --manager->allocated_resources;  // decrement allocated resource counter
    } else {
        printf("Index out of bound\n");
    }
    pthread_mutex_unlock(&manager->lock);  // release the lock after modification
    sem_post(&manager->semaphore);  // signal that a resource is available again
    return res;
}
```
The above code only gives you the basic skeleton for managing resources and PDUs. It doesn't handle all your requirements such as different allocation modes, integration with NMS, logging events, monitoring statistics, cache implementation etc. You will need to extend this based on your requirements. Also note that error handling and edge case detection are not covered in the above code, you have to add these according to your specific needs.
