    ueContextPool = (UeContext*) malloc(N * sizeof(UeContext));
}

bool addUeContext(char* GUTI, char* IMSI) {
    pthread_mutex_lock(&lock);

    if(numOfContexts < N) {
        ueContextPool[numOfContexts].GUTI = strdup(GUTI);
        ueContextPool[numOfContexts].IMSI = strdup(IMSI);
        ++numOfContexts;
        pthread_mutex_unlock(&lock);
        return true;
    } else {
        // Dynamic allocation of resources
        N *= 2;
        ueContextPool = realloc(ueContextPool, N * sizeof(UeContext));

        if(!ueContextPool) {
            pthread_mutex_unlock(&lock);
            return false;
        }

        // Add the new context
        ueContextPool[numOfContexts].GUTI = strdup(GUTI);
        ueContextPool[numOfContexts].IMSI = strdup(IMSI);
        ++numOfContexts;
        pthread_mutex_unlock(&lock);
        return true;
    }
}

