@Path("/md5")
public class MD5Service {
    private static Map<String, String> hashMap = new HashMap<>(); // this is where we will store our hashes
    @POST
    public Response calculateMD5(List<String> strings) {
        List<String> hashes = new ArrayList<>();
        for (String s : strings) {
            if (!hashMap.containsKey(s)) { // if the string is not already in our map, compute and store its hash
                String md5Hex = DigestUtils.md5Hex(s);
                hashes.add(md5Hex);
                hashMap.put(s, md5Hex);
            } else { // if the string is already in our map, retrieve its stored hash
                hashes.add(hashMap.get(s));
            }
        }
        return Response.ok(hashes).build();
    }
}
```

