UEContext* allocate_ue_context() {
    UEContext* ctx = g_new(UEContext, 1);
    if (ctx == NULL) return NULL;

    // Initialize fields...

    return ctx;
}

// Deallocates a UE context.
void deallocate_ue_context(UEContext *ctx) {
    if (ctx != NULL) g_free(ctx);
}

// Allocates the UE context pool and initializes each context.
gboolean initialize_context_pool() {
    g_mutex_lock(&lock);  // Lock to ensure thread safety during initialization

    if (contextPool != NULL) {
        // Pool already initialized, do nothing
        g_mutex_unlock(&lock);
        return TRUE;
    }

    contextPool = g_array_sized_new(FALSE, FALSE, sizeof(UEContext*), N);
    if (contextPool == NULL) {
        // Failed to allocate memory for the pool
        g_mutex_unlock(&lock);
        return FALSE;
    }

    // Initialize each context in the pool...

    g_mutex_unlock(&lock);  // Unlock after initialization is complete
    return TRUE;
}

// Deallocates and clears the UE context pool.
void clear_context_pool() {
    g_mutex_lock(&lock);

    if (contextPool == NULL) {
        g_mutex_unlock(&lock);
        return;
    }

    // Deallocate and clear each UE context in the pool...

    g_array_free(contextPool, TRUE);  // Free the array memory
    contextPool = NULL;

    g_mutex_unlock(&lock);
}

// Function to validate an OAuth2 access token response string.
gboolean validate_token_response(const char *jsonString) {
    json_error_t error;
    json_t *root = json_loads(jsonString, 0, &error);

    if (!root) return FALSE; // Failed to parse JSON string

    json_t *accessToken = json_object_get(root, "access_token");
    json_t *expiresIn = json_object_get(root, "expires_in");
    json_t *tokenType = json_object_get(root, "token_type");

    if (!json_is_string(accessToken) || !json_is_integer(expiresIn) || !json_is_string(tokenType)) {
        // Required fields are not present or have incorrect types
        json_decref(root);
        return FALSE;
    }

    if (strcmp(json_string_value(tokenType), "Bearer") || json_integer_value(expiresIn) <= 0) {
        // Invalid token type or expires_in value
        json_decref(root);
        return FALSE;
    }

    json_decref(root);
    return TRUE;
}
