['Here is a basic implementation of such a C function using linked list as an approach to store GTPU_PDU structs:

```C
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct gtpv2_c_message {
    // Add necessary fields here
} GTPV2_C_MESSAGE;

typedef struct gtpu_pdu {
    int UE_ID;
    int TEID;
    unsigned char GTP_FLAGS;
    GTPV2_C_MESSAGE* GTPV2_C_MESSAGE;
} GTPU_PDU;

typedef struct node {
    GTPU_PDU* data;
    struct node* next;
} Node;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

Node* initializeGTPU_PDUs(int N) {
    srand(time(NULL));

    Node* head = NULL;
    Node* tail = NULL;

    for (int i = 0; i < N; ++i) {
        GTPU_PDU* pdu = malloc(sizeof(GTPU_PDU));
        if (!pdu) {
            // handle error
            continue;
        }

        pdu->UE_ID = i + 1;  // Assign a valid UE_ID here
        pdu->TEID = 0;       // Default TEID value, change as necessary
        pdu->GTP_FLAGS = rand() % 256;   // Random GTP_FLAG generation

        Node* node = malloc(sizeof(Node));
        if (!node) {
            // handle error
            free(pdu);
            continue;
        }

        pthread_mutex_lock(&lock);  // Ensuring thread safety

        node->data = pdu;
        node->next = NULL;

        if (!head) {
            head = tail = node;
        } else {
            tail->next = node;
            tail = node;
        }

        pthread_mutex_unlock(&lock);  // Release lock after critical section operation
    }

    return head;
}
```
This code initializes a linked list of GTPU_PDU structures with N elements. Each element contains a randomly generated GTP_FLAGS field and is thread-safe, allowing concurrent access without race conditions. Error handling is basic and may need to be expanded upon based on specific needs. The returned linked list should be handled properly to prevent memory leaks or corruption.
