        } else {
            tail->next = newNode;
            tail = newNode;
        }
    }

    pthread_mutex_unlock(&lock); // unlocking after successful initialization

    GTPU_PDU *pduArray = malloc(N * sizeof(GTPU_PDU));  // allocating memory for the array of structures

    if (pduArray == NULL) {
        printf("Failed to allocate memory for PDUs. Exiting...\n");
        exit(-1);  
    }

    Node* temp = head;
    int i = 0;
    while(temp != NULL){  // copying the linked list into array for easy access
        pduArray[i++] = temp->pdu;
        Node *toBeDeleted = temp;
        temp = temp->next;
        free(toBeDeleted);  // deallocating memory from linked list nodes
    }

    return pduArray;
}
```
This code first allocates and initializes the required GTPU_PDU structures in a linked list. If any allocation fails, it frees up all previously allocated memory and exits with an error message. After successfully allocating and initializing the structures, it converts the linked list to array for easier access and deallocates the memory from linked list nodes. This way, it efficiently manages memory and minimizes latency during packet processing. It also ensures thread safety by using mutex locks before modifying data and unlocking after successful initialization or failure.
