    int size;
} dynamicList_t;

dynamicList_t* createDynamicList() {
    srand(time(NULL));

    dynamicList_t* dl = (dynamicList_t*) malloc(sizeof(dynamicList_t));
    if (!dl) return NULL; // Check for allocation failure

    pthread_mutex_init(&(dl->lock), NULL); // Initialize mutex

    dl->list = (NFAPI_CRC_INDICATION_PDU_T**) malloc(MAX_ELEMS * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!dl->list) { // Check for allocation failure
        free(dl);
        return NULL;
    }

    dl->size = 0;
    return dl;
}

void addElementToList(dynamicList_t* list, NFAPI_CRC_INDICATION_PDU_T* elem) {
    pthread_mutex_lock(&(list->lock)); // Lock for thread safety

    if (list->size < MAX_ELEMS) {
        list->list[list->size] = elem;
        list->size++;
    } else {
        free(elem); // If list is full, free the element to avoid memory leak
    }

    pthread_mutex_unlock(&(list->lock)); // Unlock for thread safety
}

void cleanupUnusedStructures(dynamicList_t* list) {
    pthread_mutex_lock(&(list->lock)); // Lock for thread safety

    int i = 0;
    while (i < list->size) {
        if (!list->list[i]->valid) {
            free(list->list[i]); // Free unused structure

            // Shift all subsequent elements one position to the left
            for (int j = i; j < list->size - 1; j++) {
                list->list[j] = list->list[j + 1];
            }

            list->size--; // Decrement size after removal
        } else {
            i++;
        }
    }

    pthread_mutex_unlock(&(list->lock)); // Unlock for thread safety
}

void clearList(dynamicList_t* list) {
    pthread_mutex_destroy(&(list->lock)); // Destroy mutex to release resources

    // Free all structures in the list
    for (int i = 0; i < list->size; i++) {
        free(list->list[i]);
    }

    free(list->list); // Free array holding pointers to structures
    free(list); // Free dynamicList_t structure
}
``` 
