```c
#include <stdlib.h>
#include <pthread.h>

typedef enum {ESTABLISHED, TIME_WAIT} state;

struct IPAddress{
    // Assume this struct represents an IPv4 or IPv6 address
};

typedef struct TNL_CONNECTION_RECORD_T{
    struct IPAddress src_ip;
    struct IPAddress dst_ip;
    state connection_state;
    struct TNL_CONNECTION_RECORD_T* next;
} TNL_CONNECTION_RECORD_T;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

TNL_CONNECTION_RECORD_T *head = NULL;
int record_count = 0;
const int MAX_LIMIT = 10000; // This can be changed dynamically as per need.

void add_record(struct IPAddress src, struct IPAddress dst){
    pthread_mutex_lock(&lock);  // locking before adding a record to ensure no concurrent modifications

    if (record_count >= MAX_LIMIT) {
        printf("Max limit reached.\n");
        return;
    }

    TNL_CONNECTION_RECORD_T *new_node = malloc(sizeof(TNL_CONNECTION_RECORD_T));
    if (new_node == NULL) {
        printf("Failed to allocate memory.\n");
        return;
    }

    new_node->src_ip = src;
    new_node->dst_ip = dst;
    new_node->connection_state = rand()%2 == 0 ? ESTABLISHED : TIME_WAIT; // random state initialization
    new_node->next = NULL;

    if (head == NULL) {
        head = new_node;
    } else {
        TNL_CONNECTION_RECORD_T *current = head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }

    record_count++;
    pthread_mutex_unlock(&lock);  // releasing lock after adding a record to avoid other threads from modifying it
}
```

