void initCollection(TNL_CONNECTION_COLLECTION_T* col, size_t initialCapacity) {
    col->records = malloc(sizeof(TNL_CONNECTION_RECORD_T) * initialCapacity);
    col->count = 0;
    col->capacity = initialCapacity;
    pthread_mutex_init(&col->lock, NULL);
}

// Ensure that the collection can store at least 'num' records
void ensureCapacity(TNL_CONNECTION_COLLECTION_T* col, size_t num) {
    if (col->count + num > col->capacity) {
        size_t newCapacity = col->capacity * 2;
        while (newCapacity < col->count + num) newCapacity *= 2;
        TNL_CONNECTION_RECORD_T* newRecords = malloc(sizeof(TNL_CONNECTION_RECORD_T) * newCapacity);
        memcpy(newRecords, col->records, sizeof(TNL_CONNECTION_RECORD_T) * col->count);
        free(col->records);
        col->records = newRecords;
        col->capacity = newCapacity;
    }
}

// Add a record to the collection
void addRecord(TNL_CONNECTION_COLLECTION_T* col, TNL_CONNECTION_RECORD_T rec) {
    pthread_mutex_lock(&col->lock);
    ensureCapacity(col, 1);
    memcpy(&col->records[col->count], &rec, sizeof(TNL_CONNECTION_RECORD_T));
    col->count++;
    pthread_mutex_unlock(&col->lock);
}
