    fprintf(logFile, "%s\n", msg);
    fflush(logFile);
    pthread_rwlock_unlock(&rwLock);
}

SessionKey* createSessionKey() {
    SessionKey *key = malloc(sizeof(SessionKey));

    // Initialize the key...

    return key;
}

void addToCache(SessionKey *key) {
    pthread_rwlock_wrlock(&rwLock);

    if (numOfSlabs == 0 || slabs[numOfSlabs - 1].size >= N) {
        Slab *slab = malloc(sizeof(Slab));

        // Initialize the slab...

        slabs = realloc(slabs, ++numOfSlabs);
        slabs[numOfSlabs - 1] = *slab;
    }

    int slotIndex = 0;

    while (slotIndex < N && slabs[numOfSlabs - 1].keys[slotIndex].sessionID != NULL) {
        slotIndex++;
    }

    if (slotIndex >= N) {
        error("Session key cache is full!");
        return;
    }

    slabs[numOfSlabs - 1].keys[slotIndex] = *key;
    free(key);

    pthread_rwlock_unlock(&rwLock);
}
