typedef struct Node {
    DL_SRS_TX_REQ_T data;
    struct Node *prev;
    struct Node *next;
} Node;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
Node *head = NULL;  // Initial empty list.

// Assuming external function prototype is: int fetch_srs_info(int srs_config_id, DL_SRS_TX_REQ_T* data);

void insert_ordered(DL_SRS_TX_REQ_T element) {
    pthread_mutex_lock(&lock);

    fetch_srs_info(element.SRS_CONFIG_ID, &element);  // Fetch SRS info from the external library

    Node *node = malloc(sizeof(Node));
    assert(node != NULL);  // Handle memory allocation failure.
    node->data = element;

    if (head == NULL || head->data.SRS_CONFIG_ID > element.SRS_CONFIG_ID) {  // Insert at the head
        node->next = head;
        if (head != NULL) {
            head->prev = node;
        }
        head = node;
    } else {  // Insert in sorted order
        Node *curr = head;
        while (curr->next != NULL && curr->data.SRS_CONFIG_ID < element.SRS_CONFIG_ID) {
            curr = curr->next;
        }

        node->prev = curr;
        node->next = curr->next;
        if (curr->next != NULL) {
            curr->next->prev = node;
        }
        curr->next = node;
    }

    pthread_mutex_unlock(&lock);
}

void delete(int srs_config_id) {
    pthread_mutex_lock(&lock);

    Node *curr = head;
    while (curr != NULL && curr->data.SRS_CONFIG_ID != srs_config_id) {  // Find node to delete
        curr = curr->next;
    }

    if (curr != NULL) {  // If found, remove it from the list
        if (curr->prev != NULL) {
            curr->prev->next = curr->next;
        } else {  // Node was at head of the list
            head = curr->next;
        }

        if (curr->next != NULL) {
            curr->next->prev = curr->prev;
        }

        free(curr);  // Free memory.
    }

    pthread_mutex_unlock(&lock);
}
