#include <stdlib.h>
#include <time.h>

typedef struct Connection {
    int clientID;
    char* serverAddress;
    time_t lastActiveTimestamp;
} Connection;

Connection** connections = NULL;
size_t connectionCount = 0;

void addConnection(int clientID, const char* serverAddress) {
    Connection* conn = malloc(sizeof(Connection));
    conn->clientID = clientID;
    conn->serverAddress = strdup(serverAddress);
    conn->lastActiveTimestamp = time(NULL);
    ++connectionCount;
    connections = realloc(connections, connectionCount * sizeof(Connection*));
    connections[connectionCount - 1] = conn;
}

void removeInactiveConnections(time_t timeout) {
    for (size_t i = 0; i < connectionCount; ++i) {
        if (connections[i]->lastActiveTimestamp + timeout < time(NULL)) {
            free(connections[i]->serverAddress);
            free(connections[i]);
            connections[i] = NULL;
        }
    }
}

Connection** getActiveConnections() {
    Connection** activeConnections = malloc(connectionCount * sizeof(Connection*));
    size_t j = 0;
    for (size_t i = 0; i < connectionCount; ++i) {
        if (connections[i] != NULL) {
            activeConnections[j++] = connections[i];
        }
    }
    return activeConnections;
}
