void *convertVideo(void *arg) {
    // Implement your video conversion here

    pthread_mutex_lock(&mtx); 
    numThreads--;
    pthread_mutex_unlock(&mtx);
}

int convertAndLimitBatch(char* inputFile, char* outputDir, char* codecType, int batchLimit) {
    // Ensure that the output directory exists
    if (access(outputDir, F_OK) != 0) {
        printf("Output directory does not exist.\n");
        return 1;
    }

    pthread_t tid[batchLimit];
    int threadCount = 0;
    char outputFile[MAX_FILENAME];

    // Generate the output file name based on input and codec type
    sprintf(outputFile, "%s/%s.%s", outputDir, strtok(inputFile, "."), codecType);

    while (threadCount < batchLimit) {
        pthread_mutex_lock(&mtx); 
        numThreads++;
        if (numThreads <= batchLimit) {
            // If there're less than or equal to batch limit, start a new thread for conversion
            if(pthread_create(&tid[threadCount], NULL, convertVideo, outputFile)) {
                printf("Failed to create thread\n"); 
                return 1;
            } else {
                threadCount++;
            }
        }
        pthread_mutex_unlock(&mtx);
    }

    // Wait for all threads to complete
    for (int i = 0; i < batchLimit; ++i) {
       if(pthread_join(tid[i], NULL)) {
           printf("Failed to join thread\n"); 
           return 1;
       }
    }

    return 0;
}
```
Please note that this is just a basic structure and does not include the actual encoding process, which you would need to implement using third-party libraries or system calls depending on your operating system. Also please add error checking according to your requirements.
