        printf("Memory allocation failed!\n");
        return NULL;
    }

    pthread_mutex_lock(&lock);
    while (fgets(line, sizeof line, file)) {
        char *token = strtok(line, ",");

        if(counter >= 5000) {
            printf("Exceeded maximum entries!\n");
            break;
        } else if(token == NULL) {
            printf("Malformed entry\n");
            continue;
        }

        users[counter].USER_ID = atoi(token);

        token = strtok(NULL, ",");
