            String password = kms.getPassword();
            String encryptedPassword = passwordEncryption.encrypt(password);
            sed.appendLine(config, "encrypted_password: " + encryptedPassword); 
        } catch (Exception e) {
            // handle encryption failures and key management service failures exceptions
            logError(e); 
            return null;
        }

