typedef struct NFAPI_CRC_INDICATION_PDU_T {
    // define fields here
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
Node *head = NULL;

void insert(NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&lock);

    Node* node = (Node*) malloc(sizeof(Node));
    if(node == NULL) {
        // Handle memory allocation failure
        pthread_mutex_unlock(&lock);
        return;
    }
    node->data = data;
    node->next = NULL;

    Node **indirect = &head;

    while(*indirect && (*indirect)->data.RNTI < data.RNTI) {
        indirect = &((*indirect)->next);
    }

    node->next = *indirect;
    *indirect = node;

    pthread_mutex_unlock(&lock);
}

void delete(int RNTI) {
    pthread_mutex_lock(&lock);

    Node **indirect = &head;

    while(*indirect && (*indirect)->data.RNTI != RNTI) {
        indirect = &((*indirect)->next);
    }

    if(*indirect) {
        Node *to_delete = *indirect;
        *indirect = to_delete->next;

        free(to_delete);
    }

    pthread_mutex_unlock(&lock);
}

// Implement CRC processing library and other functionalities based on your requirements. 
