#include <stdlib.h>

typedef struct LTE_Uplink_Signal_Report {
    float measurement_report;
    int frequency;
    int timing_advance;
} LTE_Uplink_Signal_Report;

typedef struct Node {
    LTE_Uplink_Signal_Report report;
    struct Node *next;
} Node;

Node* create_node(LTE_Uplink_Signal_Report report) {
    Node* newNode = (Node*) malloc(sizeof(Node));
    newNode->report = report;
    newNode->next = NULL;
    return newNode;
}

void add_report(Node** head, LTE_Uplink_Signal_Report report) {
    Node* newNode = create_node(report);

    if (*head == NULL || (report.frequency >= 2000 && report.frequency <= 3000)) { // pre-defined frequency range
        newNode->next = *head;
        *head = newNode;
    } else {
        printf("Invalid frequency detected: %d\n", report.frequency);
    }
}

void remove_report(Node** head, int frequency) {
    Node* temp = *head;
    Node* prev = NULL;

    if (temp != NULL && temp->report.frequency == frequency) {
        *head = temp->next;
        free(temp);
        return;
    }

    while (temp != NULL && temp->report.frequency != frequency) {
        prev = temp;
        temp = temp->next;
    }

    if (temp == NULL) return;

    prev->next = temp->next;
    free(temp); 
}

void iterate_reports(Node* node) {
    while (node != NULL) {
        printf("Report: %f, Frequency: %d, Timing Advance: %d\n", node->report.measurement_report, node->report.frequency, node->report.timing_advance);
        node = node->next;
    }
}
