['```C#
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;

public class DataProcessor
{
    private readonly List<double> buffer = new List<double>();
    private int windowSize;
    private readonly ReaderWriterLockSlim locker = new ReaderWriterLockSlim();

    public DataProcessor(int windowSize, IEnumerable<double> initialData)
    {
        this.windowSize = windowSize;
        buffer = initialData.ToList();
    }

    public void AddData(double value)
    {
        locker.EnterWriteLock();
        try
        {
            buffer.Add(value);
            if (buffer.Count > windowSize)
                buffer.RemoveAt(0);
        }
        finally
        {
            locker.ExitWriteLock();
        }
    }

    public void FilterData(int threshold)
    {
        locker.EnterWriteLock();
        try
        {
            for (var i = buffer.Count - 1; i >= 0 ; --i)
                if (buffer[i] < threshold)
                    buffer.RemoveAt(i);
        }
        finally
        {
            locker.ExitWriteLock();
        }
    }

    public void TransformData(Func<double, double> transform)
    {
        locker.EnterReadLock();
        try
        {
            for (var i = 0; i < buffer.Count; ++i)
                buffer[i] = transform(buffer[i]);
        }
        finally
        {
            locker.ExitReadLock();
        }
    }

    public double AggregateData(Func<IEnumerable<double>, double> aggregator)
    {
        locker.EnterReadLock();
        try
        {
            return aggregator(buffer);
        }
        finally
        {
            locker.ExitReadLock();
        }
    }

    public IEnumerable<double> GetDataWindow()
    {
        locker.EnterReadLock();
        try
        {
            return buffer;
        }
        finally
        {
            locker.ExitReadLock();
        }
    }

    public override string ToString()
    {
        locker.EnterReadLock();
        try
        {
            return $"Window Size: {windowSize}, Buffer: [{string.Join(", ", buffer)}]";
        }
        finally
        {
            locker.ExitReadLock();
        }
    }
}
