#include <stdlib.h>
#include <time.h>

typedef struct {
    int connectionID;
    time_t lastActivityTimestamp;
    double currentBandwidthUsage;
} ConnectionState;

ConnectionState* connections = NULL; // dynamic array of connections
int size = 0; // number of elements in the array

void addConnection(int connectionID) {
    if (connections == NULL) {
        connections = malloc(sizeof(ConnectionState));
    } else {
        connections = realloc(connections, sizeof(ConnectionState) * (size + 1));
    }
    ConnectionState newConnection;
    newConnection.connectionID = connectionID;
    newConnection.lastActivityTimestamp = time(NULL); // current timestamp
    newConnection.currentBandwidthUsage = 0.0; 
    connections[size] = newConnection;
    size++;
}

void removeConnection(int index) {
    if (index < size - 1) {
        for (int i = index; i < size - 1; i++) {
            connections[i] = connections[i + 1]; // shift elements to fill the gap
        }
    }
    size--;
    if (size == 0) {
        free(connections);
        connections = NULL;
    } else {
        connections = realloc(connections, sizeof(ConnectionState) * size);
    }
}
``` 
