import java.util.*;
import java.util.concurrent.*;
import java.util.logging.*;

public class MessageBroker {
    private final ExecutorService executor;
    private final ConcurrentLinkedQueue<Message> queue;

    public MessageBroker() {
        this.executor = new ThreadPoolExecutor(5, 10, 60L, TimeUnit.SECONDS, new SynchronousQueue<Runnable>());
        this.queue = new ConcurrentLinkedQueue<>();

        // Start a thread to handle messages from the queue
        executor.execute(() -> {
            while (!Thread.currentThread().isInterrupted()) {
                try {
                    Message message = queue.poll(1, TimeUnit.SECONDS);

                    if (message != null) {
                        handleMessage(message);
                    } else {
                        scaleDownIfNeeded();
                    }
                } catch (Exception e) {
                    Logger.getGlobal().log(Level.WARNING, "Error handling message", e);
                }
            }
        });
    }

    public void publishMessage(Message message) {
        queue.add(message);
        scaleUpIfNeeded();
    }

    private void handleMessage(Message message) throws Exception {
        // process the message...

        // if processing takes a long time, you might want to check for interruptions
        Thread.sleep(100);  // simulate slow processing
    }

    private synchronized void scaleUpIfNeeded() {
        // implement logic to increase number of worker threads based on queue size and system metrics
    }

    private synchronized void scaleDownIfNeeded() {
        // implement logic to decrease number of worker threads when there are no messages in the queue 
    }
}
