// Error handling and logging mechanism can be added as needed.

void* allocateStructures(size_t numberOfStructures, size_t bufferSizeInBytes, int maxRetries) {
    // Validate inputs.
    if (numberOfStructures <= 0 || bufferSizeInBytes < STRUCTURE_SIZE) {
        return NULL;
    }

    void* buffer = NULL;
    size_t allocatedBytes = 0;
    int retryCount = 0;

    while (allocatedBytes < numberOfStructures * STRUCTURE_SIZE && retryCount <= maxRetries) {
        // Lock the mutex to ensure thread-safe allocation.
        pthread_mutex_lock(&mutexBufferAllocation);

        size_t remainingSize = bufferSizeInBytes - allocatedBytes;
        void* newBuffer = malloc(remainingSize);

        if (newBuffer != NULL) {
            // If this is not the first allocation, copy the existing structures to the new buffer.
            if (buffer != NULL) {
                memcpy(newBuffer, buffer, allocatedBytes);
            }

            free(buffer);  // Free the old buffer.
            buffer = newBuffer;

            // Populate the remaining structures with valid data here.
        } else {
            sleep((1 << retryCount) * 500);  // Exponential backoff between retries.
            ++retryCount;
        }

        pthread_mutex_unlock(&mutexBufferAllocation);
    }

    if (allocatedBytes < numberOfStructures * STRUCTURE_SIZE) {
        free(buffer);  // If allocation failed, free the partial buffer.
        return NULL;
    }

    // Log successful memory allocation here.

    return buffer;
}
