```cpp
#include <iostream>
#include <vector>
#include <ctime>
#include <algorithm>
#include <unordered_map>

class ConnectionState {
public:
    int connectionID;
    time_t lastActivityTimestamp;
    double currentBandwidthUsage; // this should be more accurate, e.g., uint64_t or similar if possible
    bool activeStatus;
};

std::unordered_map<int, ConnectionState> connections;
time_t timeWindow = 10;  // pre-defined time window in seconds
double smoothingFactor = 0.25;

void manageConnections() {
    auto currentTime = std::time(nullptr);

    for (auto it = connections.begin(); it != connections.end();) {
        // Check if connection is stale and delete if so
        if (currentTime - it->second.lastActivityTimestamp > timeWindow) {
            it = connections.erase(it);  // This will not invalidate the iterator as required by C++11 and later.
        } else {
            ++it;
        }
    }

    for (auto& connection : connections) {
        // Smoothing algorithm to handle variable data rates
        connection.second.currentBandwidthUsage = smoothingFactor * connection.second.currentBandwidthUsage + (1 - smoothingFactor) * calculateActualBandwidth(connection.first);

        // Logging mechanism
        if (std::exchange(connection.second.activeStatus, isActive(connection.first)) != connection.second.activeStatus) {
            std::cout << "Connection state changed for connection ID: " << connection.first << ". New status: " << (connection.second.activeStatus ? "Active" : "Inactive") << "\n";
        }
    }
}
```
