['Here's an implementation in C:

```c
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct {
    // add your data here
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node{
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct Node* next;
} Node;

sem_t bufferSem; // semaphore to manage the access to the buffer and statistics
int totalMemory = 0;
Node* head = NULL;
Node* tail = NULL;

void* allocate(int size, int attempt){
    void* buf = malloc(size);
    if (buf == NULL && attempt < 5){
        sleep(pow(2, attempt)); // exponential backoff
        return allocate(size, attempt + 1);
    } else if (buf == NULL) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE); 
    }

    sem_wait(&bufferSem); // lock the buffer for modifications
    totalMemory += size;
    printf("Memory usage: %d\n", totalMemory);
    sem_post(&bufferSem); // release the lock

    return buf;
}

void populateArray(int N){
    srand(time(0));
    for (int i = 0; i < N; ++i) {
        Node* newNode = allocate(sizeof(NFAPI_CRC_INDICATION_PDU_T), 0); // Allocate memory for the structure

        if (head == NULL){ // If this is the first node in the queue
            head = tail = newNode;
        } else { // Otherwise, append it to the end of the list
            tail->next = newNode;
            tail = newNode;
        }
    }
}
```

This code creates a linked list that dynamically allocates `NFAPI_CRC_INDICATION_PDU_T` structures. The function `allocate()` is used to ensure efficient memory usage by retrying allocation up to 5 times with exponential backoff between attempts if the first attempt fails. Concurrency control is achieved using a semaphore, which ensures that only one thread can modify the buffer and its statistics at a time. A linked list is used instead of an array for better performance in high-concurrency environments as the size of the queue isn't fixed. 

Please note that due to the complexity of the task, many features described above have been simplified. For instance, the structure `NFAPI_CRC_INDICATION_PDU_T` is left without details and byte order handling hasn't been implemented. Also, logging system, error checking for buffer overflows, and thread-safe queue aren't shown in this code snippet.
