  pthread_mutex_lock(&lock);

  // Validate the signal report before adding it to the hash table.
  if (report->frequency < MINIMUM_FREQUENCY || report->frequency > MAXIMUM_FREQUENCY) {
    pthread_mutex_unlock(&lock);
    syslog(LOG_ERR, "Invalid frequency in signal report: %d", report->frequency);
