#include <stdlib.h>
#include <time.h>

#define MAX_SESSIONS 5000

typedef struct Session {
    int id;
    time_t loginTimestamp;
    time_t lastActivityTimestamp;
    double duration;
    enum Status { ACTIVE, EXPIRED } status;
} Session;

Session sessions[MAX_SESSIONS];
int sessionCount = 0;
double expirationWindow = 180.0;  // in seconds
double smoothingFactor = 0.5;

void addSession(int id) {
    if (sessionCount >= MAX_SESSIONS) return;

    Session* newSession = malloc(sizeof(Session));
    newSession->id = id;
    time(&newSession->loginTimestamp);
    newSession->lastActivityTimestamp = newSession->loginTimestamp;
    newSession->duration = 0.0;
    newSession->status = ACTIVE;

    sessions[sessionCount++] = *newSession;
}

void removeSession(int id) {
    for (int i = 0; i < sessionCount; i++) {
        if (sessions[i].id == id) {
            free(&sessions[i]);
            sessions[i] = sessions[--sessionCount];
            break;
        }
    }
}

void iterateSessions() {
    for (int i = 0; i < sessionCount; i++) {
        double diff = difftime(time(NULL), sessions[i].lastActivityTimestamp);
        if (diff > expirationWindow) {
            sessions[i].status = EXPIRED;
            logSessionChange(&sessions[i], "Expired due to inactivity");
        } else {
            sessions[i].duration *= smoothingFactor;  // Smooth duration using a moving average.
        }
    }
}

void garbageCollect() {
    for (int i = 0; i < sessionCount; i++) {
        if (sessions[i].status == EXPIRED) {
            free(&sessions[i]);
            sessions[i] = sessions[--sessionCount];
        }
    }
}
``` 
