#include "blueslip.h"  // Assume this exists

typedef struct {
    int key;
    long offset;
} record;

typedef struct {
    char *user_id;
    time_t last_login_time;
    char *preferences;
    char **activity_log;
} USER_PROFILE_DATA;

#define HASHSIZE 101
static record* hashtab[HASHSIZE];
pthread_mutex_t locks[HASHSIZE] = PTHREAD_MUTEX_INITIALIZER;

unsigned hash(int key) {
    return key % HASHSIZE;
}

record *lookup(int key, int create, record *data){
    unsigned int slot = hash(key);

    pthread_mutex_lock(&locks[slot]);
    record* rec = hashtab[slot];
    while (rec != NULL && rec->key != key) {
        rec = rec->next;
    }
    if(rec == NULL && create){
        rec = (record*) malloc(sizeof(record));
        if(rec == NULL || data == NULL){
            return NULL;  // Out of memory, couldn't create.
        }
        *rec = *data;
        rec->next = hashtab[slot];
        hashtab[slot] = rec;
    }
    pthread_mutex_unlock(&locks[slot]);

    return rec;  // Found.
}

int manageTests(char* modulePath, void (*testCallback)(void)) {
    void *moduleHandle = dlopen(modulePath, RTLD_LAZY);
    if (!moduleHandle) {
        printf("Failed to load module\n");
        return 1;
    }

    // Initialize the hashtable with random values.
    srand(time(NULL));
    for (int i = 0; i < 100; ++i){
        record data = { .key=rand(), .offset=rand() };
        if(!lookup(data.key, 1, &data)){
            printf("Failed to initialize hash table\n");
            return 1;
        }
    }

    for (int i = 0; i < 3; ++i) {  // Retry up to 3 times.
        testCallback();

        if(blueslip_reset()){
            printf("Failed to reset blueslip\n");
            return 1;
        }
    }

    if (dlclose(moduleHandle)) {
        printf("Failed to close module\n");
        return 1;
    }

    return 0;
}
```

