typedef struct {
    int FRAME_TIMESTAMP;
    size_t FRAME_SIZE;
    char* SOURCE_ID;
    char* FRAME_TYPE;
} MEDIA_FRAME_METADATA;

/* Helper function to allocate memory for a single frame */
MEDIA_FRAME_METADATA* createFrame(int timestamp, size_t size, const char* sourceId, const char* type) {
    MEDIA_FRAME_METADATA* frame = malloc(sizeof(MEDIA_FRAME_METADATA));
    if (frame == NULL) {
        return NULL; // Handle memory allocation failure
    }

    /* Assign values to the struct */
    frame->FRAME_TIMESTAMP = timestamp;
    frame->FRAME_SIZE = size;

    /* Allocate and copy source ID string */
    frame->SOURCE_ID = malloc(strlen(sourceId) + 1); 
    if (frame->SOURCE_ID == NULL) {
        freeFrame(frame); // Free already allocated memory on error
        return NULL; // Handle memory allocation failure
    }
    strcpy(frame->SOURCE_ID, sourceId);

    /* Allocate and copy frame type string */
    frame->FRAME_TYPE = malloc(strlen(type) + 1); 
    if (frame->FRAME_TYPE == NULL) {
        freeFrame(frame); // Free already allocated memory on error
        return NULL; // Handle memory allocation failure
    }
    strcpy(frame->FRAME_TYPE, type);

    return frame;
}

/* Helper function to free a single frame */
void freeFrame(MEDIA_FRAME_METADATA* frame) {
    if (frame != NULL) {
        /* Free allocated strings first to avoid memory leakage */
        free(frame->SOURCE_ID); 
        free(frame->FRAME_TYPE);

        /* Then, free the struct itself */
        free(frame); 
    }
}
```

Remember, this is a simplified example and does not fully account for all the requirements you mentioned in your task. A complete implementation would be much larger and more complex than can be covered here, but hopefully, this gives you an idea of how to start tackling such tasks.
