CallSessionInfo_t *sessionArray = NULL;
int arraySize = 0, arrayCapacity = 0;

/* Define your functions here */
void addNewSession(CallSessionInfo_t session) {
    pthread_mutex_lock(&lock);
    if (arraySize == arrayCapacity) {
        /* If the array is full, double its capacity */
        arrayCapacity = arrayCapacity ? arrayCapacity * 2 : 1;
        sessionArray = realloc(sessionArray, arrayCapacity * sizeof(CallSessionInfo_t));
    }
    sessionArray[arraySize++] = session; /* Add the new session to the array */
    pthread_mutex_unlock(&lock);
}

void removeSessionByID(int id) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < arraySize; i++) {
        if (sessionArray[i].id == id) { /* If the session ID matches, shift all subsequent sessions */
            memmove(sessionArray + i, sessionArray + i + 1, (arraySize - i - 1) * sizeof(CallSessionInfo_t));
            arraySize--;
            break;
        }
    }
    pthread_mutex_unlock(&lock);
}

void updateSessionByID(int id, CallSessionInfo_t newData) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < arraySize; i++) {
        if (sessionArray[i].id == id) { /* If the session ID matches, update the session info */
            sessionArray[i] = newData;
            break;
        }
    }
    pthread_mutex_unlock(&lock);
}
