int hash(int key) {
    return abs(key % TABLE_SIZE);
}

HTNode* create_item(int key, void *value) {
    HTNode* new_node = malloc(sizeof(HTNode));

    new_node->key = key;
    new_node->value = value;
    new_node->next = NULL;

    return new_node;  // return a pointer to the new node
}

void insert(int key, void *value) {
    int hashIndex = hash(key);
    pthread_mutex_lock(&lock);
    HTNode* new_node = create_item(key, value);

    // The head of the list at this index will be our last node
    HTNode* temp_node = hash_table[hashIndex];
    while (temp_node != NULL) {
        if (strcmp(temp_node->key, key) == 0) {
            printf("Key already exists\n");
            return;
        }
        temp_node = temp_node->next;
    }

    new_node->next = hash_table[hashIndex];
    hash_table[hashIndex] = new_node;

    pthread_mutex_unlock(&lock);
}

