    handle = dlopen("module.so", RTLD_LAZY);
    testFunction = dlsym(handle, "test");

    for (int i = 0; i < numRecords; i++) {
        char* result = (*testFunction)(records[i], 5000); // timeout is in ms

        int retryCount = 0;
        while (strcmp(result, "FAIL") == 0 && retryCount < 3) {
            printf("Retrying test...\n");
            result = (*testFunction)(records[i], 5000); // timeout is in ms
            retryCount++;
        }

        if (strcmp(result, "PASS") == 0) {
            printf("Test passed!\n");
            insert(records[i].key, records[i]);
        } else {
            printf("Test failed!\n");
        }
    }

    // Reset blueslip and log details here...
}
