        var rand = new Random();

        for (var i = 0; i < array.Length - 1; i++)
        {
            var j = rand.Next(i, array.Length);

            // swap elements at indices i and j
            var temp = array[i];
            array[i] = array[j];
            array[j] = temp;
        }
    }

    public void ResetRange(int minValue, int maxValue)
    {
        if (minValue > maxValue) 
            throw new ArgumentException("Minimum value should be less than or equal to maximum value.");

        this.minValue = minValue;
        this.maxValue = maxValue;
    }

