    public int Latency { get; set; }
    public int Throughput { get; set; }
}

public static List<NetworkInterfaceStats> DeserializeNetworkStats(string filePath) 
{
    var statsList = new List<NetworkInterfaceStats>();

    try 
    {
        using (Stream stream = File.OpenRead(filePath))
        {
            BinaryFormatter deserializer = new BinaryFormatter();

            while (stream.Position < stream.Length) 
            {
                NetworkInterfaceStats stats = (NetworkInterfaceStats)deserializer.Deserialize(stream);
                statsList.Add(stats);
            }
        }
    } 
    catch (Exception ex) 
    {
        // Log exception for debugging and recovery purposes, set default values to ensure system stability.
        Debug.WriteLine("Failed to deserialize network stats: " + ex.Message);
        return new List<NetworkInterfaceStats>();
    }

    return statsList.OrderBy(stats => stats.SequenceNumber).ToList();
}

public class NetworkMonitor 
{
    private readonly object _lock = new object();
    private Thread _monitorThread;
    private bool _isRunning;

    public void StartMonitoring() 
    {
        lock (_lock) 
        {
            if (!_isRunning) 
            {
                _isRunning = true;
                _monitorThread = new Thread(Monitor);
                _monitorThread.Start();
            }
        }
    }

    public void StopMonitoring() 
    {
        lock (_lock) 
        {
            if (_isRunning) 
            {
