```c
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <errno.h>

typedef enum {
    STATE1,
    STATE2,
    STATE3
} state_t;

typedef struct {
    int PARAM_ID;
    int DEFAULT_VALUE;
    int CURRENT_VALUE;
    state_t STATE;
} CONFIGURATION_PARAM_T;

typedef struct {
    CONFIGURATION_PARAM_T* params;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} ConfigManager;

ConfigManager* create_manager(size_t initialSize) {
    ConfigManager* manager = malloc(sizeof(ConfigManager));
    if (manager == NULL) {
        return NULL;
    }

    manager->params = calloc(initialSize, sizeof(CONFIGURATION_PARAM_T));
    if (manager->params == NULL) {
        free(manager);
        return NULL;
    }

    manager->capacity = initialSize;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroy_manager(ConfigManager* manager) {
    free(manager->params);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_param(ConfigManager* manager, CONFIGURATION_PARAM_T param) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count >= manager->capacity) {
        size_t newCapacity = manager->capacity * 2;
        CONFIGURATION_PARAM_T* newParams = realloc(manager->params, newCapacity * sizeof(CONFIGURATION_PARAM_T));
        if (newParams == NULL) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // out of memory
        }

        manager->params = newParams;
        manager->capacity = newCapacity;
    }

    manager->params[manager->count++] = param;

    pthread_mutex_unlock(&manager->lock);

    return 0; // success
}

// similar logic for update_param, delete_param and others

void serialize(ConfigManager* manager, FILE* file) {
    pthread_mutex_lock(&manager->lock);

    fwrite(&manager->count, sizeof(size_t), 1, file);
    fwrite(manager->params, sizeof(CONFIGURATION_PARAM_T), manager->count, file);

    pthread_mutex_unlock(&manager->lock);
}

ConfigManager* deserialize(FILE* file) {
    size_t count;
    fread(&count, sizeof(size_t), 1, file);

    ConfigManager* manager = create_manager(count * 2);
    if (manager == NULL) {
        return NULL;
    }

    fread(manager->params, sizeof(CONFIGURATION_PARAM_T), count, file);
    manager->count = count;

    return manager;
}
```
In this code, the `ConfigManager` structure is used to hold the array of structures. A mutex is used for locking access to this shared data in a thread-safe manner. Additions to the array are checked against capacity and dynamically resized as necessary. 

Serialization and deserialization use file I/O, with memory addresses serialized as raw binary data (`fwrite()`). Deserialization then allocates sufficient space for the new structures based on the saved count. 

Note that this is a simplified version of what you're asking for. Error handling would need to be added for out-of-bounds access, invalid states, and any other potential issues. Compacting memory allocation could be implemented by sorting the array periodically using `qsort()` with your custom comparator, then reallocating a new contiguous block of memory for the structures after copying over all valid entries from the old space.
