  let accumulator = initialValue;

  for (let i = 0; i < dataArray.length; ++i) {
    try {
      // call an external service to get the current value of a resource and await its response before proceeding
      const resourceData = await fetchFromService();

      accumulator = reducerFunction(accumulator, dataArray[i], resourceData);
