```csharp
using System;
using System.Collections.Concurrent;
using System.Data;
using System.Data.SqlClient;
using System.Threading.Tasks;

public class SqlCommandManager
{
    private readonly ConcurrentQueue<string> _commandQueue = new ConcurrentQueue<string>();

    public void CreateParameterizedSqlCommand(List<object[]> values, string connectionString, string commandText)
    {
        Parallel.ForEach(values, (valueArray) =>
        {
            using (var connection = new SqlConnection(connectionString))
            {
                var command = new SqlCommand(commandText, connection);

                for (int i = 0; i < valueArray.Length; i++)
                {
                    string paramName = $"@p{i}";

                    if (!command.Parameters.Contains(paramName))
                    {
                        command.Parameters.AddWithValue(paramName, valueArray[i]);
                    }
                }

                connection.Open();

                using (var reader = command.ExecuteReader())
                {
                    while (reader.Read())
                    {
                        _commandQueue.Enqueue(reader.GetString(0));
                    }
                }
            }
        });
    }
}
``` 

This method creates a separate SQL connection for each valueArray using parallel foreach, which can potentially speed up the execution when dealing with large lists of values. It uses `ConcurrentQueue` to safely enqueue created commands without causing data races or stack overflows.
