class MemoryPool {
public:
    void* Allocate() {
        std::lock_guard<std::mutex> lock(mtx);
        if (freeList_.empty()) {
            void* ptr = ::operator new(sizeof(T), std::nothrow);
            if (!ptr) return nullptr;
